INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西能做的事或用处。", "primary_collocate": null, "pronunciation": "gōng néng", "ipa": "kʊŋ˥ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这把小刀有七种功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表除了看时间，还有拍照功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子的功能是放药。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机的烘干功能很好用。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个按钮的功能吗？", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子有保温功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的旧手机功能很少。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件功能太多，我学不会。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的闹钟功能每天叫我起床。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调有除湿功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "多功能", "label": "复合"}, {"form": "功能键", "label": "复合"}], "register": "通用", "sense_fingerprint": "物品或设备能做的事、具体用处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 4 words above tier T1 (max 2): 这台 (Zipf 3.53), 洗衣机 (Zipf 3.69), 烘干 (Zipf 3.06), 好用 (Zipf 3.74)']::text[], '09683557-dab8-41ba-b863-ee314a4fd40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "功能", "is_correct": true, "explanation": "指小刀能做的事，「有七种功能」符合句意。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「有七种重量」说不通，重量不是小刀能做的事。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「有七种价格」说不通，价格不是小刀能做的事。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是东西的大小，不是用途，「有七种体积」说不通。"}], "explanations": {"功能": "指小刀能做的事，「有七种功能」符合句意。", "重量": "语义：「有七种重量」说不通，重量不是小刀能做的事。", "价格": "语义：「有七种价格」说不通，价格不是小刀能做的事。", "体积": "语义：体积是东西的大小，不是用途，「有七种体积」说不通。"}, "sentence_index": 0, "correct_answer": "功能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机有两条烘干功能。", "explanation": "量词错误：「功能」应搭配〈种〉或〈项〉，「条」用于细长的东西。"}, {"text": "这个方案起了很大功能。", "explanation": "这里应该用〈作用〉。「起作用」是固定搭配，「功能」不能与「起」搭配。"}, {"text": "这次行动取得了明显功能。", "explanation": "这里应该用〈成效〉。「取得成效」是固定搭配，「功能」不能被「取得」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "功能", "is_correct": true, "explanation": "指旧手机的用途，「功能很少」符合句意。"}, {"text": "外观", "is_correct": false, "explanation": "语义：外观是东西的样子，不能用「很少」说外观的多少。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄很少」说不通，年龄不表示手机用途的多少。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指性情，与手机能做的事无关，「脾气很少」说不通。"}], "explanations": {"功能": "指旧手机的用途，「功能很少」符合句意。", "外观": "语义：外观是东西的样子，不能用「很少」说外观的多少。", "年龄": "语义：「年龄很少」说不通，年龄不表示手机用途的多少。", "脾气": "语义：脾气指性情，与手机能做的事无关，「脾气很少」说不通。"}, "sentence_index": 6, "correct_answer": "功能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告起了很大功能。", "explanation": "这里应该用〈作用〉。「起作用」是固定搭配，「功能」不能与「起」搭配。"}, {"text": "这台空调有两根功能。", "explanation": "量词错误：「根」用于细长的东西，「功能」应搭配〈种〉或〈项〉。"}, {"text": "这次事故对他功能很大。", "explanation": "这里应该用〈影响〉。「功能」指事物的用途，不能表示对人的作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把小刀有三条功能。", "corrected_sentence": "这把小刀有三种功能。", "error_description": "量词错误：「功能」应搭配「种」或「项」，「条」用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
