INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22114, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改动文章、文件或方案中不合适的地方。", "primary_collocate": null, "pronunciation": "xiū gǎi", "ipa": "ɕjoʊ˥ kaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师让我修改这篇作文。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这个句子修改一下。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修改了三次报告。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想修改一下这个方案。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师把图修改了好几次。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个文件不能随便修改。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修改完以后，请再发给我。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求修改合同里的日期。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直在修改自己的演讲稿。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章还需要修改，错字太多。", "target_word": "修改", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修改了", "label": "体标"}, {"form": "修改过", "label": "体标"}], "register": "中性", "sense_fingerprint": "改动文章、文件或方案中不合适的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修改", "is_correct": true, "explanation": "正确。“修改”指改动文章，老师让我改这篇作文。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物咽下去，不能用来对文章做处理。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：呼吸是不及物动词，不能直接带“这篇作文”作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "配价：散步是不及物动词，不能带“这篇作文”作宾语。"}], "explanations": {"修改": "正确。“修改”指改动文章，老师让我改这篇作文。", "吃": "语义：吃是把食物咽下去，不能用来对文章做处理。", "呼吸": "配价：呼吸是不及物动词，不能直接带“这篇作文”作宾语。", "散步": "配价：散步是不及物动词，不能带“这篇作文”作宾语。"}, "sentence_index": 0, "correct_answer": "修改"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑坏了，需要修改。", "explanation": "这里应该用〈修理〉。修改用于文字、计划等的改动，机器坏了要说〈修理〉。"}, {"text": "园丁正在修改树枝。", "explanation": "这里应该用〈修剪〉。修改指改动文字或方案，剪掉树枝要说〈修剪〉。"}, {"text": "他把房间修改得很整齐。", "explanation": "这里应该用〈整理〉。修改用于文字或计划，收拾房间要说〈整理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修改", "is_correct": true, "explanation": "正确。“修改完”指把文章改好，改完以后再发给对方。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗是清洗东西，与修改文件无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，不是对文件作处理。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡是睡觉，与修改文件无关，“睡完以后，请再发给我”说不通。"}], "explanations": {"修改": "正确。“修改完”指把文章改好，改完以后再发给对方。", "洗": "语义：洗是清洗东西，与修改文件无关。", "唱": "语义：唱是唱歌，不是对文件作处理。", "睡": "语义：睡是睡觉，与修改文件无关，“睡完以后，请再发给我”说不通。"}, "sentence_index": 6, "correct_answer": "修改"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府修改了一座桥。", "explanation": "这里应该用〈修建〉。修改是改动已有的文字或计划，建造桥梁要说〈修建〉。"}, {"text": "我的牙齿需要修改一下。", "explanation": "这里应该用〈矫正〉。修改用于文字、计划等，牙齿不齐要说〈矫正〉。"}, {"text": "他的修改很高。", "explanation": "这里应该用〈修养〉。修改是改动文字或计划，形容人的素养要说〈修养〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你修改一下了这个句子。", "corrected_sentence": "请你修改一下这个句子。", "error_description": "错误：请求别人做事的句子里，“修改一下”后面不能加“了”，应说“请你修改一下这个句子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经这份报告修改完了。", "corrected_sentence": "我已经把这份报告修改完了。", "error_description": "错误：“把”字句漏掉了“把”。“修改完”的宾语“这份报告”前面要加“把”，应说“我已经把这份报告修改完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
