INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22117, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很久以前的东西或想法，和现在的不太一样。", "primary_collocate": null, "pronunciation": "gǔ diǎn", "ipa": "ku˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的想法很古典，不太适合现在。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的穿着很古典。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的家具都很古典。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢古典的生活方式。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对爱情的看法比较古典。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种古典的做法现在很少有人用。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的古典观念让年轻人不理解。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店的样子很古典。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿了一件古典的长裙。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的方式有点古典。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "古典主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "样式、想法等像很久以前的，和现在不太一样（古典的想法、很古典）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09683557-dab8-41ba-b863-ee314a4fd40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古典", "is_correct": true, "explanation": "正确。“他的想法很古典”指想法像很久以前的，此处应填“古典”。"}, {"text": "时髦", "is_correct": false, "explanation": "语义：“时髦”指跟上当下潮流，与“不太适合现在”相冲突。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容天气或环境，不用来形容想法。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不修饰想法。"}], "explanations": {"古典": "正确。“他的想法很古典”指想法像很久以前的，此处应填“古典”。", "时髦": "语义：“时髦”指跟上当下潮流，与“不太适合现在”相冲突。", "潮湿": "搭配：“潮湿”形容天气或环境，不用来形容想法。", "响亮": "搭配：“响亮”形容声音，不修饰想法。"}, "sentence_index": 0, "correct_answer": "古典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的心情很古典。", "explanation": "这里应该用〈愉快〉。古典形容样式或想法像很久以前，不用于形容心情。"}, {"text": "雨声很古典。", "explanation": "这里应该用〈清脆〉。古典形容样式、想法像很久以前，不用于形容声音。"}, {"text": "这份工作的压力很古典。", "explanation": "这里应该用〈沉重〉。古典不用于形容压力的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古典", "is_correct": true, "explanation": "正确。“爷爷的古典观念”指想法像很久以前的，此处应填“古典”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不修饰观念。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”形容心情，不指观念的类型。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不用来修饰观念。"}], "explanations": {"古典": "正确。“爷爷的古典观念”指想法像很久以前的，此处应填“古典”。", "清脆": "搭配：“清脆”形容声音，不修饰观念。", "紧张": "语义：“紧张”形容心情，不指观念的类型。", "辣": "搭配：“辣”形容味道，不用来修饰观念。"}, "sentence_index": 6, "correct_answer": "古典"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的呼吸很古典。", "explanation": "这里应该用〈平稳〉。古典不用于形容呼吸的节奏。"}, {"text": "这杯咖啡很古典。", "explanation": "这里应该用〈苦〉。古典不用于形容味道。"}, {"text": "今天的风很古典，吹得人很舒服。", "explanation": "这里应该用〈柔和〉。古典不用于形容风的感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间的布置很的古典。", "corrected_sentence": "这个房间的布置很古典。", "error_description": "多加了「的」：程度副词「很」与形容词之间不能插入「的」，删去「的」，应为「很古典」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件旗袍的样式非常很古典。", "corrected_sentence": "这件旗袍的样式非常古典。", "error_description": "程度副词重复：「非常」和「很」不能连用来修饰「古典」，删去「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
