INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22120, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是再往前走一步，或者做得更多。", "primary_collocate": null, "pronunciation": "jìn yí bù", "ipa": "tɕin˥˩ i˧˥ pu˥˩", "syllable_count": 3, "sentences": [{"text": "我们要进一步学习汉语。", "target_word": "进一步", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司想进一步提高产品的质量。", "target_word": "进一步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方进一步加强了联系。", "target_word": "进一步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们进一步了解这个问题。", "target_word": "进一步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过检查，医生进一步确定了病情。", "target_word": "进一步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府决定进一步减少污染。", "target_word": "进一步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事还要进一步讨论。", "target_word": "进一步", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看了这些资料，我对这个问题有了进一步的了解。", "target_word": "进一步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校打算进一步改善学生的生活条件。", "target_word": "进一步", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们进一步说明了自己的计划。", "target_word": "进一步", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "進一步", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在已有基础上再向前一步，做得更多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进一步", "is_correct": true, "explanation": "正确：「进一步」表示在已有基础上再推进一步，与「要学习汉语」相合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：「从来」指到目前为止一直如此，与表示将来的「要」矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经」表示动作已完成，与表示将来的「要」矛盾。"}, {"text": "业已", "is_correct": false, "explanation": "语义：「业已」表示动作已经完成，与表示将来的「要」矛盾，句子不通。"}], "explanations": {"进一步": "正确：「进一步」表示在已有基础上再推进一步，与「要学习汉语」相合。", "从来": "语义：「从来」指到目前为止一直如此，与表示将来的「要」矛盾。", "已经": "语义：「已经」表示动作已完成，与表示将来的「要」矛盾。", "业已": "语义：「业已」表示动作已经完成，与表示将来的「要」矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "进一步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他进一步出发了。", "explanation": "这里应该用〈马上〉。「进一步」表示在程度或范围上再推进，不表示动作紧接着发生。"}, {"text": "我们进一步吃饭了。", "explanation": "这里应该用〈一起〉。「进一步」不表示共同做某事，表示共同要用「一起」。"}, {"text": "他进一步考上了大学。", "explanation": "这里应该用〈终于〉。「进一步」表示程度推进，不表示经过努力后的最终结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进一步", "is_correct": true, "explanation": "正确：「进一步」表示在原有计划上再向前推进，与「这件事还要……讨论」相合。"}, {"text": "突然", "is_correct": false, "explanation": "语义：「突然」表示事情出乎意料地发生，与「还要」所表示的计划中的讨论不合。"}, {"text": "早就", "is_correct": false, "explanation": "语义：「早就」表示很久以前已经如此，与「还要」的将来意思矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」表示过去发生过，与「还要」所表示的尚未完成、仍需进行的意思矛盾。"}], "explanations": {"进一步": "正确：「进一步」表示在原有计划上再向前推进，与「这件事还要……讨论」相合。", "突然": "语义：「突然」表示事情出乎意料地发生，与「还要」所表示的计划中的讨论不合。", "早就": "语义：「早就」表示很久以前已经如此，与「还要」的将来意思矛盾。", "曾经": "语义：「曾经」表示过去发生过，与「还要」所表示的尚未完成、仍需进行的意思矛盾。"}, "sentence_index": 6, "correct_answer": "进一步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他进一步睡着了。", "explanation": "这里应该用〈很快〉。「进一步」表示在已有基础上再推进，不表示动作发生得快。"}, {"text": "这件衣服进一步漂亮。", "explanation": "这里应该用〈非常〉。「进一步」修饰动作的推进，不能直接修饰形容词表示程度高。"}, {"text": "他进一步出生了。", "explanation": "这里应该用〈刚刚〉。「进一步」表示在已有基础上再推进，「出生」是一次性的事件，要说「刚刚出生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要进一步了改进工作方法。", "corrected_sentence": "我们要进一步改进工作方法。", "error_description": "错误：「进一步了改进」，「了」为完成标记，不能插在副词「进一步」与动词「改进」之间；删去「了」，正确句为「我们要进一步改进工作方法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们进一步改进得设计。", "corrected_sentence": "他们进一步改进了设计。", "error_description": "错误：「改进得设计」，「得」是程度补语标记，后面需要描述性补语，这里表示动作完成，应用「了」；正确：「进一步改进了设计」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
