INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展的方向或变化的样子。", "primary_collocate": null, "pronunciation": "qū xiàng", "ipa": "tɕʰy˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们的阅读趋向和以前不一样了。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看一看天气的趋向，再决定去不去爬山。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想知道学生选课的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，明年的就业趋向不太乐观。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的发展趋向是越来越绿色。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很关心市场价格的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天记录股票的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图表清楚地显示了销售的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究气候变化的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在大家的饮食趋向更健康了。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨向", "label": "繁体"}, {"form": "趋向性", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "趋向|名词|事情发展的方向或变化的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋向", "is_correct": true, "explanation": "正确：“趋向”指阅读变化的方向或样子，与“和以前不一样了”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：阅读没有颜色，“阅读颜色”与“不一样了”的变化说法不相关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人体的高矮，与阅读的变化无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“阅读”不与“价格”搭配，“阅读价格”不能表达阅读的变化。"}], "explanations": {"趋向": "正确：“趋向”指阅读变化的方向或样子，与“和以前不一样了”相合。", "颜色": "语义：阅读没有颜色，“阅读颜色”与“不一样了”的变化说法不相关。", "身高": "语义：“身高”指人体的高矮，与阅读的变化无关。", "价格": "搭配：“阅读”不与“价格”搭配，“阅读价格”不能表达阅读的变化。"}, "sentence_index": 0, "correct_answer": "趋向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他朝着车站的趋向跑去。", "explanation": "这里应该用〈方向〉。“趋向”指事情发展的走向或样子，不指跑步时的具体方向。"}, {"text": "这台电脑的趋向很快，用起来很方便。", "explanation": "这里应该用〈速度〉。“趋向”指事情发展的方向，不指电脑运行的快慢。"}, {"text": "侦探很趋向，案子破得很快。", "explanation": "这里应该用〈聪明〉。“趋向”不能用来形容人的才智，形容人的才智要用聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋向", "is_correct": true, "explanation": "正确：“趋向”指股票变化的方向，与“记录股票的”相合。"}, {"text": "面积", "is_correct": false, "explanation": "语义：股票没有面积，“面积”与股票的变化情况不相关。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体占的空间，股票不能说有体积。"}, {"text": "温度", "is_correct": false, "explanation": "语义：股票不讲温度，“温度”无法作为股票变化情况被记录。"}], "explanations": {"趋向": "正确：“趋向”指股票变化的方向，与“记录股票的”相合。", "面积": "语义：股票没有面积，“面积”与股票的变化情况不相关。", "体积": "搭配：“体积”指物体占的空间，股票不能说有体积。", "温度": "语义：股票不讲温度，“温度”无法作为股票变化情况被记录。"}, "sentence_index": 6, "correct_answer": "趋向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的精神趋向很好。", "explanation": "这里应该用〈状态〉。“趋向”指事情发展的方向或变化的样子，人的精神情况要用“状态”。"}, {"text": "他说话的趋向很温和，大家都爱听。", "explanation": "这里应该用〈语气〉。“趋向”指事情发展的方向，说话的口气要用语气。"}, {"text": "他待人的趋向很热情，大家都爱找他。", "explanation": "这里应该用〈态度〉。“趋向”指事情发展的方向，待人的样子要用态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一张新的发展趋向。", "corrected_sentence": "这是一种新的发展趋向。", "error_description": "量词错误：“趋向”是抽象名词，应该用量词“种”，不能用“张”；“张”用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们看到了一根新的饮食趋向。", "corrected_sentence": "我们看到了一种新的饮食趋向。", "error_description": "量词错误：“趋向”是抽象名词，应该用量词“种”，不能用“根”；“根”多用于细长的物体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
