INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22124, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22124, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一天比一天更……", "primary_collocate": null, "pronunciation": "rì yì", "ipa": "ɻ̩˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "路上的车日益增多。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气日益寒冷。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在，环境问题日益重要。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系日益亲近。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语的人日益增加。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子日益懂事。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的生活日益方便。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力日益加大。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对中国文化的兴趣日益浓厚。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体日益健康。", "target_word": "日益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，表示程度一天天加深，多修饰变化的词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日益", "is_correct": true, "explanation": "正确：“日益”表示一天比一天更，与“车增多”的逐步变化相符。"}, {"text": "反复", "is_correct": false, "explanation": "语义：“反复”表示来回重复，与“日益增多”的持续变化不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与“增多”的持续变化不符。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”表示暗中进行，车辆增多是公开可见的，不能用“偷偷”。"}], "explanations": {"日益": "正确：“日益”表示一天比一天更，与“车增多”的逐步变化相符。", "反复": "语义：“反复”表示来回重复，与“日益增多”的持续变化不符。", "偶尔": "语义：“偶尔”表示间或发生，与“增多”的持续变化不符。", "偷偷": "语义：“偷偷”表示暗中进行，车辆增多是公开可见的，不能用“偷偷”。"}, "sentence_index": 0, "correct_answer": "日益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天他们日益和好了。", "explanation": "这里应该用〈终于〉。〈日益〉表示逐日加深，不能用于某一天发生的一次性事件。"}, {"text": "他日益哭了。", "explanation": "这里应该用〈突然〉。〈日益〉表示程度逐日加深，哭这种瞬间发生的动作不能用〈日益〉。"}, {"text": "这个城市日益保持安静。", "explanation": "这里应该用〈一直〉。〈日益〉表示逐日变化，不能修饰“保持不变”的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日益", "is_correct": true, "explanation": "正确：“日益”表示程度逐日加深，与“生活”逐渐便利相符。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反，这里前后没有出乎意料的情况。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”表示限定，“只方便”不构成通顺的搭配，不能描述生活的改善。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，这里生活变好是顺势发展，不是相反的情况。"}], "explanations": {"日益": "正确：“日益”表示程度逐日加深，与“生活”逐渐便利相符。", "偏偏": "语义：“偏偏”表示与预期相反，这里前后没有出乎意料的情况。", "只": "搭配：“只”表示限定，“只方便”不构成通顺的搭配，不能描述生活的改善。", "反而": "语义：“反而”表示与预期相反，这里生活变好是顺势发展，不是相反的情况。"}, "sentence_index": 6, "correct_answer": "日益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人日益到达。", "explanation": "这里应该用〈同时〉。〈日益〉表示逐日加深，不能表示两件事在同一时间发生。"}, {"text": "我们日益讨论问题。", "explanation": "这里应该用〈首先〉。〈日益〉表示程度逐日加深，不能表示先后顺序。"}, {"text": "这个孩子日益是学生。", "explanation": "这里应该用〈已经〉。〈日益〉表示程度逐日加深，不能修饰“是学生”这类身份判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的人口日益着减少。", "corrected_sentence": "这座城市的人口日益减少。", "error_description": "错误：“着”不能加在副词“日益”之后，“日益”后应直接接动词。正确：“日益减少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的游客很日益增多。", "corrected_sentence": "这个小镇的游客日益增多。", "error_description": "错误：“很”与“日益”都是修饰语，不能叠用，应去掉“很”，写作“日益增多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
