INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "观念就是你心里怎么想一件事。", "primary_collocate": null, "pronunciation": "guān niàn", "ipa": "kwan˥ njɛn˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷的观念和我的不一样。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很强的时间观念。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个观念太老了，现在没人接受。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书改变了她对钱的观念。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母要给孩子好的金钱观念。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家的家庭观念不同。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的观念变得越来越开放。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要改变这种旧观念。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的环保观念影响了全家人。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两代人在婚姻观念上常常不同。", "target_word": "观念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "旧观念", "label": "复合"}, {"form": "新观念", "label": "复合"}, {"form": "时间观念", "label": "复合"}], "register": "中性", "sense_fingerprint": "人对某件事长期形成的看法和想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观念", "is_correct": true, "explanation": "正确：“观念”指人对事情的看法和想法，与“不一样”的对比相合。"}, {"text": "非常", "is_correct": false, "explanation": "词性：“非常”是副词，不能放在“爷爷的”后面作名词使用。"}, {"text": "因为", "is_correct": false, "explanation": "词性：“因为”是连词，不能被“爷爷的”修饰。"}, {"text": "慢慢", "is_correct": false, "explanation": "词性：“慢慢”是副词，不能被“爷爷的”修饰作主语。"}], "explanations": {"观念": "正确：“观念”指人对事情的看法和想法，与“不一样”的对比相合。", "非常": "词性：“非常”是副词，不能放在“爷爷的”后面作名词使用。", "因为": "词性：“因为”是连词，不能被“爷爷的”修饰。", "慢慢": "词性：“慢慢”是副词，不能被“爷爷的”修饰作主语。"}, "sentence_index": 0, "correct_answer": "观念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的脸上露出了开心的观念。", "explanation": "这里应该用〈表情〉。观念是人对事情的看法，不能显露在脸上。"}, {"text": "这次旅行让我买了很多观念。", "explanation": "这里应该用〈纪念品〉。观念是人对事情的看法，不是能买的东西；旅行中买的是纪念品。"}, {"text": "她把这段童年的观念煮成了一碗汤。", "explanation": "这里应该用〈食材〉。观念是人对事情的看法，不能当食材来煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观念", "is_correct": true, "explanation": "正确：“观念”指人对事情的看法，年轻人的想法变得开放，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能说变得越来越开放。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能与“开放”搭配，“开放”多形容想法和态度。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”与“开放”的意思不合，句中说的是年轻人的想法。"}], "explanations": {"观念": "正确：“观念”指人对事情的看法，年轻人的想法变得开放，符合句意。", "身高": "体貌：“身高”指人的高矮，不能说变得越来越开放。", "年龄": "搭配：“年龄”不能与“开放”搭配，“开放”多形容想法和态度。", "声音": "语义：“声音”与“开放”的意思不合，句中说的是年轻人的想法。"}, "sentence_index": 6, "correct_answer": "观念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他制定了明年的观念。", "explanation": "这里应该用〈计划〉。制定的是计划或方案，观念是人的看法，不能制定。"}, {"text": "她的观念很开朗。", "explanation": "这里应该用〈性格〉。开朗形容人的性格，观念是看法，不能用开朗来形容。"}, {"text": "他把观念存进了银行。", "explanation": "这里应该用〈钱〉。存进银行的是钱，观念是看法，不能存入银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很强的环保观念。", "corrected_sentence": "他有一种很强的环保观念。", "error_description": "错误形式：“一只”；正确形式：“一种”。量词“只”多用于动物或成对的器官，“观念”应当用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈有一张很旧的观念。", "corrected_sentence": "妈妈有一种很旧的观念。", "error_description": "错误形式：“一张”；正确形式：“一种”。量词“张”用于纸、桌子等平面的东西，“观念”是抽象名词，应当用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "“局部”与“全面”相对，指只涉及一部分，与“全面的检查”相对。"}, {"text": "详细", "is_correct": false, "explanation": "“详细”强调细致，与“全面”不构成反义关系。"}, {"text": "深刻", "is_correct": false, "explanation": "“深刻”强调程度深，与“全面”不构成反义关系。"}, {"text": "精确", "is_correct": false, "explanation": "“精确”强调准确无误，与“全面”不构成反义关系。"}], "correct_answer": "局部", "explanations": {"局部": "“局部”与“全面”相对，指只涉及一部分，与“全面的检查”相对。", "详细": "“详细”强调细致，与“全面”不构成反义关系。", "深刻": "“深刻”强调程度深，与“全面”不构成反义关系。", "精确": "“精确”强调准确无误，与“全面”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "片面", "is_correct": true, "explanation": "“片面”指只看一部分，与“知识很全面”相对。"}, {"text": "深入", "is_correct": false, "explanation": "“深入”强调程度深，与“全面”不构成反义关系。"}, {"text": "渊博", "is_correct": false, "explanation": "“渊博”与“全面”意思相近，不是反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”指种类多、数量大，与“全面”不构成反义关系。"}], "correct_answer": "片面", "explanations": {"片面": "“片面”指只看一部分，与“知识很全面”相对。", "深入": "“深入”强调程度深，与“全面”不构成反义关系。", "渊博": "“渊博”与“全面”意思相近，不是反义关系。", "丰富": "“丰富”指种类多、数量大，与“全面”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "各个方面、各个部分都照顾到，没有遗漏。", "primary_collocate": null, "pronunciation": "quán miàn", "ipa": "tɕʰɥɛn³⁵ mjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "这份报告写得很全面。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师全面检查了我的作业。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题的看法不全面。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给他做了全面的检查。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要全面了解这里的情况。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书全面地介绍了中国的历史。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想得太不全面了。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习要全面发展,不能只学数学。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对新工人进行了全面的训练。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的知识很全面,什么都懂。", "target_word": "全面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全面地", "label": "状语"}, {"form": "不全面", "label": "否定"}], "register": "中性", "sense_fingerprint": "各个方面都照顾到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d9ab088-f832-4c2b-8bdc-c6dfd9f23bbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全面", "is_correct": true, "explanation": "“全面”指各方面都照顾到，“这份报告写得很全面”成立。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容文章或报告。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容人或动物的体型，不能用来形容报告。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不用来评价写作。"}], "explanations": {"全面": "“全面”指各方面都照顾到，“这份报告写得很全面”成立。", "甜": "搭配：“甜”形容味道，不能用来形容文章或报告。", "胖": "语义：“胖”形容人或动物的体型，不能用来形容报告。", "咸": "搭配：“咸”形容味道，不用来评价写作。"}, "sentence_index": 0, "correct_answer": "全面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全面观众都站了起来。", "explanation": "这里应该用〈全场〉。整个场地的观众要用“全场”；“全面”指方面都顾到，不用于修饰观众。"}, {"text": "他个子很全面。", "explanation": "这里应该用〈高〉。形容身高要用“高”；“全面”指方面或范围都包括，不能形容身高。"}, {"text": "这件事全面是他的错。", "explanation": "这里应该用〈完全〉。表示彻底、毫无例外用“完全”；“全面”指方面，不能用于判断是非。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全面", "is_correct": true, "explanation": "“全面”指想问题周到、不遗漏，“你想得太不全面了”成立。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”形容高度，不能形容想法的周全程度。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”形容温度，不能形容想法。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不用来形容想法。"}], "explanations": {"全面": "“全面”指想问题周到、不遗漏，“你想得太不全面了”成立。", "高": "语义：“高”形容高度，不能形容想法的周全程度。", "烫": "语义：“烫”形容温度，不能形容想法。", "辣": "搭配：“辣”形容味道，不用来形容想法。"}, "sentence_index": 6, "correct_answer": "全面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他全面都湿透了。", "explanation": "这里应该用〈全身〉。整个身体用“全身”；“全面”指方面都顾到，不指身体。"}, {"text": "他全面以赴地准备比赛。", "explanation": "这里应该用〈全力〉。用尽力气去做用“全力以赴”；“全面”指方面，不能说“全面以赴”。"}, {"text": "汽车全面前进。", "explanation": "这里应该用〈全速〉。速度最快用“全速”；“全面”不能形容速度或前进的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查太很全面。", "corrected_sentence": "这次调查很全面。", "error_description": "错误：程度副词“很”前多加了“太”，两个程度副词不能连用。正确应为“这次调查很全面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师全面得讲解了这道题。", "corrected_sentence": "老师全面地讲解了这道题。", "error_description": "错误：修饰动词“讲解”的状语后应用“地”，不用“得”。“得”用于动词或形容词之后的补语。正确应为“全面地讲解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
