INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "浪漫主义是一种想法，觉得世界很美好，像童话故事一样。", "primary_collocate": null, "pronunciation": "làng màn zhǔ yì", "ipa": "lɑŋ˥˩ man˥˩ ʈʂu˨˩˦ i˥˩", "syllable_count": 4, "sentences": [{"text": "他身上有一种浪漫主义情怀，总觉得生活像童话。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "她的生活里总有一点浪漫主义色彩。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "他对未来怀着一份浪漫主义憧憬。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "有人说她骨子里有浪漫主义情怀。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "他总用一种浪漫主义情怀看待世界。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "浪漫主义情怀让她相信，世界很美好。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "他身上浓厚的浪漫主义色彩，常让朋友们会心一笑。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "你的浪漫主义情怀很可贵，但这份工作需要踏实。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "她怀着浪漫主义情怀去旅行。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}, {"text": "年轻时他身上的浪漫主义色彩很浓。", "target_word": "浪漫主义", "complexity_tier": "T3", "furigana": "làng màn zhǔ yì", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪漫主義", "label": "繁体"}, {"form": "浪漫主义者", "label": "复合"}], "register": "中性", "sense_fingerprint": "认为世界美好、像童话一样的人生态度与想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09683557-dab8-41ba-b863-ee314a4fd40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪漫主义", "is_correct": true, "explanation": "正确。“他身上有一种浪漫主义情怀，总觉得生活像童话”中，此处应填“浪漫主义”。"}, {"text": "现实", "is_correct": false, "explanation": "语义：“现实”与“总觉得生活像童话”的态度相反。"}, {"text": "机械", "is_correct": false, "explanation": "语义：“机械”指冷冰冰的操作，与童话般的生活感受冲突。"}, {"text": "农业", "is_correct": false, "explanation": "搭配：“农业情怀”不是常用搭配，与“情怀”一词不相配。"}], "explanations": {"浪漫主义": "正确。“他身上有一种浪漫主义情怀，总觉得生活像童话”中，此处应填“浪漫主义”。", "现实": "语义：“现实”与“总觉得生活像童话”的态度相反。", "机械": "语义：“机械”指冷冰冰的操作，与童话般的生活感受冲突。", "农业": "搭配：“农业情怀”不是常用搭配，与“情怀”一词不相配。"}, "sentence_index": 0, "correct_answer": "浪漫主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有人说她骨子里有浪漫主义的数据。", "explanation": "这里应该用〈情怀〉。浪漫主义指看待世界的态度，不能与「数据」搭配。"}, {"text": "有人说她是一个浪漫主义。", "explanation": "这里应该用〈浪漫主义者〉。浪漫主义指态度或思潮，指人要加“者”。"}, {"text": "这台电脑的浪漫主义很快。", "explanation": "这里应该用〈速度〉。浪漫主义指把世界看得美好的想法，不能说电脑的浪漫主义快不快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪漫主义", "is_correct": true, "explanation": "正确。“他身上浓厚的浪漫主义色彩”指带有理想化情调的气质，此处应填“浪漫主义”。"}, {"text": "硝烟", "is_correct": false, "explanation": "语义：硝烟与“会心一笑”的轻松氛围冲突。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒与句中描述的气质无关，语义不通。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：“色彩”前多用颜色或风格词，煤炭只表示物料，不作色彩的修饰语。"}], "explanations": {"浪漫主义": "正确。“他身上浓厚的浪漫主义色彩”指带有理想化情调的气质，此处应填“浪漫主义”。", "硝烟": "语义：硝烟与“会心一笑”的轻松氛围冲突。", "病毒": "语义：病毒与句中描述的气质无关，语义不通。", "煤炭": "搭配：“色彩”前多用颜色或风格词，煤炭只表示物料，不作色彩的修饰语。"}, "sentence_index": 6, "correct_answer": "浪漫主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和女友之间的浪漫主义很坚硬。", "explanation": "这里应该用〈甜蜜〉。浪漫主义形容情怀或氛围，不能与「很坚硬」搭配。"}, {"text": "这双鞋的浪漫主义是四十二号。", "explanation": "这里应该用〈尺码〉。浪漫主义是一种想法，不能表示鞋的大小。"}, {"text": "他对数字的计算很有浪漫主义。", "explanation": "这里应该用〈精确〉。浪漫主义指重视感情与想象的态度，不用于形容计算的准确性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对爱情很有浪漫主义地情怀。", "corrected_sentence": "他对爱情很有浪漫主义情怀。", "error_description": "错误形式“浪漫主义地情怀”，正确形式“浪漫主义情怀”。“地”用于修饰动词、形容词，修饰名词“情怀”时不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年轻时他是一个浪漫主义。", "corrected_sentence": "年轻时他是一个浪漫主义者。", "error_description": "错误形式“一个浪漫主义”，正确形式“一个浪漫主义者”。浪漫主义指一种想法，指人要说“浪漫主义者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀疏", "is_correct": true, "explanation": "正确：稀疏指数量少、间隔大，与“密集”正相反。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地不硬，和“密集”没有反义关系。"}, {"text": "轻快", "is_correct": false, "explanation": "轻快形容动作或节奏灵活，和“密集”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足，和“密集”没有反义关系。"}], "correct_answer": "稀疏", "explanations": {"稀疏": "正确：稀疏指数量少、间隔大，与“密集”正相反。", "柔软": "柔软形容质地不硬，和“密集”没有反义关系。", "轻快": "轻快形容动作或节奏灵活，和“密集”没有反义关系。", "明亮": "明亮形容光线充足，和“密集”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
