INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很多东西挤在一起，靠得很近。", "primary_collocate": null, "pronunciation": "mì jí", "ipa": "mi˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "菜市场里人很密集，我们走得很慢。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的小花种得太密集了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高楼密集的城市，天空显得很小。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼群密集地游过来，水都变黑了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书摆得很密集，放不下了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下的房子很密集，连路都很窄。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的树很密集，坐在下面很凉快。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的公交车站很密集。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花丛里蜜蜂密集地飞着。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，操场上的学生非常密集。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "密集型", "label": "复合"}, {"form": "人口密集", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多东西挤在一起、靠得很近的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：密集（mì jí）指很多东西挤在一起，靠得很近。"}, {"text": "密技", "is_correct": false, "explanation": "密技（mì jì）只是第二个音节的声调不同，意思是秘密的技巧，和“密集”不是一回事。"}, {"text": "密计", "is_correct": false, "explanation": "密计（mì jì）与 jí 的声调不同，意思是秘密的计策，不是“挤在一起”。"}, {"text": "秘计", "is_correct": false, "explanation": "秘计（mì jì）的第二个音节声调与 jí 不同，意思是秘密的计谋。"}], "explanations": {"密集": "正确：密集（mì jí）指很多东西挤在一起，靠得很近。", "密技": "密技（mì jì）只是第二个音节的声调不同，意思是秘密的技巧，和“密集”不是一回事。", "密计": "密计（mì jì）与 jí 的声调不同，意思是秘密的计策，不是“挤在一起”。", "秘计": "秘计（mì jì）的第二个音节声调与 jí 不同，意思是秘密的计谋。"}, "sentence_index": null, "correct_answer": "密集"}, "level_3": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：“人很密集”指很多人挤在一起，所以“我们走得很慢”。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”形容地方空、没有人，和“走得很慢”的拥挤情景不符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容安静无声，不是形容人挤在一起。"}, {"text": "苍白", "is_correct": false, "explanation": "体貌：“苍白”形容脸色，不能用来形容一群人挤在一起的样子。"}], "explanations": {"密集": "正确：“人很密集”指很多人挤在一起，所以“我们走得很慢”。", "空旷": "语义：“空旷”形容地方空、没有人，和“走得很慢”的拥挤情景不符。", "寂静": "语义：“寂静”形容安静无声，不是形容人挤在一起。", "苍白": "体貌：“苍白”形容脸色，不能用来形容一群人挤在一起的样子。"}, "sentence_index": 0, "correct_answer": "密集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国的关系很密集，合作很多。", "explanation": "这里应该用〈紧密〉。关系、联系要用紧密，密集只指许多东西或人挤在一起。"}, {"text": "老师讲课时，大家的思想都很密集。", "explanation": "这里应该用〈集中〉。思想、注意力要用集中，密集不能用来形容思想。"}, {"text": "这只猫的身材很密集，抱起来很重。", "explanation": "这里应该用〈胖〉。密集指许多东西挤在一起，不能形容猫的身材；形容猫身材圆润、抱起来很沉，要用胖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：“河边的树很密集”指树挤在一起，所以“坐在下面很凉快”。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容能看透的物体，不能用来形容树的分布。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音乱，不能用来形容树的密度。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音响亮，不能用来形容树。"}], "explanations": {"密集": "正确：“河边的树很密集”指树挤在一起，所以“坐在下面很凉快”。", "透明": "语义：“透明”形容能看透的物体，不能用来形容树的分布。", "嘈杂": "语义：“嘈杂”形容声音乱，不能用来形容树的密度。", "嘹亮": "语义：“嘹亮”形容声音响亮，不能用来形容树。"}, "sentence_index": 6, "correct_answer": "密集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音很密集，全班都听得见。", "explanation": "这里应该用〈洪亮〉。密集指许多东西挤在一起，不能形容声音的大小；声音大要用洪亮。"}, {"text": "我们两家的关系很密集，常来常往。", "explanation": "这里应该用〈亲密〉。关系、感情要用亲密，密集只指许多东西或人挤在一起。"}, {"text": "这张桌子很密集，一个人就能搬走。", "explanation": "这里应该用〈轻〉。密集指许多东西挤在一起，不能形容桌子的重量；桌子轻、一个人就能搬走要用轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站前的自行车得密集，我们只能慢慢走。", "corrected_sentence": "车站前的自行车很密集，我们只能慢慢走。", "error_description": "用词错：程度副词“很”误写成“得”。“得”是补语标记，接在动词或形容词后面（如“种得太密集”“密集得很”），不能直接修饰形容词“密集”，应说“很密集”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山坡上有一片密集地小树林。", "corrected_sentence": "山坡上有一片密集的小树林。", "error_description": "结构错误：“密集”修饰“小树林”时要用“的”，不能用“地”。正确说法是“密集的小树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
