INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22136, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西听你的话，不让它乱跑。", "primary_collocate": null, "pronunciation": "kòng zhì", "ipa": "kʰʊŋ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他不能控制自己的脾气。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机用手控制着车。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你控制一下音量。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生帮他控制体重。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太紧张了，控制不住地发抖。", "target_word": "控制", "complexity_tier": "T3", "furigana": "tā tài jǐnzhāng le, kòngzhì bú zhù de fādǒu", "sentence_source": "generated"}, {"text": "我们要控制每天吃糖的量。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用遥控器可以控制电视。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很难控制住自己的情绪。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察很快控制了现场。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子太小，还不会控制自己的手。", "target_word": "控制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "控制了", "label": "体标"}, {"form": "控制着", "label": "体标"}, {"form": "控制过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使人或事物按自己的意愿活动，不超出范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "控制", "is_correct": true, "explanation": "正确答案。控制 kòng zhì，意思是使事物按自己的意愿活动。"}, {"text": "空置", "is_correct": false, "explanation": "kōng（第一声）与 kòng（第四声）声调不同，意思是没人使用、闲置。"}, {"text": "重置", "is_correct": false, "explanation": "zhòng 与 kòng 声母不同（zh 与 k），声调相同，意思是重新设置。"}, {"text": "共治", "is_correct": false, "explanation": "gòng 与 kòng 声母不同（g 与 k），声调相同，意思是共同治理。"}], "explanations": {"控制": "正确答案。控制 kòng zhì，意思是使事物按自己的意愿活动。", "空置": "kōng（第一声）与 kòng（第四声）声调不同，意思是没人使用、闲置。", "重置": "zhòng 与 kòng 声母不同（zh 与 k），声调相同，意思是重新设置。", "共治": "gòng 与 kòng 声母不同（g 与 k），声调相同，意思是共同治理。"}, "sentence_index": null, "correct_answer": "控制"}, "level_3": {"options": [{"text": "控制", "is_correct": true, "explanation": "“控制”指管住自己的情绪，与“他不能”“自己的脾气”相符。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的宾语应是影音内容，不能说“播放自己的脾气”。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”是不及物动词，不能带“自己的脾气”作宾语。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语应是可购买的物品，脾气不能被购买。"}], "explanations": {"控制": "“控制”指管住自己的情绪，与“他不能”“自己的脾气”相符。", "播放": "搭配：“播放”的宾语应是影音内容，不能说“播放自己的脾气”。", "出发": "配价：“出发”是不及物动词，不能带“自己的脾气”作宾语。", "买": "搭配：“买”的宾语应是可购买的物品，脾气不能被购买。"}, "sentence_index": 0, "correct_answer": "控制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快控制了这些知识。", "explanation": "这里应该用〈掌握〉。控制用于对象的活动或状态，知识、技能要说掌握。"}, {"text": "他每天控制月亮。", "explanation": "这里应该用〈欣赏〉。控制是让东西听从自己，月亮不能被控制，看月亮要说欣赏。"}, {"text": "我控制了一本小说。", "explanation": "这里应该用〈读〉。控制是让对象按自己的意愿活动，看书要说读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控制", "is_correct": true, "explanation": "“控制”指用遥控器操纵电视，与“遥控器”“电视”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃电视”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“电视”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，电视不能被唱。"}], "explanations": {"控制": "“控制”指用遥控器操纵电视，与“遥控器”“电视”相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃电视”。", "哭": "配价：“哭”是不及物动词，不能带“电视”作宾语。", "唱": "搭配：“唱”的宾语应是歌曲，电视不能被唱。"}, "sentence_index": 6, "correct_answer": "控制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校控制学生的音乐才能。", "explanation": "这里应该用〈培养〉。控制用于对象的活动或状态，才能要说培养。"}, {"text": "妈妈控制面条。", "explanation": "这里应该用〈煮〉。控制不能用于做饭，煮面条要说煮。"}, {"text": "他控制了一首歌。", "explanation": "这里应该用〈唱〉。控制不能用于歌曲，唱歌要说唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于控制了住自己的脾气。", "corrected_sentence": "他终于控制住了自己的脾气。", "error_description": "错误在于“了”的位置。“控制住”是带结果补语“住”的结构，“了”应放在“住”之后，不能插在“控制”和“住”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机把车控制了很稳。", "corrected_sentence": "司机把车控制得很稳。", "error_description": "错误在于“了”与程度补语“很稳”不能同用。“控制”后接程度补语要用“得”，应说“司机把车控制得很稳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
