INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22140, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脸上的样子，能看出开心或难过。", "primary_collocate": null, "pronunciation": "biǎo qíng", "ipa": "piaʊ˨˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "听到好消息，他脸上露出了开心的表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的表情很难过，好像刚哭过。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他的表情，我就知道他在生气。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做了错事，脸上的表情很不自然。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，大家的表情都很轻松。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师严肃的表情让教室一下子安静了。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着成绩单，表情慢慢变了。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员的表情很丰富，一会儿笑一会儿哭。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不说话，我看不出她是什么表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟收到礼物，惊讶的表情很可爱。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种表情", "label": "量词"}, {"form": "一副表情", "label": "量词"}, {"form": "表情包", "label": "复合"}, {"form": "面部表情", "label": "复合"}], "register": "中性", "sense_fingerprint": "脸上显露出的神情、样子，反映心情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "正确：“表情”指脸上显露的样子，能看出开心，与“露出”搭配。"}, {"text": "包裹", "is_correct": false, "explanation": "语义：包裹是物件，脸上不会露出包裹，也与“开心”无关。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“露出”通常接神情、样子，不搭配“声音”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的分量，不是能显露出开心的脸上样子。"}], "explanations": {"表情": "正确：“表情”指脸上显露的样子，能看出开心，与“露出”搭配。", "包裹": "语义：包裹是物件，脸上不会露出包裹，也与“开心”无关。", "声音": "搭配：“露出”通常接神情、样子，不搭配“声音”。", "体重": "体貌：体重是身体的分量，不是能显露出开心的脸上样子。"}, "sentence_index": 0, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份表情需要你签字。", "explanation": "这里应该用〈文件〉。需要签字的纸要说文件；表情指脸上的样子，不能用来指纸件。"}, {"text": "这个地区的表情很稳定。", "explanation": "这里应该用〈形势〉。地区的局面要说形势；表情指脸上的样子，不能用来形容局面。"}, {"text": "他看着我，心里藏着伤心的表情。", "explanation": "这里应该用〈心情〉。心里藏着的情绪要说心情；表情指脸上的样子，不能藏在心里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "正确：看成绩单时脸上的样子慢慢变化，“表情”符合语境。"}, {"text": "发型", "is_correct": false, "explanation": "语义：看成绩单时发型不会慢慢变化，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会在看成绩单的过程中慢慢变化。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不是能随阅读而变化的样子。"}], "explanations": {"表情": "正确：看成绩单时脸上的样子慢慢变化，“表情”符合语境。", "发型": "语义：看成绩单时发型不会慢慢变化，句意不通。", "年龄": "语义：年龄不会在看成绩单的过程中慢慢变化。", "身高": "体貌：“身高”指身体的高矮，不是能随阅读而变化的样子。"}, "sentence_index": 6, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的表情说给老师听。", "explanation": "这里应该用〈感受〉。心里的体会要说感受；表情指脸上的样子，不能用来讲述心里的体会。"}, {"text": "我们把数据填在一张表情里。", "explanation": "这里应该用〈表格〉。填写数据的纸要说表格；表情指脸上的样子。"}, {"text": "两人之间有深厚的表情。", "explanation": "这里应该用〈感情〉。两人之间的情意要说感情；表情指脸上的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈看到信，脸上露出了一把担心的表情。", "corrected_sentence": "妈妈看到信，脸上露出了一种担心的表情。", "error_description": "量词用错：“表情”应配“种”或“副”，不能配“把”。应说“一种担心的表情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生看到病人脸上有一条痛苦的表情。", "corrected_sentence": "医生看到病人脸上有一种痛苦的表情。", "error_description": "量词用错：“表情”应配“种”或“副”，不能配“条”。应说“一种痛苦的表情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
