INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人在社会中所处的位置或等级。", "primary_collocate": null, "pronunciation": "dì wèi", "ipa": "ti˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他是大学教授，在社会上很有地位。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，医生的地位一般比较高。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作很努力，终于提高了自己的地位。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们家，爷爷的地位最高，大家都听他的。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的经济很好，在世界上的地位越来越高。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管地位高低，大家在法律面前都是平等的。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了新工作，地位一下子变高了。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在社会上，老师的地位很重要。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不看重钱和地位，只想过简单的生活。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去女人在家里没有什么地位。", "target_word": "地位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社会地位", "label": "复合"}, {"form": "国际地位", "label": "复合"}], "register": "中性", "sense_fingerprint": "人在社会中所处的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地位", "is_correct": true, "explanation": "正确：教授在社会上的身份和分量，用“地位”最恰当。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“很有”修饰的是分量、能力之类的抽象义，“体积”指空间大小，不能这样修饰社会身份，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很有”修饰的是分量、能力之类的抽象义，“身高”是具体数值，不搭配。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”是人的生理或社会分类，不能说在社会上“很有性别”。"}], "explanations": {"地位": "正确：教授在社会上的身份和分量，用“地位”最恰当。", "体积": "搭配：“很有”修饰的是分量、能力之类的抽象义，“体积”指空间大小，不能这样修饰社会身份，句意不通。", "身高": "搭配：“很有”修饰的是分量、能力之类的抽象义，“身高”是具体数值，不搭配。", "性别": "语义：“性别”是人的生理或社会分类，不能说在社会上“很有性别”。"}, "sentence_index": 0, "correct_answer": "地位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座学校的地位在河边。", "explanation": "这里应该用〈位置〉。地位指社会身份或等级，学校的地理位置要用〈位置〉。"}, {"text": "他跑步的地位很快，一下子就跑完了全程。", "explanation": "这里应该用〈速度〉。地位指社会中的位置，跑步的快慢要用〈速度〉。"}, {"text": "他的身体地位很好。", "explanation": "这里应该用〈状况〉。地位指社会中的位置，身体的好坏要用〈状况〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地位", "is_correct": true, "explanation": "正确：换了新工作后社会上的地位提高，用“地位”最恰当。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能说“变高”，换工作也不会改变颜色，句意不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：换工作不会使温度升高，句子语义不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄只会增长，换工作不会让年龄“变高”。"}], "explanations": {"地位": "正确：换了新工作后社会上的地位提高，用“地位”最恰当。", "颜色": "语义：颜色不能说“变高”，换工作也不会改变颜色，句意不通。", "温度": "语义：换工作不会使温度升高，句子语义不通。", "年龄": "语义：年龄只会增长，换工作不会让年龄“变高”。"}, "sentence_index": 6, "correct_answer": "地位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的地位很大，很多病人都用。", "explanation": "这里应该用〈作用〉。地位指社会中的位置，药物的效果要用〈作用〉。"}, {"text": "这辆车的地位很快，开起来很舒服。", "explanation": "这里应该用〈速度〉。地位指社会中的位置，车子的快慢要用〈速度〉。"}, {"text": "这杯水的地位很高，我一口都没喝。", "explanation": "这里应该用〈温度〉。地位指社会中的位置，水的冷热要用〈温度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人在村里很是地位，大家都尊敬他。", "corrected_sentence": "这位老人在村里很有地位，大家都尊敬他。", "error_description": "“很是”是副词，只修饰形容词或动词，不能带名词“地位”；应说“很有地位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很有地位人。", "corrected_sentence": "他是一个很有地位的人。", "error_description": "“地位”修饰“人”时要加“的”，应说“很有地位的人”。漏掉“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22144, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "理智：与“情感”相对，指凭道理和判断做事，不单凭感受。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子：与“情感”没有反义关系，是具体的家具。"}, {"text": "河流", "is_correct": false, "explanation": "河流：与“情感”没有反义关系，是具体的自然事物。"}, {"text": "天空", "is_correct": false, "explanation": "天空：与“情感”没有反义关系，指地面上方的自然空间。"}], "correct_answer": "理智", "explanations": {"理智": "理智：与“情感”相对，指凭道理和判断做事，不单凭感受。", "桌子": "桌子：与“情感”没有反义关系，是具体的家具。", "河流": "河流：与“情感”没有反义关系，是具体的自然事物。", "天空": "天空：与“情感”没有反义关系，指地面上方的自然空间。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22144, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "理智：与“情感”相对，指凭道理和判断做事，不单凭感受。"}, {"text": "花园", "is_correct": false, "explanation": "花园：与“情感”没有反义关系，是种花草的场所。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋：与“情感”没有反义关系，是广阔的水域。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户：与“情感”没有反义关系，是房屋上透光的部分。"}], "correct_answer": "理智", "explanations": {"理智": "理智：与“情感”相对，指凭道理和判断做事，不单凭感受。", "花园": "花园：与“情感”没有反义关系，是种花草的场所。", "海洋": "海洋：与“情感”没有反义关系，是广阔的水域。", "窗户": "窗户：与“情感”没有反义关系，是房屋上透光的部分。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人心里对人和事所产生的喜怒哀乐等感受。", "primary_collocate": null, "pronunciation": "qíng gǎn", "ipa": "tɕʰiŋ˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这首歌表达了母亲对孩子的情感。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少说出自己的情感。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间的情感需要用心保护。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这部电影，我的情感很复杂。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写的诗里有很深的情感。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对小狗有很深的情感。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作文要把真实的情感写出来。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们之间的情感越来越深。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把情感藏在心里，不让别人知道。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事很打动人，因为里面有真实的情感。", "target_word": "情感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情感上", "label": "方位用法"}, {"form": "情感表达", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人心里对人和事的喜怒哀乐等感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情感", "is_correct": true, "explanation": "情感：表示母亲对孩子的喜爱与牵挂，与“表达”搭配自然。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“表达”后接感情、心意，不接“价格”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不能作为“表达”的内容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是人的内心感受，不能作为母亲表达的对象。"}], "explanations": {"情感": "情感：表示母亲对孩子的喜爱与牵挂，与“表达”搭配自然。", "价格": "搭配：“表达”后接感情、心意，不接“价格”。", "体重": "语义：“体重”是身体的重量，不能作为“表达”的内容。", "颜色": "语义：“颜色”不是人的内心感受，不能作为母亲表达的对象。"}, "sentence_index": 0, "correct_answer": "情感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的情感很硬。", "explanation": "这里误把〈情感〉当成了〈硬度〉。情感指心里高兴或难过的感觉，不能用来说石头的软硬。"}, {"text": "他的情感很便宜，只要五块钱。", "explanation": "这里误把〈情感〉当成了〈价钱〉。情感指心里高兴或难过的感觉，不能用来说价钱的高低。"}, {"text": "这台电脑的情感很快。", "explanation": "这里应该用〈速度〉。情感指心里的感受，不能用来说电脑的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情感", "is_correct": true, "explanation": "情感：指作者内心真实的感受，与“真实的……写出来”搭配自然。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有内心感受，不能作为“写出来”的内容。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是写作文要写出来的内心感受。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不是可以写出来的内心感受。"}], "explanations": {"情感": "情感：指作者内心真实的感受，与“真实的……写出来”搭配自然。", "石头": "语义：石头没有内心感受，不能作为“写出来”的内容。", "汽油": "语义：汽油是燃料，不是写作文要写出来的内心感受。", "身材": "体貌：“身材”指人的体形，不是可以写出来的内心感受。"}, "sentence_index": 6, "correct_answer": "情感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脚已经没有情感了。", "explanation": "这里应该用〈感觉〉。情感指心里的喜怒哀乐，身体的知觉要用“感觉”。"}, {"text": "我的爸爸是情感。", "explanation": "这里误把〈情感〉当成了〈职业〉。情感指心里高兴或难过的感觉，不能用来指人的身份或职业。"}, {"text": "他把情感吃光了，所以现在不饿。", "explanation": "这里误把〈情感〉当成了〈食物〉。情感指心里高兴或难过的感觉，不能当作食物来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我心里有一只复杂的情感。", "corrected_sentence": "我心里有一种复杂的情感。", "error_description": "量词错误：“情感”要用“种”，“只”多用于动物或成对的东西，不能修饰“情感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影打动人，是因为它有真实地情感。", "corrected_sentence": "这部电影打动人，是因为它有真实的情感。", "error_description": "结构助词：修饰名词“情感”要用“的”，“地”用于修饰动词，写成“真实地情感”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
