INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22154, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一段时间内受很多人喜欢、欢迎的。", "primary_collocate": null, "pronunciation": "liú xíng", "ipa": "ljoʊ³⁵ ɕiŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这种红色的鞋子今年很流行。", "target_word": "流行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在年轻人都喜欢流行的歌曲。", "target_word": "流行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年流行的裙子，今年没人穿了。", "target_word": "流行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短视频在学生中非常流行。", "target_word": "流行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌最近特别流行。", "target_word": "流行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是穿最流行的衣服。", "target_word": "流行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说这种游戏在国外也很流行。", "target_word": "流行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长头发以前很流行，现在不流行了。", "target_word": "流行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个冬天最流行的颜色是什么？", "target_word": "流行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词是网上最近才流行起来的。", "target_word": "流行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流行了", "label": "体标"}], "register": "中性", "sense_fingerprint": "事物一时受很多人欢迎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7cea0ef-f5d6-475e-98b1-4539dcad4711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流行", "is_correct": true, "explanation": "正确：“流行”（liúxíng）表示受很多人喜欢，是这里要听的词。"}, {"text": "流星", "is_correct": false, "explanation": "xīng（第一声）与 xíng（第二声）声调不同，意思是流星。"}, {"text": "留情", "is_correct": false, "explanation": "qíng 与 xíng 声母不同：q 与 x，意思是留情，指宽恕。"}, {"text": "流血", "is_correct": false, "explanation": "xuè 与 xíng 韵母和声调都不同，前字 liú 相同，意思是出血。"}], "explanations": {"流行": "正确：“流行”（liúxíng）表示受很多人喜欢，是这里要听的词。", "流星": "xīng（第一声）与 xíng（第二声）声调不同，意思是流星。", "留情": "qíng 与 xíng 声母不同：q 与 x，意思是留情，指宽恕。", "流血": "xuè 与 xíng 韵母和声调都不同，前字 liú 相同，意思是出血。"}, "sentence_index": null, "correct_answer": "流行"}, "level_3": {"options": [{"text": "流行", "is_correct": true, "explanation": "正确：“流行”表示受很多人喜欢，符合“这种红色的鞋子今年很……”的语境。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”描述人的情绪，不能用来形容鞋子。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指人不说话，用来形容鞋子说不通。"}, {"text": "贫穷", "is_correct": false, "explanation": "搭配：“贫穷”指人或地区的经济状况，不能修饰鞋子。"}], "explanations": {"流行": "正确：“流行”表示受很多人喜欢，符合“这种红色的鞋子今年很……”的语境。", "生气": "语义：“生气”描述人的情绪，不能用来形容鞋子。", "沉默": "语义：“沉默”指人不说话，用来形容鞋子说不通。", "贫穷": "搭配：“贫穷”指人或地区的经济状况，不能修饰鞋子。"}, "sentence_index": 0, "correct_answer": "流行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很流行，大家都听得懂。", "explanation": "这里应该用〈流畅〉。流行指受很多人欢迎，说话顺利要用〈流畅〉。"}, {"text": "这股风很流行，吹得人很舒服。", "explanation": "这里应该用〈和煦〉。流行指受欢迎，形容风的温和要用〈和煦〉。"}, {"text": "这条马路很流行，车开得很快。", "explanation": "这里应该用〈畅通〉。流行指受欢迎，道路无阻要用〈畅通〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22154, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "流行", "is_correct": true, "explanation": "正确：“流行”（liúxíng）表示受很多人喜欢，是这里要听的词。"}, {"text": "留名", "is_correct": false, "explanation": "míng 与 xíng 声母不同：m 与 x，意思是留下名字。"}, {"text": "留心", "is_correct": false, "explanation": "xīn 与 xíng 声调和韵母都不同（-in 与 -ing），意思是留意。"}, {"text": "旅行", "is_correct": false, "explanation": "lǚ 与 liú 韵母和声调都不同，后字 xíng 不变，意思是旅行。"}], "explanations": {"流行": "正确：“流行”（liúxíng）表示受很多人喜欢，是这里要听的词。", "留名": "míng 与 xíng 声母不同：m 与 x，意思是留下名字。", "留心": "xīn 与 xíng 声调和韵母都不同（-in 与 -ing），意思是留意。", "旅行": "lǚ 与 liú 韵母和声调都不同，后字 xíng 不变，意思是旅行。"}, "sentence_index": null, "correct_answer": "流行"}, "level_3": {"options": [{"text": "流行", "is_correct": true, "explanation": "正确：“流行”表示受很多人喜欢，符合“听说这种游戏在国外也很……”的语境。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”只能说人或动物，游戏不会饥饿。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”描述人的感受，不用于游戏。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”修饰空间，不能说游戏“很宽敞”。"}], "explanations": {"流行": "正确：“流行”表示受很多人喜欢，符合“听说这种游戏在国外也很……”的语境。", "饥饿": "语义：“饥饿”只能说人或动物，游戏不会饥饿。", "寂寞": "语义：“寂寞”描述人的感受，不用于游戏。", "宽敞": "搭配：“宽敞”修饰空间，不能说游戏“很宽敞”。"}, "sentence_index": 6, "correct_answer": "流行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "血从他的伤口流行。", "explanation": "这里应该用〈流出〉。流行表示受欢迎，液体从伤口流出要用〈流出〉。"}, {"text": "他的性格很流行，朋友很多。", "explanation": "“流行”只用于受欢迎的事物，不能形容人的性格；形容性格要用〈开朗〉。"}, {"text": "河水在山里流行。", "explanation": "这里应该用〈流动〉。“流行”不表示水的流动，水流要用〈流动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款游戏流行地很快。", "corrected_sentence": "这款游戏流行得很快。", "error_description": "表示“流行”的程度要用补语，应说“流行得很快”，不能用“地”说“流行地很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种颜色今年被流行了。", "corrected_sentence": "这种颜色今年流行了。", "error_description": "“流行”不带宾语，不能用“被”构成被动句，去掉“被”，说“这种颜色今年流行了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
