INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "理论家就是很懂很多道理并经常讲给别人听的人。", "primary_collocate": null, "pronunciation": "lǐ lùn jiā", "ipa": "/li˨˩ lwən˥˩ tɕja˥/", "syllable_count": 3, "sentences": [{"text": "我哥哥是个理论家，总爱讲大道理。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个理论家，说得多，做得少。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别听那个理论家的，他自己没试过。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是我们家的理论家。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她像个理论家，每件事都有道理。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都叫他理论家。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理论家又开始给我们讲道理了。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事的时候，我不想听理论家说话。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不只是理论家，也会自己动手。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个理论家今天又讲了一个小时。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "很懂道理、爱给别人讲道理的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f59b8ca-db7c-451b-a6bc-df6abcd7de58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理论家", "is_correct": true, "explanation": "正确：口语中“理论家”指爱讲道理的人，与“总爱讲大道理”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会讲道理，与“总爱讲大道理”矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“总爱讲大道理”要求能说话的主语，窗户不能作主语。"}, {"text": "雕像", "is_correct": false, "explanation": "体貌：“雕像”只描述静止的外形，不会说话，与“总爱讲大道理”不符。"}], "explanations": {"理论家": "正确：口语中“理论家”指爱讲道理的人，与“总爱讲大道理”相符。", "石头": "语义：石头不会讲道理，与“总爱讲大道理”矛盾。", "窗户": "配价：“总爱讲大道理”要求能说话的主语，窗户不能作主语。", "雕像": "体貌：“雕像”只描述静止的外形，不会说话，与“总爱讲大道理”不符。"}, "sentence_index": 0, "correct_answer": "理论家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台理论家今天来我们班讲课。", "explanation": "量词错误：〈台〉多用于机器，指人的“理论家”应用〈个〉或〈位〉。"}, {"text": "我家来了一只理论家。", "explanation": "量词错误：〈只〉多用于动物，指人应用〈个〉或〈位〉。"}, {"text": "我家来了一条理论家。", "explanation": "量词错误：〈条〉用于长条形事物，指人应用〈个〉或〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理论家", "is_correct": true, "explanation": "正确：口语中“理论家”指爱讲道理的人，“又开始给我们讲道理”正合语境。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会讲道理，句意不通。"}, {"text": "空调", "is_correct": false, "explanation": "配价：“给我们讲道理”要求能说话的施事，空调不能充当。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭不会讲道理，与句意相矛盾。"}], "explanations": {"理论家": "正确：口语中“理论家”指爱讲道理的人，“又开始给我们讲道理”正合语境。", "椅子": "语义：椅子不会讲道理，句意不通。", "空调": "配价：“给我们讲道理”要求能说话的施事，空调不能充当。", "早饭": "语义：早饭不会讲道理，与句意相矛盾。"}, "sentence_index": 6, "correct_answer": "理论家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电脑坏了，请理论家来修。", "explanation": "这里应该用〈专家〉。修电脑要找懂技术的人，“理论家”只指爱讲道理的人，不会修东西。"}, {"text": "他是我们的理论家，每天带我们练跑步。", "explanation": "这里应该用〈教练〉。带人练跑步是教练的工作，“理论家”指爱讲道理的人。"}, {"text": "这桌菜是理论家做的，很好吃。", "explanation": "这里应该用〈厨师〉。做菜要靠厨师，“理论家”不做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈是个理论家们，遇事总要解释。", "corrected_sentence": "我妈妈是个理论家，遇事总要解释。", "error_description": "后缀错误：量词“个”修饰的名词后不能加“们”，应为“个理论家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个的理论家又在给我们讲道理了。", "corrected_sentence": "那个理论家又在给我们讲道理了。", "error_description": "结构错误：指示词加量词与名词之间不能插入“的”，应去掉“的”，为“那个理论家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
