INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主义是一种想法，很多人一起相信它，照着去做。", "primary_collocate": null, "pronunciation": "zhǔ yì", "ipa": "ʈʂu˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "他从小就相信一种主义。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个主义让很多人有了希望。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是主义。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了自己的主义，工作了一辈子。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人不喜欢谈主义，只想过好日子。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种主义的想法很不一样。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了很多种主义。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不相信这个主义？", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想让大家都接受他的主义。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个主义要有很多人相信才有力量。", "target_word": "主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主義", "label": "繁体"}, {"form": "一种主义", "label": "量词"}, {"form": "社会主义", "label": "复合"}, {"form": "个人主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "许多人共同相信并依照去做的系统想法或主张；名词义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22158, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主义", "is_correct": true, "explanation": "「主义」指许多人共同相信并依照去做的系统想法，是本题正确答案。"}, {"text": "注意", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是留心、当心。"}, {"text": "竹椅", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，yǐ（第三声）与 yì（第四声）声调不同，意思是用竹子做的椅子。"}, {"text": "主业", "is_correct": false, "explanation": "yè 与 yì 韵母不同（ie 与 i），意思是主要的事业或业务。"}], "explanations": {"主义": "「主义」指许多人共同相信并依照去做的系统想法，是本题正确答案。", "注意": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是留心、当心。", "竹椅": "zhú（第二声）与 zhǔ（第三声）声调不同，yǐ（第三声）与 yì（第四声）声调不同，意思是用竹子做的椅子。", "主业": "yè 与 yì 韵母不同（ie 与 i），意思是主要的事业或业务。"}, "sentence_index": null, "correct_answer": "主义"}, "level_3": {"options": [{"text": "主义", "is_correct": true, "explanation": "「主义」指一套系统的思想主张，与「相信一种」搭配通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指色彩，不是可以相信的思想体系。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：「乐器」指演奏用的器具，与「相信」搭配不成立。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「相信」接的是观点或道理，「体温」是身体指标，不能被相信。"}], "explanations": {"主义": "「主义」指一套系统的思想主张，与「相信一种」搭配通顺。", "颜色": "语义：「颜色」指色彩，不是可以相信的思想体系。", "乐器": "语义：「乐器」指演奏用的器具，与「相信」搭配不成立。", "体温": "搭配：「相信」接的是观点或道理，「体温」是身体指标，不能被相信。"}, "sentence_index": 0, "correct_answer": "主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手里拿着一把主义。", "explanation": "这里应该用〈种〉。〈把〉用于有柄的器具，「主义」是抽象的思想体系，不能用〈把〉计量。"}, {"text": "他喝了一杯主义。", "explanation": "这里应该用〈种〉。〈杯〉用于液体或盛在杯中的东西，「主义」不能用〈杯〉计量。"}, {"text": "他摘了一朵主义。", "explanation": "这里应该用〈种〉。〈朵〉用于花朵或云彩，「主义」不能用〈朵〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22158, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主义", "is_correct": true, "explanation": "「主义」指许多人共同相信并依照去做的系统想法，是本题正确答案。"}, {"text": "主页", "is_correct": false, "explanation": "yè（第四声）与 yì（第四声）韵母不同（ie 与 i），意思是网站的首页。"}, {"text": "竹艺", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是用竹子制作工艺品的技艺。"}, {"text": "助益", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是帮助和益处。"}], "explanations": {"主义": "「主义」指许多人共同相信并依照去做的系统想法，是本题正确答案。", "主页": "yè（第四声）与 yì（第四声）韵母不同（ie 与 i），意思是网站的首页。", "竹艺": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是用竹子制作工艺品的技艺。", "助益": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是帮助和益处。"}, "sentence_index": null, "correct_answer": "主义"}, "level_3": {"options": [{"text": "主义", "is_correct": true, "explanation": "「主义」指一套系统的思想主张，「书里写了很多种主义」语义通顺。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指滋味或气味，不是书里要写的思想体系。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指岁数，「书里写了很多种年龄」句子说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」只用于人或动物的重量，不能与「很多种」搭配表示书中内容。"}], "explanations": {"主义": "「主义」指一套系统的思想主张，「书里写了很多种主义」语义通顺。", "味道": "语义：「味道」指滋味或气味，不是书里要写的思想体系。", "年龄": "语义：「年龄」指岁数，「书里写了很多种年龄」句子说不通。", "体重": "搭配：「体重」只用于人或动物的重量，不能与「很多种」搭配表示书中内容。"}, "sentence_index": 6, "correct_answer": "主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的主义是做一名老师。", "explanation": "这里应该用〈理想〉。「主义」指成体系的思想主张，个人的人生愿望要用「理想」。"}, {"text": "这次考试，我的主义是及格。", "explanation": "这里应该用〈目标〉。「主义」指系统的思想主张，短期的具体要求要用「目标」。"}, {"text": "这个月的主义是减肥。", "explanation": "这里应该用〈计划〉。「主义」指系统的思想主张，一段时间内要做的事要用「计划」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_v