INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们坚持一条主义，从不动摇。", "corrected_sentence": "他们坚持一种主义，从不动摇。", "error_description": "错误：「条」用于细长的物体，不能计量「主义」。正确：「种」，即「一种主义」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多人都遵守他的主义。", "corrected_sentence": "很多人都信仰他的主义。", "error_description": "错误：「遵守」接规则、纪律，不与思想体系「主义」搭配。正确：「信仰」，即「信仰他的主义」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
