INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学是学习数字、形状和加减的课。", "primary_collocate": null, "pronunciation": "shù xué", "ipa": "ʂu˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "今天下午第一节是数学。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最不喜欢的课是数学，因为作业太多。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天数学要考试，我得复习。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后，我问同学数学作业怎么做。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周三上午我们有两节数学。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他数学考了九十分，很高兴。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上讲数学，同学们认真听着。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的数学不好，妈妈请了老师帮他。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天上午先上数学，再上英语。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这学期我们在数学课上学了加减法和图形。", "target_word": "数学", "complexity_tier": "T3", "furigana": "zhè xué qī wǒ men zài shù xué kè shàng xué le jiā jiǎn fǎ hé tú xíng。", "sentence_source": "generated"}], "morphological_forms": [{"form": "數學", "label": "繁体"}, {"form": "数学课", "label": "复合"}, {"form": "数学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校里学习数字、形状和加减的课程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '935c507d-9a1e-4188-bb8e-3e75cd8aa9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22164, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数学", "is_correct": true, "explanation": "数学（shù xué）：句中所指的课程。"}, {"text": "输血", "is_correct": false, "explanation": "shū 与 shù、xuè 与 xué 声调都不同，输血指把血液输入人体。"}, {"text": "入学", "is_correct": false, "explanation": "rù 与 shù 声母不同（r 与 sh），入学指进入学校。"}, {"text": "助学", "is_correct": false, "explanation": "zhù 与 shù 声母不同（zh 与 sh），助学指帮助学生求学。"}], "explanations": {"数学": "数学（shù xué）：句中所指的课程。", "输血": "shū 与 shù、xuè 与 xué 声调都不同，输血指把血液输入人体。", "入学": "rù 与 shù 声母不同（r 与 sh），入学指进入学校。", "助学": "zhù 与 shù 声母不同（zh 与 sh），助学指帮助学生求学。"}, "sentence_index": null, "correct_answer": "数学"}, "level_3": {"options": [{"text": "数学", "is_correct": true, "explanation": "数学：课程名，“今天下午第一节是数学”说得通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“第一节”指一个课时，不能是一顿饭。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是场地，不是课程安排，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：说“第一节是……”要用科目或活动，不说“课本”。"}], "explanations": {"数学": "数学：课程名，“今天下午第一节是数学”说得通。", "午饭": "语义：“第一节”指一个课时，不能是一顿饭。", "操场": "语义：操场是场地，不是课程安排，句意不通。", "课本": "搭配：说“第一节是……”要用科目或活动，不说“课本”。"}, "sentence_index": 0, "correct_answer": "数学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每周上两本数学。", "explanation": "这里应该用〈节〉。作为课程，数学用“节”计量，“本”用于书籍。"}, {"text": "我每天上一首数学。", "explanation": "这里应该用〈节〉。“首”用于诗歌、歌曲，不用于课程。"}, {"text": "我每天上一张数学。", "explanation": "这里应该用〈节〉。“张”用于平面的东西，不用于课程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数学", "is_correct": true, "explanation": "数学：课程名，“老师在黑板上讲数学”说得通。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“讲”不接“歌”，应说“唱歌”。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：老师不会在黑板上讲衣服，句意不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是可以在黑板上讲授的内容。"}], "explanations": {"数学": "数学：课程名，“老师在黑板上讲数学”说得通。", "歌": "搭配：“讲”不接“歌”，应说“唱歌”。", "衣服": "语义：老师不会在黑板上讲衣服，句意不通。", "蛋糕": "语义：蛋糕不是可以在黑板上讲授的内容。"}, "sentence_index": 6, "correct_answer": "数学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把电话号码里的数学抄在了纸上。", "explanation": "这里应该用〈数字〉。数学指学科，不指一个个号码。"}, {"text": "我们要统计观众的数学。", "explanation": "这里应该用〈数量〉。数学不能用来说观众有多少。"}, {"text": "书架上书的数学不少。", "explanation": "这里应该用〈数目〉。数学不表示书的多少，“书的数目”才说得通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这学期选了两本数学。", "corrected_sentence": "他这学期选了两门数学。", "error_description": "错误在量词：“两本数学”中，“本”用于书籍；作为课程的数学应用“门”计量。应改为“两门数学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每周有三数学课。", "corrected_sentence": "我们每周有三门数学课。", "error_description": "错误在量词：数词“三”与名词“数学课”之间缺少量词，应加“门”，写作“三门数学课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22166, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排除", "is_correct": true, "explanation": "“排除”指把某事物挡在某个范围之外，与“纳入”（放进范围之内）意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细地看，与“纳入”的意思没有对立关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指使损坏的东西恢复正常，与“纳入”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指就某事交换意见，与“纳入”没有反义关系。"}], "correct_answer": "排除", "explanations": {"排除": "“排除”指把某事物挡在某个范围之外，与“纳入”（放进范围之内）意思相反。", "观察": "“观察”指仔细地看，与“纳入”的意思没有对立关系。", "修理": "“修理”指使损坏的东西恢复正常，与“纳入”没有反义关系。", "讨论": "“讨论”指就某事交换意见，与“纳入”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
