INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某事物归入某个范围、计划或系统之内。", "primary_collocate": null, "pronunciation": "nà rù", "ipa": "na˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "学校把这件事纳入了今年的计划。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把新员工纳入培训名单。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱已经纳入了明年的预算。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把老人的医疗费用纳入医保范围。", "target_word": "纳入", "complexity_tier": "T3", "furigana": "zhèng fǔ bǎ lǎo rén de yī liáo fèi yòng nà rù yī bǎo fàn wéi", "sentence_source": "generated"}, {"text": "请把我的意见纳入考虑。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把环保纳入城市发展的计划。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目没有纳入这次的名单。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每天跑步纳入了生活安排。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的课程已经纳入学校的教学计划。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，请把这些费用纳入本月的账单。", "target_word": "纳入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纳入了", "label": "体标（完成）"}, {"form": "纳入过", "label": "体标（经历）"}], "register": "书面", "sense_fingerprint": "把某事物放进某个范围、计划或系统之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18b3f918-5c54-4472-be9f-e910ce51db7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纳入", "is_correct": true, "explanation": "“纳入”指把事物归入某个计划之内，符合句中“今年的计划”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃计划。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿计划。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是把具体的东西丢掉，不能说把事情“扔”进计划里。"}], "explanations": {"纳入": "“纳入”指把事物归入某个计划之内，符合句中“今年的计划”的语境。", "吃": "搭配：“吃”的对象是食物，不能说吃计划。", "穿": "搭配：“穿”的对象是衣物，不能说穿计划。", "扔": "语义：“扔”是把具体的东西丢掉，不能说把事情“扔”进计划里。"}, "sentence_index": 0, "correct_answer": "纳入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把工资纳入银行。", "explanation": "这里应该用〈存入〉。纳入指把事物归入某个计划或范围，把钱存进银行要用存入。"}, {"text": "这种植物纳入了很多水分。", "explanation": "这里应该用〈吸收〉。植物从外界摄取水分要用吸收，纳入不能表示这个动作。"}, {"text": "他把一杯热水纳入了杯子里。", "explanation": "这里应该用〈倒入〉。纳入指把事物归入某个范围或系统，把液体倒进容器要用倒入，不能说纳入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纳入", "is_correct": true, "explanation": "“纳入”指把事物归入某个名单之内，这里表示项目没有被归入这次的名单。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说煮名单。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”用于食物，不能说煎名单。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”是咀嚼，与把项目归入名单无关。"}], "explanations": {"纳入": "“纳入”指把事物归入某个名单之内，这里表示项目没有被归入这次的名单。", "煮": "搭配：“煮”的对象是食物，不能说煮名单。", "煎": "搭配：“煎”用于食物，不能说煎名单。", "嚼": "语义：“嚼”是咀嚼，与把项目归入名单无关。"}, "sentence_index": 6, "correct_answer": "纳入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们纳入了教室。", "explanation": "这里应该用〈进入〉。纳入指把事物归入某个范围、计划或系统，人走进某个地方要用进入。"}, {"text": "他纳入了沉思。", "explanation": "这里应该用〈陷入〉。陷入指陷进某种状态，纳入没有这个意思，不能说纳入沉思。"}, {"text": "河水纳入了村庄。", "explanation": "这里应该用〈灌入〉。灌入指液体注入某处，纳入不能用于河水流进村庄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这个想法纳入着报告。", "corrected_sentence": "我们把这个想法纳入了报告。", "error_description": "体标错误：“纳入”是一次性完成的动作，应用“了”表示完成，“着”表示持续状态，与这里的语境不符。正确：“纳入了报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们部门没有纳入了这次的名单。", "corrected_sentence": "我们部门没有纳入这次的名单。", "error_description": "体标错误：“没有”表示否定，不能与表示完成的“了”同用。正确：“没有纳入这次的名单”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
