INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某样东西出现或产生。", "primary_collocate": null, "pronunciation": "cuī shēng chū", "ipa": "/tsʰweɪ˥ ʂɤŋ˥ ʈʂʰu˥/", "syllable_count": 3, "sentences": [{"text": "这个想法催生出新的产品。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络催生出很多新工作。", "target_word": "催生出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的环境能催生出好的想法。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的出现催生出了新的生活方式。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛催生出几位年轻的明星。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "压力有时会催生出意想不到的办法。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的快速发展催生出很多新行业。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书催生出一部有名的电影。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上购物催生出送货这个行业。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同文化的交流催生出新的音乐。", "target_word": "催生出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "催生出了", "label": "体标"}], "register": "书面", "sense_fingerprint": "动词：某种条件或事物促使新事物产生出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吞噬", "is_correct": false, "explanation": "语义：“吞噬”指吞食或侵占，与“新的产品”的产生相冲突。"}, {"text": "催生出", "is_correct": true, "explanation": "正确：“催生出”表示让新产品出现，符合句意。"}, {"text": "扼杀", "is_correct": false, "explanation": "语义：“扼杀”指压制使其消亡，与“新的产品”的出现相反。"}, {"text": "卖出", "is_correct": false, "explanation": "配价：“卖出”要求能买卖的人或店铺作主语，“这个想法”不能卖出产品。"}], "explanations": {"吞噬": "语义：“吞噬”指吞食或侵占，与“新的产品”的产生相冲突。", "催生出": "正确：“催生出”表示让新产品出现，符合句意。", "扼杀": "语义：“扼杀”指压制使其消亡，与“新的产品”的出现相反。", "卖出": "配价：“卖出”要求能买卖的人或店铺作主语，“这个想法”不能卖出产品。"}, "sentence_index": 0, "correct_answer": "催生出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶催生出了一件新毛衣。", "explanation": "这里应该用〈织〉。催生出指外部条件促使新事物产生，奶奶亲手做毛衣要用织。"}, {"text": "这个城市催生出了很多人口。", "explanation": "这里应该用〈增加〉。催生出只用于新事物的出现，人口增长要用增加，不能说催生出人口。"}, {"text": "他催生出了一顿丰盛的午饭。", "explanation": "这里应该用〈做〉。催生出指外部条件促使新事物产生，亲手做饭要用做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱散", "is_correct": false, "explanation": "搭配：“驱散”多用于人群、云雾，不能用来驱散“新行业”。"}, {"text": "催生出", "is_correct": true, "explanation": "正确：“催生出”表示发展使新行业出现，符合句意。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光灭掉，与“新行业”的出现正好相反。"}, {"text": "修剪", "is_correct": false, "explanation": "配价：“修剪”的对象是枝叶或头发，“城市的快速发展”不能修剪行业。"}], "explanations": {"驱散": "搭配：“驱散”多用于人群、云雾，不能用来驱散“新行业”。", "催生出": "正确：“催生出”表示发展使新行业出现，符合句意。", "熄灭": "语义：“熄灭”指火或光灭掉，与“新行业”的出现正好相反。", "修剪": "配价：“修剪”的对象是枝叶或头发，“城市的快速发展”不能修剪行业。"}, "sentence_index": 6, "correct_answer": "催生出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们催生出了一座新的大桥。", "explanation": "这里应该用〈建造〉。建造指有计划地修建实体工程；催生出指条件使新事物产生，不用于工人修桥。"}, {"text": "科学家催生出了一颗新的行星。", "explanation": "这里应该用〈发现〉。发现指找到本来就存在的事物；催生出指使新事物产生，行星不是人催生出来的。"}, {"text": "他催生出了一份文件。", "explanation": "这里应该用〈起草〉。起草指动笔拟写文件；催生出指外部条件使新事物产生，不用于人亲手拟写文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工业的进步催生出着许多新职业。", "corrected_sentence": "工业的进步催生出了许多新职业。", "error_description": "体标错误：“催生出”带结果补语“出”，表示已产生的结果应用“了”，不能用表示持续的“着”，应改为“催生出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电脑的普及一批新的职业催生出了。", "corrected_sentence": "电脑的普及催生出了一批新的职业。", "error_description": "语序错误：宾语“一批新的职业”应放在“催生出了”之后，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
