INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家相信某个人或某个东西说的是对的、真的。", "primary_collocate": null, "pronunciation": "quán wēi xìng", "ipa": "tɕʰɥɛn weɪ ɕiŋ", "syllable_count": 3, "sentences": [{"text": "大家都觉得他说的话很有权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生的诊断很有权威性，大家都相信。", "target_word": "权威性", "complexity_tier": "T3", "furigana": "zhè wèi yī shēng de zhěn duàn hěn yǒu quán wēi xìng, dà jiā dōu xiāng xìn.", "sentence_source": "generated"}, {"text": "网上的消息没有书上的权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份数据出自国家统计局，它的权威性很高。", "target_word": "权威性", "complexity_tier": "T3", "furigana": "zhè fèn shù jù chū zì guó jiā tǒng jì jú, tā de quán wēi xìng hěn gāo.", "sentence_source": "generated"}, {"text": "老师的话为什么有权威性？", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书是名医写的，权威性很高。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年纪小，说话没有权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我更相信这个网站，因为它有权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做了二十年研究，说的话有权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子觉得妈妈的话最有权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "大家相信某人或某物说的是对的、真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '935c507d-9a1e-4188-bb8e-3e75cd8aa9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体积", "is_correct": false, "explanation": "体貌：“体积”描述物体的空间大小，不能用来形容说的话。"}, {"text": "形状", "is_correct": false, "explanation": "体貌：“形状”描述外形，说的话没有形状。"}, {"text": "权威性", "is_correct": true, "explanation": "符合语境：“很有权威性”表示大家相信他说的话是真的。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是人的形体数据，“很有身高”不成搭配。"}], "explanations": {"体积": "体貌：“体积”描述物体的空间大小，不能用来形容说的话。", "形状": "体貌：“形状”描述外形，说的话没有形状。", "权威性": "符合语境：“很有权威性”表示大家相信他说的话是真的。", "身高": "搭配：“身高”是人的形体数据，“很有身高”不成搭配。"}, "sentence_index": 0, "correct_answer": "权威性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的权威性很高，要五百块。", "explanation": "这里应该用〈价格〉。权威性指可信的程度，衣服卖多少钱要用〈价格〉。"}, {"text": "这条路的权威性很大，车很多。", "explanation": "这里应该用〈宽度〉。权威性指可信的程度，路面的宽窄要用〈宽度〉。"}, {"text": "这块石头的权威性很大，很重。", "explanation": "这里应该用〈重量〉。权威性指可信的程度，石头的分量要用〈重量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”与“年纪小”重复，说话没有年龄没有意义。"}, {"text": "权威性", "is_correct": true, "explanation": "符合语境：“年纪小”说明说话缺少使人相信的力量，与“没有权威性”呼应。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指受教育的经历，说话时谈不上有没有学历。"}, {"text": "籍贯", "is_correct": false, "explanation": "搭配：“籍贯”是出生地信息，“说话没有籍贯”不成搭配。"}], "explanations": {"年龄": "语义：“年龄”与“年纪小”重复，说话没有年龄没有意义。", "权威性": "符合语境：“年纪小”说明说话缺少使人相信的力量，与“没有权威性”呼应。", "学历": "语义：“学历”指受教育的经历，说话时谈不上有没有学历。", "籍贯": "搭配：“籍贯”是出生地信息，“说话没有籍贯”不成搭配。"}, "sentence_index": 6, "correct_answer": "权威性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的权威性很好，能跑很远。", "explanation": "这里应该用〈体力〉。权威性不能描述身体能力，跑远要用〈体力〉。"}, {"text": "她的权威性很漂亮，许多人喜欢她的样子。", "explanation": "这里应该用〈外貌〉。权威性指使人信服的力量，长相要用〈外貌〉。"}, {"text": "这个人的权威性很多，家里的钱都归他。", "explanation": "这里应该用〈财富〉。权威性不可计数，家里的钱财要用〈财富〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的话很权威性，大家都相信。", "corrected_sentence": "他的话很有权威性，大家都相信。", "error_description": "“很”修饰的是“有权威性”，前面需要动词“有”。正确说法是“他的话很有权威性，大家都相信。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份资料很有的权威性。", "corrected_sentence": "这份资料很有权威性。", "error_description": "“有”后面直接接名词“权威性”，中间不能加助词“的”；“很有的权威性”是错误说法。正确说法是“这份资料很有权威性。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
