INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "演奏者就是表演音乐的人。", "primary_collocate": null, "pronunciation": "yǎn zòu zhě", "ipa": "jɛn˨˩˦ tsou˥˩ tʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是一位很有名的钢琴演奏者。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者都穿着黑色的衣服。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小提琴演奏者站在舞台中间。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐队有五位演奏者。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者在台上拉了一首很美的曲子。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者的手指动得很快。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹想长大后做一个演奏者。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者向观众鞠了一躬。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的演奏者吸引了很多路人。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者每天都要练习好几个小时。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "钢琴演奏者", "label": "复合"}], "register": "中性", "sense_fingerprint": "表演音乐的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6e45d9-9c82-4a41-8650-3333a5ca1ff5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演奏者", "is_correct": true, "explanation": "演奏者指表演音乐的人，与“钢琴”搭配，指钢琴演奏家，句意通顺。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是做饭的人，与“钢琴”无关，句子说的是音乐表演者。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机是开车的人，不能是“钢琴”方面的人，句意不通。"}, {"text": "乐谱", "is_correct": false, "explanation": "搭配：“一位”用于指人，乐谱不能用“位”计量。"}], "explanations": {"演奏者": "演奏者指表演音乐的人，与“钢琴”搭配，指钢琴演奏家，句意通顺。", "厨师": "语义：厨师是做饭的人，与“钢琴”无关，句子说的是音乐表演者。", "司机": "语义：司机是开车的人，不能是“钢琴”方面的人，句意不通。", "乐谱": "搭配：“一位”用于指人，乐谱不能用“位”计量。"}, "sentence_index": 0, "correct_answer": "演奏者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的演奏者做的菜很好吃。", "explanation": "这里应该用〈厨师〉。饭馆里做菜的人是厨师，演奏者指表演音乐的人。"}, {"text": "这出话剧的演奏者演得很好。", "explanation": "这里应该用〈演员〉。话剧里表演的人称演员，演奏者只指表演音乐的人。"}, {"text": "这位演奏者在医院里给病人看病。", "explanation": "这里应该用〈医生〉。演奏者指表演音乐的人，给病人看病的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏者", "is_correct": true, "explanation": "演奏者是表演音乐的人，可以作为“做一个”的职业，句意通顺。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“做”后接的应是人或职业，乐器不能被“做”成职业。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录曲子的符号，不是可以去“做”的职业。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是看演出的人，不是职业，与“想长大后做”不符。"}], "explanations": {"演奏者": "演奏者是表演音乐的人，可以作为“做一个”的职业，句意通顺。", "乐器": "搭配：“做”后接的应是人或职业，乐器不能被“做”成职业。", "乐谱": "语义：乐谱是记录曲子的符号，不是可以去“做”的职业。", "观众": "语义：观众是看演出的人，不是职业，与“想长大后做”不符。"}, "sentence_index": 6, "correct_answer": "演奏者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场足球比赛中，那位演奏者踢进了两个球。", "explanation": "这里应该用〈球员〉。比赛中踢球进球的是球员，演奏者指表演音乐的人。"}, {"text": "这本小说的演奏者写了三年才写完。", "explanation": "这里应该用〈作者〉。写小说的人是作者，演奏者指表演音乐的人。"}, {"text": "这幅画的演奏者是一位年轻的女画家。", "explanation": "这里应该用〈作者〉。画画的人是画的作者，演奏者指表演音乐的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只钢琴演奏者刚刚获奖。", "corrected_sentence": "那位钢琴演奏者刚刚获奖。", "error_description": "量词错误：指人的“钢琴演奏者”应用“位”，“只”不用于计量人，应把“那只”改为“那位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很有才华演奏者在音乐会上很紧张。", "corrected_sentence": "这位很有才华的演奏者在音乐会上很紧张。", "error_description": "修饰语与中心语之间漏了“的”：“很有才华”修饰“演奏者”时要加“的”，应为“很有才华的演奏者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "升与降是一对反义词，升表示从下往上移动，与“直升机从山顶慢慢降到草地上”的方向相反。"}, {"text": "走", "is_correct": false, "explanation": "走指步行或行进，只表示移动，不是与“降”相对的方向义。"}, {"text": "飞", "is_correct": false, "explanation": "飞指在空中飞行，不是与“降”相对的方向义。"}, {"text": "跑", "is_correct": false, "explanation": "跑指快速移动，不表示与“降”相对的方向。"}], "correct_answer": "升", "explanations": {"升": "升与降是一对反义词，升表示从下往上移动，与“直升机从山顶慢慢降到草地上”的方向相反。", "走": "走指步行或行进，只表示移动，不是与“降”相对的方向义。", "飞": "飞指在空中飞行，不是与“降”相对的方向义。", "跑": "跑指快速移动，不表示与“降”相对的方向。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "升与降是一对反义词，表示从下往上移动，与“跳伞的人从飞机上降到草地”的方向相反。"}, {"text": "游", "is_correct": false, "explanation": "游指在水中游动，不表示与“降”相对的方向。"}, {"text": "站", "is_correct": false, "explanation": "站指站立不动，与“降”不构成反义关系。"}, {"text": "玩", "is_correct": false, "explanation": "玩指嬉戏娱乐，与“降”的移动方向无关。"}], "correct_answer": "升", "explanations": {"升": "升与降是一对反义词，表示从下往上移动，与“跳伞的人从飞机上降到草地”的方向相反。", "游": "游指在水中游动，不表示与“降”相对的方向。", "站": "站指站立不动，与“降”不构成反义关系。", "玩": "玩指嬉戏娱乐，与“降”的移动方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从上往下走。", "primary_collocate": null, "pronunciation": "jiàng", "ipa": "tɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我们坐缆车从山顶降到了山脚。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登山队完成任务后，从山顶降到了营地。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员用绳子从楼顶降到了三楼。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机从山顶慢慢降到了草地上。", "target_word": "降", "complexity_tier": "T3", "furigana": "zhí shēng jī cóng shān dǐng màn màn jiàng dào le cǎo dì shàng.", "sentence_source": "generated"}, {"text": "工人坐着吊篮，从高楼的顶部降到了地面。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伞兵从空中慢慢降到了地面。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吊车把大箱子从空中慢慢降到了船上。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，山顶的云慢慢降到了半山腰。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他顺着绳子从窗口降到了院子里。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳伞的人从飞机上降到了草地上。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "降了", "label": "体标（了）"}, {"form": "降过", "label": "体标（过）"}, {"form": "降落", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人或物沿着高处向下移动到低处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa6fc4b-3b94-4372-8dfa-3cb1d7e50379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "降 jiàng 指从上往下走，是本题的目标词。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，讲的意思是说话。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，江的意思是河流。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，奖的意思是奖励。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），见的意思是看见。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），向的意思是朝着。"}], "explanations": {"降": "降 jiàng 指从上往下走，是本题的目标词。", "讲": "jiǎng（第三声）与 jiàng（第四声）声调不同，讲的意思是说话。", "江": "jiāng（第一声）与 jiàng（第四声）声调不同，江的意思是河流。", "奖": "jiǎng（第三声）与 jiàng（第四声）声调不同，奖的意思是奖励。", "见": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），见的意思是看见。", "向": "xiàng 与 jiàng 声母不同（x 与 j），向的意思是朝着。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "降：有控制地从高处向低处移动，与缆车从山顶到山脚的下行相符。"}, {"text": "升", "is_correct": false, "explanation": "语义：升指向上移动，与从山顶到山脚的向下方向相反。"}, {"text": "飞", "is_correct": false, "explanation": "搭配：“飞”多用于鸟、飞机等能飞的东西，缆车载人不说“飞”。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔指意外跌落，与“坐缆车”这种有控制的下行矛盾。"}], "explanations": {"降": "降：有控制地从高处向低处移动，与缆车从山顶到山脚的下行相符。", "升": "语义：升指向上移动，与从山顶到山脚的向下方向相反。", "飞": "搭配：“飞”多用于鸟、飞机等能飞的东西，缆车载人不说“飞”。", "摔": "语义：摔指意外跌落，与“坐缆车”这种有控制的下行矛盾。"}, "sentence_index": 0, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着山路降到了山顶。", "explanation": "这里应该用〈上〉。上指向高处移动，到山顶是向上；降指向下移动，不能说“降到山顶”。"}, {"text": "他把画降到了墙上。", "explanation": "这里应该用〈挂〉。挂指把物体固定在高处，画挂在墙上；降指从高处向下移动，不能用来指挂画。"}, {"text": "他把书包降到了桌子上。", "explanation": "这里应该用〈放〉。放指把东西安置到某处，没有从上往下移动的意思；书包放在桌上不说降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "降 jiàng 指从上往下走，是本题的目标词。"}, {"text": "姜", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，姜的意思是生姜。"}, {"text": "健", "is_correct": false, "explanation": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），健的意思是健康。"}, {"text": "建", "is_correct": false, "explanation": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），建的意思是建造。"}, {"text": "项", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），项的意思是项目或条款。"}], "explanations": {"降": "降 jiàng 指从上往下走，是本题的目标词。", "姜": "jiāng（第一声）与 jiàng（第四声）声调不同，姜的意思是生姜。", "健": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），健的意思是健康。", "建": "jiàn 与 jiàng 韵尾不同（-n 与 -ng），建的意思是建造。", "项": "xiàng 与 jiàng 声母不同（x 与 j），项的意思是项目或条款。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "降：有控制地从高处慢慢移到低处，符合吊车把箱子吊到船上的动作。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”的主体是人或动物，不能用于大箱子。"}, {"text": "掉", "is_correct": false, "explanation": "语义：掉指意外落下，与“吊车慢慢”的受控动作矛盾。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”指在水中移动，不能用于吊车运送箱子。"}], "explanations": {"降": "降：有控制地从高处慢慢移到低处，符合吊车把箱子吊到船上的动作。", "跳": "搭配：“跳”的主体是人或动物，不能用于大箱子。", "掉": "语义：掉指意外落下，与“吊车慢慢”的受控动作矛盾。", "游": "搭配：“游”指在水中移动，不能用于吊车运送箱子。"}, "sentence_index": 6, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那块石头降到了河底。", "explanation": "这里应该用〈沉〉。石头在水里往下落到河底，要说“沉”；“降”不用来说物体在水中下沉。"}, {"text": "他从滑梯上降到了地上。", "explanation": "这里应该用〈滑〉。滑指顺着斜面滑下，滑梯上的人用“滑”；“降”指有控制地下降，不说这种滑下。"}, {"text": "杯子从桌上降到了地上。", "explanation": "这里应该用〈掉〉。掉指物体不慎落下，杯子从桌上落地用“掉”；“降”不用于不慎落下的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞机慢慢降了跑道上。", "corrected_sentence": "飞机慢慢降到了跑道上。", "error_description": "“降”后接处所要用“到”，应说“降到了跑道上”；漏掉“到”直接说“降了跑道上”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把木箱降了到地面上。", "corrected_sentence": "工人把木箱降到了地面上。", "error_description": "补语“到”之后才接“了”，应说“降到了地面上”；“了”放在“到”前说“降了到地面上”，语序不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22190, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
