INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "思考事情的规律和道理。", "primary_collocate": null, "pronunciation": "luó jí", "ipa": "lwɔ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他说话很有逻辑，大家都听得懂。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的逻辑不清楚。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的话没有逻辑，我听不明白。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学数学能让人更有逻辑。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的逻辑很简单：先做，再检查。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事的逻辑有问题，前后不一样。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师讲话的逻辑特别清楚。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照这个逻辑，我们应该早点出发。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法听起来有逻辑。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作文要注意逻辑，不能想到哪写到哪。", "target_word": "逻辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逻辑性", "label": "派生"}, {"form": "逻辑思维", "label": "复合"}], "register": "正式", "sense_fingerprint": "思考和说话时前后相连的道理和条理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逻辑", "is_correct": true, "explanation": "“有逻辑”指说话条理清楚、前后相连，符合“大家都听得懂”。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“成绩”指学习或工作取得的结果，不能用来形容说话。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，说话没有面积，“很有面积”不成立。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与说话无关，不能用来形容说话。"}], "explanations": {"逻辑": "“有逻辑”指说话条理清楚、前后相连，符合“大家都听得懂”。", "成绩": "搭配：“成绩”指学习或工作取得的结果，不能用来形容说话。", "面积": "语义：“面积”指平面的大小，说话没有面积，“很有面积”不成立。", "体温": "语义：“体温”指身体的温度，与说话无关，不能用来形容说话。"}, "sentence_index": 0, "correct_answer": "逻辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家的逻辑很大，住了三代人。", "explanation": "这里应该用〈房子〉。逻辑指思考的规律，不指房屋，应说“房子很大”。"}, {"text": "他没有来参加会议，逻辑是生病了。", "explanation": "这里应该用〈理由〉。逻辑是思考的规律，不能直接当作缺席的原因。"}, {"text": "这首歌的逻辑很好听，我每天都听。", "explanation": "这里应该用〈旋律〉。逻辑指思考和推理的规律，不用来形容歌曲好听，应说“旋律很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逻辑", "is_correct": true, "explanation": "“律师讲话的逻辑”指讲话的条理，可以说“特别清楚”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不是讲话的内容，不能“特别清楚”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高度，与讲话无关，不能说“讲话的身高特别清楚”。"}, {"text": "精力", "is_correct": false, "explanation": "搭配：“清楚”形容能看清或说明白的东西，不用来形容精力。"}], "explanations": {"逻辑": "“律师讲话的逻辑”指讲话的条理，可以说“特别清楚”。", "体重": "语义：“体重”指身体的重量，不是讲话的内容，不能“特别清楚”。", "身高": "语义：“身高”指人的高度，与讲话无关，不能说“讲话的身高特别清楚”。", "精力": "搭配：“清楚”形容能看清或说明白的东西，不用来形容精力。"}, "sentence_index": 6, "correct_answer": "逻辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盘菜的逻辑很咸，我吃不下去。", "explanation": "这里应该用〈味道〉。逻辑指思考和推理的规律，不用来描述菜的咸淡，应说“味道很咸”。"}, {"text": "这件衣服的逻辑很贵，我买不起。", "explanation": "这里应该用〈价格〉。逻辑指思考的规律，不指东西的价钱，应说“价格很贵”。"}, {"text": "他用逻辑把房子刷成了白色。", "explanation": "这里应该用〈油漆〉。逻辑指思考的规律，不能用来刷墙，刷墙要用“油漆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的话有很逻辑，大家都爱听。", "corrected_sentence": "她的话很有逻辑，大家都爱听。", "error_description": "错误：“有很逻辑”。副词“很”应放在“有”前面，正确形式是“很有逻辑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只逻辑很清楚，我们都听懂了。", "corrected_sentence": "这种逻辑很清楚，我们都听懂了。", "error_description": "错误：“这只逻辑”。“只”多用于动物，逻辑是抽象的，应该用“种”，正确形式是“这种逻辑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧", "is_correct": true, "explanation": "反义：旧指不新的、用过的，与“全新”相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：陡峭与全新不构成反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "无关：响亮与全新不构成反义关系。"}, {"text": "温柔", "is_correct": false, "explanation": "无关：温柔与全新不构成反义关系。"}], "correct_answer": "旧", "explanations": {"旧": "反义：旧指不新的、用过的，与“全新”相对。", "陡峭": "无关：陡峭与全新不构成反义关系。", "响亮": "无关：响亮与全新不构成反义关系。", "温柔": "无关：温柔与全新不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陈旧", "is_correct": true, "explanation": "反义：陈旧指旧的、过时的，与“全新”相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "无关：缓慢与全新不构成反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：寒冷与全新不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静与全新不构成反义关系。"}], "correct_answer": "陈旧", "explanations": {"陈旧": "反义：陈旧指旧的、过时的，与“全新”相对。", "缓慢": "无关：缓慢与全新不构成反义关系。", "寒冷": "无关：寒冷与全新不构成反义关系。", "安静": "无关：安静与全新不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "全部都是新的，没有旧的。", "primary_collocate": null, "pronunciation": "quán xīn", "ipa": "tɕʰɥɛn˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "我买了一部全新的手机。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋是全新的，我还没穿过。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的家具都是全新的。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新年到了，他换上全新的衣服。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑是全新的，一点儿也不旧。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校给每个班换了全新的桌子。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以后，我们要买全新的沙发。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧车卖了，开着全新的车回家。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子打开后，里面是全新的杯子。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给弟弟买了一辆全新的自行车。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全新的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "整个都是新的、没有用过的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6e45d9-9c82-4a41-8650-3333a5ca1ff5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全新", "is_correct": true, "explanation": "正确：全新指整个都是新的、没有用过，修饰“手机”，符合句意。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：手机没有情绪，“悲伤的手机”不成立。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”形容人或动物，不能修饰“手机”。"}, {"text": "苦涩", "is_correct": false, "explanation": "搭配：“苦涩”形容味道，不能修饰“手机”。"}], "explanations": {"全新": "正确：全新指整个都是新的、没有用过，修饰“手机”，符合句意。", "悲伤": "语义：手机没有情绪，“悲伤的手机”不成立。", "饥饿": "搭配：“饥饿”形容人或动物，不能修饰“手机”。", "苦涩": "搭配：“苦涩”形容味道，不能修饰“手机”。"}, "sentence_index": 0, "correct_answer": "全新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "清晨的山上空气很全新，吸一口很舒服。", "explanation": "这里应该用〈新鲜〉。全新说东西从未用过，空气的清爽要用新鲜。"}, {"text": "我的爷爷很全新，他都八十岁了。", "explanation": "这里应该用〈精神〉。全新指东西全部是新的，不能用来形容人；形容老人有活力要用精神。"}, {"text": "这双鞋穿过很多次，现在却是全新的。", "explanation": "这里应该用〈新〉。全新指从未用过；穿过很多次的鞋只能说还很新，不能说全新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全新", "is_correct": true, "explanation": "正确：全新表示从未用过的，与“买”搭配，符合句意。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“要买”与“免费”矛盾，买东西不能是免费的。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属变旧、损坏，与“搬家后要买新沙发”的语境矛盾。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：发霉的沙发不能拿来买，与“要买”的语境矛盾。"}], "explanations": {"全新": "正确：全新表示从未用过的，与“买”搭配，符合句意。", "免费": "语义：“要买”与“免费”矛盾，买东西不能是免费的。", "生锈": "语义：“生锈”指金属变旧、损坏，与“搬家后要买新沙发”的语境矛盾。", "发霉": "语义：发霉的沙发不能拿来买，与“要买”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "全新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台收音机用了五年，现在却是全新的。", "explanation": "这里应该用〈新〉。全新指从未用过；用了五年的收音机只能说外观还很新，不能说全新。"}, {"text": "我家的小猫很全新，它陪我们生活了三年。", "explanation": "这里应该用〈活泼〉。全新指东西全部是新的，不能用来形容动物；形容小猫的状态要用活泼。"}, {"text": "他讲的故事很全新，我们都没听过。", "explanation": "这里应该用〈新鲜〉。全新指东西从未用过、全部是新的，形容故事、想法让人感到新奇要用新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她穿上了一双全新了运动鞋。", "corrected_sentence": "她穿上了一双全新的运动鞋。", "error_description": "错误：“全新”后面接了“了”。正确：应为“全新的运动鞋”。形容词修饰名词时要用“的”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把厨房装修成了全新地样子。", "corrected_sentence": "他把厨房装修成了全新的样子。", "error_description": "错误：“全新”修饰名词“样子”时，结构助词用了“地”。正确：应为“全新的样子”。“地”用于修饰动词，修饰名词要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
