INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22196, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事说得特别重要。", "primary_collocate": null, "pronunciation": "qiáng diào", "ipa": "tɕʰjɑŋ˧˥ tjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老师一直强调要多说汉语。", "target_word": "强调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生强调我要多喝水。", "target_word": "强调", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈再三强调，出门要带钥匙。", "target_word": "强调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在会上强调了安全很重要。", "target_word": "强调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理强调这件事特别重要。", "target_word": "强调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想强调一点，迟到是不对的。", "target_word": "强调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书强调学习方法比时间更重要。", "target_word": "强调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他反复强调着同一个问题。", "target_word": "强调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说过很多次，他特别强调要按时交作业。", "target_word": "强调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告里强调这种牙膏对牙齿很好。", "target_word": "强调", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "强调了", "label": "体标"}, {"form": "强调过", "label": "体标"}, {"form": "強調", "label": "繁体"}], "register": "中性", "sense_fingerprint": "特别指出某事重要，要人注意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22196, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强调", "is_correct": true, "explanation": "强调（qiáng diào）：把一件事说得特别重要，即目标词。"}, {"text": "腔调", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是说话的腔调，不是强调。"}, {"text": "情调", "is_correct": false, "explanation": "qíng 比 qiáng 少一个 a 音（韵母不同），意思是情趣、格调，不是强调。"}, {"text": "强盗", "is_correct": false, "explanation": "dào 与 diào 相比少了介音 i，意思是抢劫财物的人，不是强调。"}], "explanations": {"强调": "强调（qiáng diào）：把一件事说得特别重要，即目标词。", "腔调": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是说话的腔调，不是强调。", "情调": "qíng 比 qiáng 少一个 a 音（韵母不同），意思是情趣、格调，不是强调。", "强盗": "dào 与 diào 相比少了介音 i，意思是抢劫财物的人，不是强调。"}, "sentence_index": null, "correct_answer": "强调"}, "level_3": {"options": [{"text": "强调", "is_correct": true, "explanation": "正确：「强调」表示反复说明要多说汉语，与「一直」的语境相合。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：「禁止」与「要多说汉语」的要求相反，句子变成禁止多说汉语。"}, {"text": "批评", "is_correct": false, "explanation": "语义：「批评」指指出错误，与「要多说汉语」的要求不合。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：「讨论」后面接的是议题，不接「要多说汉语」这样的行为要求。"}], "explanations": {"强调": "正确：「强调」表示反复说明要多说汉语，与「一直」的语境相合。", "禁止": "语义：「禁止」与「要多说汉语」的要求相反，句子变成禁止多说汉语。", "批评": "语义：「批评」指指出错误，与「要多说汉语」的要求不合。", "讨论": "搭配：「讨论」后面接的是议题，不接「要多说汉语」这样的行为要求。"}, "sentence_index": 0, "correct_answer": "强调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校强调了老师。", "explanation": "这里应该用〈重视〉。「强调」的宾语是观点或要求，不能直接指人；「重视」可以直接带人或事物。"}, {"text": "他强调地看了我一眼。", "explanation": "这里应该用〈仔细地〉。「强调地」修饰的是说话或表态，不能修饰「看」这类动作。"}, {"text": "他在饭店强调了一碗面。", "explanation": "这里应该用〈点〉。在饭店要饭菜说「点」，「强调」的宾语应是观点、要求或某事的重要性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强调", "is_correct": true, "explanation": "正确：「强调」表示把「学习方法比时间更重要」这一观点说得特别重要，句子通顺。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：「抱怨」的主语必须是有情绪的人，「这本书」是物体，不能抱怨。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」需要有意识的人作主语，书不能嘲笑别人的观点。"}, {"text": "完成", "is_correct": false, "explanation": "配价：「完成」要求接任务类宾语，不能直接接一个句子。"}], "explanations": {"强调": "正确：「强调」表示把「学习方法比时间更重要」这一观点说得特别重要，句子通顺。", "抱怨": "语义：「抱怨」的主语必须是有情绪的人，「这本书」是物体，不能抱怨。", "嘲笑": "语义：「嘲笑」需要有意识的人作主语，书不能嘲笑别人的观点。", "完成": "配价：「完成」要求接任务类宾语，不能直接接一个句子。"}, "sentence_index": 6, "correct_answer": "强调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他强调了高兴。", "explanation": "这里应该用〈表达〉。「强调」的宾语应是观点、要求或某事的重要性，「高兴」是情绪，说出感受要用「表达」。"}, {"text": "他把钥匙强调在包里。", "explanation": "这里应该用〈放〉。「强调」不能表示把东西放在某处，「把……强调在……里」不通。"}, {"text": "他强调成了大家的朋友。", "explanation": "这里应该用〈成为〉。「强调」不能带结果补语「成」，表示变成某种身份要说「成为」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师强调很清楚。", "corrected_sentence": "老师强调得很清楚。", "error_description": "错误：「强调很清楚」漏掉了补语标记「得」；正确：「强调得很清楚」，「得」引出程度补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个观点强调得两遍。", "corrected_sentence": "他把这个观点强调了两遍。", "error_description": "错误：「强调得两遍」中的「得」是程度补语标记，后面需要描述性的补语，这里表示动作完成，应用「了」；正确：「把这个观点强调了两遍」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭式", "is_correct": true, "explanation": "“封闭式”与“开放式”相反，指空间或设施不敞开，人不能自由进入使用。"}, {"text": "陈旧", "is_correct": false, "explanation": "“陈旧”指东西老旧，与“开放”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”说表面质地，与“开放”无关。"}, {"text": "懒散", "is_correct": false, "explanation": "“懒散”说人的作风，不是“开放”的反义词。"}], "correct_answer": "封闭式", "explanations": {"封闭式": "“封闭式”与“开放式”相反，指空间或设施不敞开，人不能自由进入使用。", "陈旧": "“陈旧”指东西老旧，与“开放”没有反义关系。", "粗糙": "“粗糙”说表面质地，与“开放”无关。", "懒散": "“懒散”说人的作风，不是“开放”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭式", "is_correct": true, "explanation": "“封闭式”与“开放式”相反，指空间或设施封闭，不允许人自由进入使用。"}, {"text": "狭小", "is_correct": false, "explanation": "“狭小”只说空间小，与“开放”不构成反义关系。"}, {"text": "单一", "is_correct": false, "explanation": "“单一”与“多样”相对，不是“开放”的反义词。"}, {"text": "独特", "is_correct": false, "explanation": "“独特”强调与众不同，与“开放”没有反义关系。"}], "correct_answer": "封闭式", "explanations": {"封闭式": "“封闭式”与“开放式”相反，指空间或设施封闭，不允许人自由进入使用。", "狭小": "“狭小”只说空间小，与“开放”不构成反义关系。", "单一": "“单一”与“多样”相对，不是“开放”的反义词。", "独特": "“独特”强调与众不同，与“开放”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以让人进去或使用，不关起来。", "primary_collocate": null, "pronunciation": "kāi fàng shì", "ipa": "kʰaɪ˥ fɑŋ˥˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "我家的厨房是开放式的，和客厅连在一起。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个开放式阳台没有墙，也没有玻璃窗。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的开放式图书馆，学生可以随便进去看书。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园是开放式的，没有大门，也不收门票。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放式的办公室里没有墙，同事们坐在一起。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在开放式的小区里，外面的人可以走进来。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放式厨房很流行，做饭时还能和家人聊天。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座开放式花园全天不关门，大家随时可以进来。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想要开放式的书架，不要带门的柜子。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开放式停车场不设大门，车可以随时开进开出。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开放式厨房", "label": "复合"}], "register": "中性", "sense_fingerprint": "空间或设施不封闭、不上锁、人可自由进出使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6e45d9-9c82-4a41-8650-3333a5ca1ff5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开放式", "is_correct": true, "explanation": "“开放式”指厨房不设墙、与客厅相通，与“和客厅连在一起”相符。"}, {"text": "封闭式", "is_correct": false, "explanation": "语义：“封闭式”厨房与客厅不相通，与“连在一起”矛盾。"}, {"text": "严实", "is_correct": false, "explanation": "体貌：“严实”形容遮挡得密不透风的样子，与“连在一起”的状态不符。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“独立”的厨房与客厅分开，与“连在一起”冲突。"}], "explanations": {"开放式": "“开放式”指厨房不设墙、与客厅相通，与“和客厅连在一起”相符。", "封闭式": "语义：“封闭式”厨房与客厅不相通，与“连在一起”矛盾。", "严实": "体貌：“严实”形容遮挡得密不透风的样子，与“连在一起”的状态不符。", "独立": "语义：“独立”的厨房与客厅分开，与“连在一起”冲突。"}, "sentence_index": 0, "correct_answer": "开放式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区是开放式的，大门却每天晚上都锁得紧紧的。", "explanation": "这里的“开放式”指可以进出、不关起来，句中却说大门每天晚上都锁得紧紧的，前后矛盾；此处应指“封闭式”。"}, {"text": "这扇窗户是开放式的，所以冬天一直紧紧关着。", "explanation": "这里的“开放式”指可以进出、不关起来，句中却说窗户冬天一直紧紧关着，前后矛盾；此处应指“封闭式”。"}, {"text": "我的姐姐是开放式的人，喜欢和陌生人聊天。", "explanation": "这里应该用〈开朗〉。形容性格用“开朗”，“开放式”只形容空间、设施或方式，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开放式", "is_correct": true, "explanation": "“开放式”厨房不设墙，做饭时可以和家人聊天，与后句相合。"}, {"text": "密闭式", "is_correct": false, "explanation": "语义：“密闭式”厨房与外界隔绝，做饭时无法和家人聊天，与后句矛盾。"}, {"text": "关闭的", "is_correct": false, "explanation": "语义：“关闭的”厨房把人隔在里面，与“还能和家人聊天”冲突。"}, {"text": "闭塞的", "is_correct": false, "explanation": "语义：“闭塞”的厨房与外界隔绝，做饭时难以和家人聊天，与后句矛盾。"}], "explanations": {"开放式": "“开放式”厨房不设墙，做饭时可以和家人聊天，与后句相合。", "密闭式": "语义：“密闭式”厨房与外界隔绝，做饭时无法和家人聊天，与后句矛盾。", "关闭的": "语义：“关闭的”厨房把人隔在里面，与“还能和家人聊天”冲突。", "闭塞的": "语义：“闭塞”的厨房与外界隔绝，做饭时难以和家人聊天，与后句矛盾。"}, "sentence_index": 6, "correct_answer": "开放式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店是开放式的，门口却一直锁着，顾客根本进不去。", "explanation": "这里的“开放式”指可以进入、不关起来，句中却说门口一直锁着、顾客进不去，前后矛盾；此处应指“封闭式”。"}, {"text": "这家店的老板是开放式的人，什么事都愿意听顾客的。", "explanation": "这里应该用〈随和〉。形容人的脾气用“随和”，“开放式”只形容空间、设施或方式，不用于人。"}, {"text": "他的心胸是开放式的，见到不同的人都很友好。", "explanation": "这里应该用〈开阔〉。形容心胸用“开阔”，不用“开放式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个花园是很开放式的，大家随时可以进来。", "corrected_sentence": "这个花园是开放式的，大家随时可以进来。", "error_description": "“开放式”是区别词，不能受“很”修饰，应去掉“很”，说“是开放式的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商场采用很开放式布局，顾客可以自由走动。", "corrected_sentence": "这家商场采用开放式布局，顾客可以自由走动。", "error_description": "“很”不能修饰“开放式”这类分类形容词，应说“采用开放式布局”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
