INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西出现或变成新的东西。", "primary_collocate": null, "pronunciation": "shēng chéng", "ipa": "ʂɤŋ˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个软件能生成漂亮的图片。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你输入名字，电脑就生成一个头像。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用电脑生成了一张新地图。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点击这里，系统会生成一份表格。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他让软件生成一段短音乐。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑生成过很多有趣的故事。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序生成了新的密码。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个怪物是用电脑特效生成的。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器每天生成一百个数字。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件没生成结果，大概是出错了。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生成了", "label": "完成体"}, {"form": "生成过", "label": "经历体"}, {"form": "自动生成", "label": "复合词"}], "register": "中性", "sense_fingerprint": "生成：让东西出现或变成新的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6de49e-72b6-4a2d-bfaf-3bbde5e3aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22206, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生成", "is_correct": true, "explanation": "生成：shēng chéng，让东西出现或变成新的东西。"}, {"text": "声称", "is_correct": false, "explanation": "第二个音节 chēng（第一声）与 chéng（第二声）声调不同，意思是宣称、断言。"}, {"text": "圣城", "is_correct": false, "explanation": "第一个音节 shèng（第四声）与 shēng（第一声）声调不同，意思是圣城、圣地。"}, {"text": "省城", "is_correct": false, "explanation": "第一个音节 shěng（第三声）与 shēng（第一声）声调不同，意思是省会城市。"}, {"text": "生辰", "is_correct": false, "explanation": "第二个音节 chén 与 chéng 韵尾不同（n 与 ng），声调相同，意思是出生的时辰或生日。"}], "explanations": {"生成": "生成：shēng chéng，让东西出现或变成新的东西。", "声称": "第二个音节 chēng（第一声）与 chéng（第二声）声调不同，意思是宣称、断言。", "圣城": "第一个音节 shèng（第四声）与 shēng（第一声）声调不同，意思是圣城、圣地。", "省城": "第一个音节 shěng（第三声）与 shēng（第一声）声调不同，意思是省会城市。", "生辰": "第二个音节 chén 与 chéng 韵尾不同（n 与 ng），声调相同，意思是出生的时辰或生日。"}, "sentence_index": null, "correct_answer": "生成"}, "level_3": {"options": [{"text": "生成", "is_correct": true, "explanation": "生成：能制作出漂亮的图片，符合“软件”的功能。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能唱图片。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，图片不能吃。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”搭配饮料，不说喝图片。"}], "explanations": {"生成": "生成：能制作出漂亮的图片，符合“软件”的功能。", "唱": "语义：“唱”的对象是歌曲，不能唱图片。", "吃": "语义：“吃”的对象是食物，图片不能吃。", "喝": "搭配：“喝”搭配饮料，不说喝图片。"}, "sentence_index": 0, "correct_answer": "生成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次争论生成了很大的影响。", "explanation": "这里应该用〈产生〉。“产生影响”是固定搭配，“生成”不能与“影响”搭配。"}, {"text": "爸爸每天早上生成一壶茶。", "explanation": "这里应该用〈泡〉。生成侧重让事物以程序或过程出现，泡茶要用泡。"}, {"text": "他用木头生成了一把椅子。", "explanation": "这里应该用〈制作〉。生成多指产出抽象或数字内容，手工做具体器物要用制作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生成", "is_correct": true, "explanation": "生成：程序产生了新的密码，与“程序”的功能相合。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”搭配桌面、污渍等，不说擦密码。"}, {"text": "劈", "is_correct": false, "explanation": "语义：劈是把东西剖开，与程序制作新密码的语义不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪，程序不会煮东西，密码也不能煮。"}], "explanations": {"生成": "生成：程序产生了新的密码，与“程序”的功能相合。", "擦": "搭配：“擦”搭配桌面、污渍等，不说擦密码。", "劈": "语义：劈是把东西剖开，与程序制作新密码的语义不合。", "煮": "语义：煮是烹饪，程序不会煮东西，密码也不能煮。"}, "sentence_index": 6, "correct_answer": "生成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂每天生成五百双鞋。", "explanation": "这里应该用〈生产〉。生成多指产出数据或抽象内容，工厂批量制造的产品要用生产。"}, {"text": "奶奶生成了一锅汤。", "explanation": "这里应该用〈煮〉。生成不用于烹饪，熬汤要用煮。"}, {"text": "施工队生成了一条隧道。", "explanation": "这里应该用〈建造〉。生成多用于产出抽象或数字内容，修建隧道等大型工程要用建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电脑能生成了一张漂亮的地图。", "corrected_sentence": "电脑能生成一张漂亮的地图。", "error_description": "“能”表示能力，后面的动词不加“了”。错误形式：能生成了一张地图；正确形式：能生成一张地图。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件生成地很快。", "corrected_sentence": "这个软件生成得很快。", "error_description": "补语标记错误：动词“生成”后接程度补语，要用“得”，不能用“地”。错误形式：生成地很快；正确形式：生成得很快。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22208, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "综合", "is_correct": true, "explanation": "《现代汉语词典》中，「分析」与「综合」互为反义：一个是拆开研究，一个是合起来看。"}, {"text": "种植", "is_correct": false, "explanation": "与「分析」没有反义或近义关系，是栽种植物的意思。"}, {"text": "游泳", "is_correct": false, "explanation": "与「分析」无关，是在水中运动的动作。"}, {"text": "修理", "is_correct": false, "explanation": "与「分析」无关，是修补物件的意思。"}], "correct_answer": "综合", "explanations": {"综合": "《现代汉语词典》中，「分析」与「综合」互为反义：一个是拆开研究，一个是合起来看。", "种植": "与「分析」没有反义或近义关系，是栽种植物的意思。", "游泳": "与「分析」无关，是在水中运动的动作。", "修理": "与「分析」无关，是修补物件的意思。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22208, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "综合", "is_correct": true, "explanation": "《现代汉语词典》中，「分析」与「综合」互为反义：一个是拆开研究，一个是合起来看。"}, {"text": "散步", "is_correct": false, "explanation": "与「分析」无关，是慢慢走路、活动身体的意思。"}, {"text": "装饰", "is_correct": false, "explanation": "与「分析」无关，是使物体更美观的意思。"}, {"text": "发射", "is_correct": false, "explanation": "与「分析」无关，是把物体射出去的意思。"}], "correct_answer": "综合", "explanations": {"综合": "《现代汉语词典》中，「分析」与「综合」互为反义：一个是拆开研究，一个是合起来看。", "散步": "与「分析」无关，是慢慢走路、活动身体的意思。", "装饰": "与「分析」无关，是使物体更美观的意思。", "发射": "与「分析」无关，是把物体射出去的意思。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22208, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一样东西分成几部分，看看它们是什么。", "primary_collocate": null, "pronunciation": "fēn xī", "ipa": "fən˥˥ ɕi˥˥", "syllable_count": 2, "sentences": [{"text": "老师请我们分析这个句子。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在分析他的血样。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先分析这个问题。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在分析这些数字。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你分析一下这首诗。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家分析了这种水，里面有很多盐。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们分析这篇文章，找出了几个主要部分。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要学会分析每个句子。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分析了这道题的每一步。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分析了一下这道菜的成分。", "target_word": "分析", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分析了", "label": "体标"}, {"form": "分析过", "label": "体标"}, {"form": "分析分析", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把事物分成几部分来研究", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分析", "is_correct": true, "explanation": "正确答案。「分析」（fēn xī）指把事物分成几部分来研究。"}, {"text": "分期", "is_correct": false, "explanation": "声母不同：「qī」与「xī」声母不同，意思是「分成若干时期」。"}, {"text": "分心", "is_correct": false, "explanation": "韵尾不同：「xīn」与「xī」只差韵尾 -n，意思是「注意力分散」。"}, {"text": "分歧", "is_correct": false, "explanation": "声母与声调都不同：「qí」（第二声）与「xī」（第一声），意思是「意见不一致」。"}], "explanations": {"分析": "正确答案。「分析」（fēn xī）指把事物分成几部分来研究。", "分期": "声母不同：「qī」与「xī」声母不同，意思是「分成若干时期」。", "分心": "韵尾不同：「xīn」与「xī」只差韵尾 -n，意思是「注意力分散」。", "分歧": "声母与声调都不同：「qí」（第二声）与「xī」（第一声），意思是「意见不一致」。"}, "sentence_index": null, "correct_answer": "分析"}, "level_3": {"options": [{"text": "分析", "is_correct": true, "explanation": "「分析」指把句子拆开研究其成分，符合「老师请我们」的语境。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：「烹饪」指做饭做菜，不能用于研究句子。"}, {"text": "种植", "is_correct": false, "explanation": "语义：「种植」用于植物，与「这个句子」不搭。"}, {"text": "洗涤", "is_correct": false, "explanation": "搭配：「洗涤」用于衣物、器皿，不能说洗涤句子。"}], "explanations": {"分析": "「分析」指把句子拆开研究其成分，符合「老师请我们」的语境。", "烹饪": "语义：「烹饪」指做饭做菜，不能用于研究句子。", "种植": "语义：「种植」用于植物，与「这个句子」不搭。", "洗涤": "搭配：「洗涤」用于衣物、器皿，不能说洗涤句子。"}, "sentence_index": 0, "correct_answer": "分析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司把奖金分析给员工。", "explanation": "这里应该用〈分配〉。「分析」指研究事物的道理或构成，不能表示把钱分给别人。"}, {"text": "我们用三种颜料分析出了这种颜色。", "explanation": "这里应该用〈调〉。「分析」指研究事物的构成，不指把颜料混合成颜色；混合颜料要用〈调〉。"}, {"text": "那个小孩不小心把饼干分析碎了。", "explanation": "这里应该用〈打碎〉。「分析」是研究道理，不表示把东西弄碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分析", "is_correct": true, "explanation": "「分析」指把文章拆开研究，找出主要部分，符合语境。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：「缝补」用于衣物等织物，不能用于文章。"}, {"text": "煎", "is_correct": false, "explanation": "语义：「煎」是烹饪动作，与「这篇文章」不搭。"}, {"text": "栽培", "is_correct": false, "explanation": "搭配：「栽培」多用于植物或人才，不说栽培文章。"}], "explanations": {"分析": "「分析」指把文章拆开研究，找出主要部分，符合语境。", "缝补": "语义：「缝补」用于衣物等织物，不能用于文章。", "煎": "语义：「煎」是烹饪动作，与「这篇文章」不搭。", "栽培": "搭配：「栽培」多用于植物或人才，不说栽培文章。"}, "sentence_index": 6, "correct_answer": "分析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分析了一下现在几点，然后就出门了。", "explanation": "这里应该用〈看〉。「分析」指研究事物的道理或构成，看时间只需看表，不需要分析。"}, {"text": "他分析了一下门，门就开了。", "explanation": "这里应该用〈推〉。「分析」指把事物分成部分来研究，不表示用手推开门的动作。"}, {"text": "他把衣服分析干净了，晾在外面。", "explanation": "这里应该用〈洗〉。「分析」是研究事物的构成，不能表示把衣服弄干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他分析很清楚。", "corrected_sentence": "他分析得很清楚。", "error_description": "漏掉补语的「得」。「分析」后面接表示程度的补语时，要用「得」连接，错误形式是「分析很清楚」，正确形式是「分析得很清楚」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想分析了这份报告的数据。", "corrected_sentence": "我想分析一下这份报告的数据。", "error_description": "时态助词用错。「想」表示意愿，后面的动作尚未发生，不能用「了」表示完成；应用「一下」表示短时间的尝试。错误形式是「想分析了」，正确形式是「想分析一下」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
