INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做数学题或电脑工作时，一步一步做事情的方法。", "primary_collocate": null, "pronunciation": "suàn fǎ", "ipa": "swan˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这道数学题有一个简单的算法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑按照算法一步一步工作。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写出了算法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个算法一共有五个步骤。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了一个更快的算法来算加法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李用新算法做完了这道题。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做电脑游戏要先想好算法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看得懂这个算法吗？", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的算法太慢，电脑算了很久。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算法写错了，电脑没法工作。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "新算法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "算法：做题或电脑工作时一步一步的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6de49e-72b6-4a2d-bfaf-3bbde5e3aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v