INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "算法", "is_correct": true, "explanation": "正确：“算法”是解题的简单步骤，与“数学题”搭配，符合句意。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：口袋是物件，不是解数学题的方法。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用来挡雨的物品，与数学题无关。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来形容数学题的解法。"}], "explanations": {"算法": "正确：“算法”是解题的简单步骤，与“数学题”搭配，符合句意。", "口袋": "语义：口袋是物件，不是解数学题的方法。", "雨伞": "语义：雨伞是用来挡雨的物品，与数学题无关。", "身材": "体貌：“身材”指人的体形，不能用来形容数学题的解法。"}, "sentence_index": 0, "correct_answer": "算法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想了一个好算法来减肥。", "explanation": "这里应该用〈方法〉。“算法”指计算或解题的步骤，减肥要用“方法”。"}, {"text": "这部电影的算法很感人，我看哭了。", "explanation": "这里应该用〈故事〉。“算法”指解题或电脑工作的步骤，不会感人；电影里让人感动的是故事。"}, {"text": "这台机器的算法很厚。", "explanation": "这里应该用〈说明书〉。“算法”是抽象的步骤，不能用“厚”来形容，指纸质材料才用“厚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "算法", "is_correct": true, "explanation": "正确：做游戏前要设计的是程序的算法，符合句意。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭与做电脑游戏的设计工作无关。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是做游戏时需要事先设计的内容。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“想好”一般接计划、方案、内容，与“饮料”搭配不当。"}], "explanations": {"算法": "正确：做游戏前要设计的是程序的算法，符合句意。", "午饭": "语义：午饭与做电脑游戏的设计工作无关。", "天气": "语义：天气不是做游戏时需要事先设计的内容。", "饮料": "搭配：“想好”一般接计划、方案、内容，与“饮料”搭配不当。"}, "sentence_index": 6, "correct_answer": "算法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的算法很长，我看了半天。", "explanation": "这里应该用〈菜单〉。“算法”指解题或做事的步骤，餐厅列出菜品的单子要用菜单。"}, {"text": "妈妈在厨房里做了一道算法，全家都说好吃。", "explanation": "这里应该用〈菜〉。“算法”指解题或做事的步骤，做出来能吃的东西要用菜。"}, {"text": "他把这首歌的算法唱得很好听。", "explanation": "这里应该用〈旋律〉。“算法”指解题或做事的步骤，歌曲的音乐线条要用旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
