INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于写了完这个算法。", "corrected_sentence": "他终于写完了这个算法。", "error_description": "补语错误：结果补语“完”应紧跟动词，说“写完了”，不能放在“了”后面说“写了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
