INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来记歌的书", "primary_collocate": null, "pronunciation": "yuè pǔ", "ipa": "ɥe˥˩ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在书店买了一本新乐谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本乐谱里有二十首儿童歌曲。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把乐谱翻到第十页。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的钢琴老师借给她一本乐谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的乐谱放在钢琴上面。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本乐谱很厚，里面都是老歌。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有很多外国歌曲的乐谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着一本旧乐谱去教室练歌。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把乐谱忘在家里了。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本乐谱的纸已经发黄了。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一本乐谱", "label": "量词"}, {"form": "樂譜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一本记着歌曲的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6de49e-72b6-4a2d-bfaf-3bbde5e3aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐谱", "is_correct": true, "explanation": "乐谱：一本印有歌曲的书，量词用“本”，书店可以买到。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴的量词是“架”，不说一本钢琴。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：书店不卖咖啡，咖啡也不是“本”能计量的东西。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：电脑的量词是“台”，不说一本电脑。"}], "explanations": {"乐谱": "乐谱：一本印有歌曲的书，量词用“本”，书店可以买到。", "钢琴": "搭配：钢琴的量词是“架”，不说一本钢琴。", "咖啡": "语义：书店不卖咖啡，咖啡也不是“本”能计量的东西。", "电脑": "搭配：电脑的量词是“台”，不说一本电脑。"}, "sentence_index": 0, "correct_answer": "乐谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的钢琴老师借给她一只乐谱。", "explanation": "这里应该用〈本〉。乐谱是书册，用“本”计量；“只”用于动物或成对物品中的一个。"}, {"text": "她的钢琴老师借给她一把乐谱。", "explanation": "这里应该用〈本〉。“把”用于有柄的器具，不能用于乐谱。"}, {"text": "她的钢琴老师借给她一棵乐谱。", "explanation": "这里应该用〈本〉。“棵”用于植物，不能用于乐谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐谱", "is_correct": true, "explanation": "乐谱：图书馆里能借到的、印有外国歌曲的书，与句意相合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是可以在图书馆里收藏的外国歌曲材料，与句意不合。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单上列的是菜品，与外国歌曲无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：外国歌曲不搭配冰箱，二者不能构成“……的”修饰关系。"}], "explanations": {"乐谱": "乐谱：图书馆里能借到的、印有外国歌曲的书，与句意相合。", "饮料": "语义：饮料不是可以在图书馆里收藏的外国歌曲材料，与句意不合。", "菜单": "语义：菜单上列的是菜品，与外国歌曲无关。", "冰箱": "搭配：外国歌曲不搭配冰箱，二者不能构成“……的”修饰关系。"}, "sentence_index": 6, "correct_answer": "乐谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台乐谱的纸已经发黄了。", "explanation": "这里应该用〈本〉。“台”用于机器、电器等，不能用于乐谱。"}, {"text": "我一口气读完了那块乐谱。", "explanation": "这里应该用〈本〉。“块”多用于块状物，乐谱是书册，不能用“块”计量。"}, {"text": "图书馆的那座乐谱很厚。", "explanation": "这里应该用〈本〉。“座”用于山、桥、建筑等，不能用于乐谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师送了我一首乐谱。", "corrected_sentence": "老师送了我一本乐谱。", "error_description": "量词错误：乐谱是书册，应用“本”，不能用“首”。错误形式：送了我一首乐谱；正确形式：送了我一本乐谱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把两双乐谱放进了书包。", "corrected_sentence": "我把两本乐谱放进了书包。", "error_description": "量词错误：乐谱应用“本”，“双”指成对的东西，不能用于乐谱。错误形式：两双乐谱；正确形式：两本乐谱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
