INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数据就是一些数字和事实。", "primary_collocate": null, "pronunciation": "shù jù", "ipa": "ʂu˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这组数据是老师昨天给我的。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把数据写在表格里。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先收集数据，再写报告。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据说明今年的雨很多。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的数据不见了，他很着急。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据不对，所以结果也不对。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看着数据，慢慢地点了点头。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天记录天气的数据。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份数据显示，很多人喜欢走路上班。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用数据来决定卖什么东西。", "target_word": "数据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一组数据", "label": "量词"}, {"form": "一份数据", "label": "量词"}, {"form": "数据库", "label": "复合"}, {"form": "大数据", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来说明情况的数字和事实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据", "is_correct": true, "explanation": "正确。“这组数据是老师昨天给我的”中，“数据”是老师给的数字和事实，与“组”的计量相符。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：“朋友”是人，老师不能把一组朋友“给我”，这句话的意思不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”一般用“套”“幢”计量，“这组房子”搭配不当。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心的感受，不能一组一组地由老师交给别人。"}], "explanations": {"数据": "正确。“这组数据是老师昨天给我的”中，“数据”是老师给的数字和事实，与“组”的计量相符。", "朋友": "语义：“朋友”是人，老师不能把一组朋友“给我”，这句话的意思不通。", "房子": "搭配：“房子”一般用“套”“幢”计量，“这组房子”搭配不当。", "心情": "语义：“心情”是内心的感受，不能一组一组地由老师交给别人。"}, "sentence_index": 0, "correct_answer": "数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想喝一杯数据。", "explanation": "这里应该用〈饮料〉。“数据”是数字和事实，不能被喝。"}, {"text": "他打开了这组数据，让风吹进来。", "explanation": "这里应该用〈窗户〉。“数据”是数字和事实，不能打开，也不能让风吹进来，应说“打开窗户”。"}, {"text": "这组数据很好听。", "explanation": "这里应该用〈歌曲〉。“数据”是数字和事实，不用来形容好听与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据", "is_correct": true, "explanation": "正确。“医生看着数据，慢慢地点了点头”中，“数据”是医生正在查看的内容，与语境相符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”一般不与“声音”搭配，“看着声音”不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”看不见摸不着，医生不会“看着空气”再点头，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不能与“味道”搭配，应该用“闻”来表示感知味道。"}], "explanations": {"数据": "正确。“医生看着数据，慢慢地点了点头”中，“数据”是医生正在查看的内容，与语境相符。", "声音": "搭配：“看”一般不与“声音”搭配，“看着声音”不成立。", "空气": "语义：“空气”看不见摸不着，医生不会“看着空气”再点头，句意不通。", "味道": "搭配：“看”不能与“味道”搭配，应该用“闻”来表示感知味道。"}, "sentence_index": 6, "correct_answer": "数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用数据炒了一盘菜。", "explanation": "这里应该用〈食材〉。“数据”是数字和事实，不能用来炒菜。"}, {"text": "下雨了，我打开数据走出了门。", "explanation": "这里应该用〈雨伞〉。“数据”是数字和事实，不能打开来挡雨。"}, {"text": "他的数据跑得很快。", "explanation": "这里应该用〈选手〉。“数据”不能做跑步的动作，这里误用了它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给了我一本数据。", "corrected_sentence": "老师给了我一份数据。", "error_description": "错误形式是“一本数据”，正确形式是“一份数据”。“本”用于书籍，“数据”一般用“份”或“组”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们收到了一座数据。", "corrected_sentence": "我们收到了一份数据。", "error_description": "错误形式是“一座数据”，正确形式是“一份数据”。“座”多用于山、桥等大型固定物，“数据”一般用“份”或“组”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破坏", "is_correct": true, "explanation": "破坏与创造相反，指使事物受损或毁坏，二者构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步与创造没有反义关系，二者意义无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与创造没有反义关系，二者意义无关。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与创造没有反义关系，二者意义无关。"}], "correct_answer": "破坏", "explanations": {"破坏": "破坏与创造相反，指使事物受损或毁坏，二者构成反义关系。", "散步": "散步与创造没有反义关系，二者意义无关。", "吃饭": "吃饭与创造没有反义关系，二者意义无关。", "游泳": "游泳与创造没有反义关系，二者意义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "毁灭", "is_correct": true, "explanation": "毁灭与创造相反，指使事物彻底消失，二者构成反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与创造没有反义关系，二者意义无关。"}, {"text": "读书", "is_correct": false, "explanation": "读书与创造没有反义关系，二者意义无关。"}, {"text": "画画", "is_correct": false, "explanation": "画画与创造没有反义关系，只是与画家的语境有关。"}], "correct_answer": "毁灭", "explanations": {"毁灭": "毁灭与创造相反，指使事物彻底消失，二者构成反义关系。", "跑步": "跑步与创造没有反义关系，二者意义无关。", "读书": "读书与创造没有反义关系，二者意义无关。", "画画": "画画与创造没有反义关系，只是与画家的语境有关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出以前没有的新东西。", "primary_collocate": null, "pronunciation": "chuàng zào", "ipa": "/ʈʂʰuɑŋ˥˩ tsɑʊ˥˩/", "syllable_count": 2, "sentences": [{"text": "这位画家创造了一种新的画法。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用纸创造出很多有意思的玩具。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老师能给学生创造学习的机会。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人创造了公司的第一个产品。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱迪生创造了很多有用的东西。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些工人为城市创造了很多财富。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想创造一个没有烦恼的新世界。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们在课上创造了一首新歌。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要自己创造好的生活。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他创造过三次世界纪录。", "target_word": "创造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创造了", "label": "体标：完成"}, {"form": "创造过", "label": "体标：经历"}, {"form": "创造力", "label": "复合"}], "register": "中性", "sense_fingerprint": "做出以前没有的新事物、新成绩或新条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e886baf2-6b8e-4ba4-b9ee-b0c12fe6a1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创造", "is_correct": true, "explanation": "正确：「创造」表示做出以前没有的新画法，与「一种新的画法」相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说吃画法。"}, {"text": "参观", "is_correct": false, "explanation": "语义：「参观」指去看地点或展览，不能用来指画家做出画法。"}, {"text": "继承", "is_correct": false, "explanation": "语义：「继承」指接受前人留下的东西，与「新的画法」矛盾。"}], "explanations": {"创造": "正确：「创造」表示做出以前没有的新画法，与「一种新的画法」相合。", "吃": "搭配：「吃」的对象是食物，不能说吃画法。", "参观": "语义：「参观」指去看地点或展览，不能用来指画家做出画法。", "继承": "语义：「继承」指接受前人留下的东西，与「新的画法」矛盾。"}, "sentence_index": 0, "correct_answer": "创造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天创造一千辆汽车。", "explanation": "这里应该用〈制造〉。「创造」强调做出以前没有的东西，大批量生产同类产品要用「制造」。"}, {"text": "学校创造了一场足球比赛。", "explanation": "这里应该用〈举办〉。「创造」指做出新事物，比赛这类活动要用「举办」。"}, {"text": "妈妈创造了一桌家常菜。", "explanation": "这里应该用〈做〉。「创造」偏重做出前所未有的东西，日常做饭用「做」即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创造", "is_correct": true, "explanation": "正确：「创造」指建立前所未有的新事物，与「一个新世界」相合。"}, {"text": "买", "is_correct": false, "explanation": "搭配：「买」的对象是可以买卖的东西，世界不能买。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食物或液体，世界不能煮。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」指拆开或拆毁具体物品，与「新世界」不合。"}], "explanations": {"创造": "正确：「创造」指建立前所未有的新事物，与「一个新世界」相合。", "买": "搭配：「买」的对象是可以买卖的东西，世界不能买。", "煮": "搭配：「煮」的对象是食物或液体，世界不能煮。", "拆": "语义：「拆」指拆开或拆毁具体物品，与「新世界」不合。"}, "sentence_index": 6, "correct_answer": "创造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次台风创造了很大的损失。", "explanation": "这里应该用〈造成〉。「创造」指有意做出好的新东西，不说「创造损失」；造成不好的结果要用「造成」。"}, {"text": "他在新学校创造了很多朋友。", "explanation": "这里应该用〈结交〉。「创造」不用于人际关系，交朋友要用「结交」。"}, {"text": "这支球队创造了观众的喜爱。", "explanation": "这里应该用〈赢得〉。「创造」针对做出的事物，观众的喜爱要用「赢得」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司创造了出很多工作机会。", "corrected_sentence": "这家公司创造出了很多工作机会。", "error_description": "错误形式「创造了出」：补语「出」应紧接动词，「了」放在补语之后，正确形式为「创造出了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团队创造了过一种新的治疗方法。", "corrected_sentence": "这个团队创造过一种新的治疗方法。", "error_description": "错误形式「创造了过」：「了」与「过」不能同时加在同一个动词后，正确形式为「创造过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
