INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22218, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或东西顶住，不让它倒下或掉下来。", "primary_collocate": null, "pronunciation": "zhī chēng", "ipa": "tʂʅ˥ tʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他用双手支撑着身体。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四根柱子支撑着屋顶。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树枝太重了，我们用木棍支撑它。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用肩膀支撑着快倒的架子。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的腿太细，支撑不住电视。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥下的石柱支撑着整座桥。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用拐杖支撑身体才能站稳。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪压弯了树枝，我们用竹竿支撑着。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两根杆子支撑着这顶帐篷。", "target_word": "支撑", "complexity_tier": "T3", "furigana": "liǎng gēn gān zi zhī chēng zhe zhè dǐng zhàng peng.", "sentence_source": "generated"}, {"text": "工人用木板支撑那面旧墙。", "target_word": "支撑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支撑着", "label": "体标"}, {"form": "支撑了", "label": "体标"}, {"form": "支撑过", "label": "体标"}], "register": "中性", "sense_fingerprint": "支撑：用手或物体顶住，防止倒下或掉落", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支撑", "is_correct": true, "explanation": "“支撑”指用手或物体顶住，使身体不倒，这里正是此义。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕不能用来顶住身体使其不倒，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象应是文字，不能说写身体。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与顶住身体不倒无关，句意不通。"}], "explanations": {"支撑": "“支撑”指用手或物体顶住，使身体不倒，这里正是此义。", "撕": "语义：撕不能用来顶住身体使其不倒，句意不通。", "写": "搭配：“写”的对象应是文字，不能说写身体。", "唱": "语义：唱歌与顶住身体不倒无关，句意不通。"}, "sentence_index": 0, "correct_answer": "支撑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们支撑你的决定。", "explanation": "这里应该用〈支持〉。支撑指用物体顶住使不倒，只用于具体的东西；赞成他人的决定要用“支持”。"}, {"text": "教授支撑了一场精彩的讲座。", "explanation": "这里应该用〈举办〉。支撑指用东西顶住使不倒，不能用于讲座；组织一场讲座要说举办。"}, {"text": "他每天都支撑跑步。", "explanation": "这里应该用〈坚持〉。支撑指顶住使不倒，不能用于跑步这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支撑", "is_correct": true, "explanation": "“支撑”指用物体顶住身体，使人能站稳，符合语境。"}, {"text": "摇", "is_correct": false, "explanation": "语义：摇动身体会使人站不稳，与“才能站稳”矛盾。"}, {"text": "捆", "is_correct": false, "explanation": "搭配：“捆”的对象多是物体，不能用拐杖去捆身体。"}, {"text": "量", "is_correct": false, "explanation": "语义：用拐杖量身体与站稳无关，句意不通。"}], "explanations": {"支撑": "“支撑”指用物体顶住身体，使人能站稳，符合语境。", "摇": "语义：摇动身体会使人站不稳，与“才能站稳”矛盾。", "捆": "搭配：“捆”的对象多是物体，不能用拐杖去捆身体。", "量": "语义：用拐杖量身体与站稳无关，句意不通。"}, "sentence_index": 6, "correct_answer": "支撑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察在路口支撑秩序。", "explanation": "这里应该用〈维持〉。秩序是抽象的，要说维持秩序；支撑指用东西顶住，不用于秩序。"}, {"text": "他支撑了一封长长的信。", "explanation": "这里应该用〈写〉。支撑指用东西顶住使不倒，不能用于信件；写信要说“写”。"}, {"text": "他支撑了全部责任。", "explanation": "这里应该用〈承担〉。承担责任要说“承担”，支撑只用于顶住具体的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两根木梁支撑着了这间旧房子。", "corrected_sentence": "两根木梁支撑着这间旧房子。", "error_description": "错误：“着”表示动作持续，“了”表示完成，二者不能叠用；“支撑着”已表示持续，后面不能再加“了”。应删去“了”，正确为“支撑着这间旧房子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几根木桩支撑了住那面墙。", "corrected_sentence": "几根木桩支撑住了那面墙。", "error_description": "错误：“了”放错了位置。补语“住”应紧跟动词，“了”放在“住”之后。应为“支撑住了那面墙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
