INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种表演，演员唱歌说话讲故事。", "primary_collocate": null, "pronunciation": "gē jù", "ipa": "kɤ˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "歌剧是演员一边唱歌一边讲故事的表演。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚剧院有一场歌剧，我们一起去吧。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部歌剧的故事很有意思。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌剧里的演员穿着漂亮的衣服。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看歌剧，一句也没听懂。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在歌剧里演一位公主。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌剧演到一半，观众都鼓起掌来。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷最爱看歌剧，每个月都去剧院。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在学校演了一场歌剧。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场歌剧一共三个小时。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场歌剧", "label": "量词"}, {"form": "一部歌剧", "label": "量词"}, {"form": "歌劇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "演员边唱边说讲故事的一场表演", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6de49e-72b6-4a2d-bfaf-3bbde5e3aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌剧", "is_correct": true, "explanation": "歌剧是唱说结合、讲故事的表演，正符合“演员一边唱歌一边讲故事”的描述。"}, {"text": "杂技", "is_correct": false, "explanation": "语义：杂技靠身体技巧表演，不靠唱歌讲故事，与句意不符。"}, {"text": "魔术", "is_correct": false, "explanation": "语义：魔术靠手法和道具变戏法，不靠唱歌讲故事。"}, {"text": "芭蕾", "is_correct": false, "explanation": "搭配：芭蕾靠舞蹈表现，不说“一边唱歌一边讲故事”。"}], "explanations": {"歌剧": "歌剧是唱说结合、讲故事的表演，正符合“演员一边唱歌一边讲故事”的描述。", "杂技": "语义：杂技靠身体技巧表演，不靠唱歌讲故事，与句意不符。", "魔术": "语义：魔术靠手法和道具变戏法，不靠唱歌讲故事。", "芭蕾": "搭配：芭蕾靠舞蹈表现，不说“一边唱歌一边讲故事”。"}, "sentence_index": 0, "correct_answer": "歌剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歌剧里的演员不用唱歌，只用说话表演。", "explanation": "这里应该用〈话剧〉。歌剧以唱为主，演员要唱歌，不能说“不用唱歌”。"}, {"text": "歌剧里的演员全靠跳舞，不说一句话。", "explanation": "这里应该用〈舞剧〉。歌剧主要靠歌唱，不靠跳舞，也不是完全不说话。"}, {"text": "歌剧里的演员在台上说相声，逗大家笑。", "explanation": "这里应该用〈相声〉。相声是说学逗唱的曲艺，不在歌剧里表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌剧", "is_correct": true, "explanation": "歌剧是一场表演，“演到一半”描述表演进程，观众中途鼓掌符合常理，句意成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是表演，“作业演到一半”说不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不能被“演”，观众也不会因为雨而鼓掌。"}, {"text": "体检", "is_correct": false, "explanation": "搭配：“演”接表演类事物，体检是检查，不能说“体检演到一半”。"}], "explanations": {"歌剧": "歌剧是一场表演，“演到一半”描述表演进程，观众中途鼓掌符合常理，句意成立。", "作业": "语义：作业不是表演，“作业演到一半”说不通。", "雨": "语义：雨不能被“演”，观众也不会因为雨而鼓掌。", "体检": "搭配：“演”接表演类事物，体检是检查，不能说“体检演到一半”。"}, "sentence_index": 6, "correct_answer": "歌剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场歌剧的选手在泳池里游了二十圈，观众为他们欢呼。", "explanation": "这里应该用〈游泳比赛〉。歌剧靠唱和说讲故事，选手在泳池里游泳，要用游泳比赛。"}, {"text": "这场歌剧的球员在草地上传球，观众一直为他们呐喊。", "explanation": "这里应该用〈足球赛〉。歌剧没有球员在草地上传球比赛；球员传球、观众呐喊要用足球赛。"}, {"text": "这场歌剧的演员在空中荡着秋千翻跟头，观众拍手叫好。", "explanation": "这里应该用〈杂技〉。歌剧靠唱和说讲故事，不靠空中翻跟头；荡秋千翻跟头是杂技。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年看过一只歌剧。", "corrected_sentence": "她去年看过一场歌剧。", "error_description": "量词错误：“歌剧”应用“场”，“只”用于动物或成对物品中的一个，不能用来数歌剧。错误形式：看过一只歌剧；正确形式：看过一场歌剧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天去看了一位歌剧，很精彩。", "corrected_sentence": "我们昨天去看了一场歌剧，很精彩。", "error_description": "量词错误：“歌剧”应该用“场”；“位”用于人，不能用来数歌剧。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9d378b-b7e8-4035-98f3-02073b3b9023') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
