INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22227, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做一件事看看它是不是会那样。", "primary_collocate": null, "pronunciation": "shí yàn", "ipa": "ʂʐ̩˧˥ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我想实验一下这个新办法。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在厨房里实验新菜谱。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢自己实验，不爱看说明书。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先实验一下，看看行不行。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生实验不同的学习方法。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把糖放进水里，想实验一下它多久会化。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用不同的颜色实验了很多次。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想实验一下这种新的护发油，看看头发会不会变亮。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做菜时，我喜欢实验新的做法。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先实验一下，不行再换。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实验了", "label": "完成体"}, {"form": "实验过", "label": "经历体"}, {"form": "实验一下", "label": "动量"}, {"form": "實驗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "亲自试做一件事，看结果是否如预想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实验", "is_correct": true, "explanation": "正确答案：实验（shí yàn），指亲自试做一件事看结果。"}, {"text": "食盐", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是食用的盐。"}, {"text": "食言", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是不守诺言。"}, {"text": "时延", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是信号传输的延迟。"}], "explanations": {"实验": "正确答案：实验（shí yàn），指亲自试做一件事看结果。", "食盐": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是食用的盐。", "食言": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是不守诺言。", "时延": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是信号传输的延迟。"}, "sentence_index": null, "correct_answer": "实验"}, "level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "正确：“实验一下这个新办法”指亲自试做，看看效果如何。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象通常是食物，不能与“办法”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，无法用于“办法”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能与“办法”搭配。"}], "explanations": {"实验": "正确：“实验一下这个新办法”指亲自试做，看看效果如何。", "吃": "搭配：“吃”的对象通常是食物，不能与“办法”搭配。", "唱": "语义：“唱”指发出歌声，无法用于“办法”。", "喝": "搭配：“喝”的对象是饮品，不能与“办法”搭配。"}, "sentence_index": 0, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仔细实验了这份报告。", "explanation": "这里应该用〈研究〉。实验指亲自试做看结果，不能用于阅读或分析书面材料。"}, {"text": "他每天认真实验英语。", "explanation": "这里应该用〈学习〉。实验是动手试做看结果，不用来指掌握语言知识。"}, {"text": "我想实验一下那位老师的心情。", "explanation": "这里应该用〈猜〉。实验指亲自试做看结果，不能用来揣测别人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "正确：“用不同的颜色实验”指试做不同的方案，看颜色的效果，与句意相符。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：演讲是讲话活动，不能用颜色作为工具。"}, {"text": "思考", "is_correct": false, "explanation": "语义：思考是脑力活动，不能用颜色来进行。"}, {"text": "写作", "is_correct": false, "explanation": "语义：写作要用文字，颜色不是写作的材料。"}], "explanations": {"实验": "正确：“用不同的颜色实验”指试做不同的方案，看颜色的效果，与句意相符。", "演讲": "语义：演讲是讲话活动，不能用颜色作为工具。", "思考": "语义：思考是脑力活动，不能用颜色来进行。", "写作": "语义：写作要用文字，颜色不是写作的材料。"}, "sentence_index": 6, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都在实验这幅画。", "explanation": "这里应该用〈欣赏〉。实验是亲自试做看结果，不用于观赏艺术品。"}, {"text": "妈妈想实验一下那本词典。", "explanation": "这里应该用〈查〉。实验指亲自试做看结果，不用于查阅词典。"}, {"text": "我们一起实验一下这场电影。", "explanation": "这里应该用〈观看〉。实验指做一件事看结果，不能用于看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这个办法实验着一下。", "corrected_sentence": "我把这个办法实验了一下。", "error_description": "体标记错误：动量补语“一下”前应用完成体“了”，“着”表示动作持续进行，不能用于已完成的一次尝试。应说“实验了一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他实验了完所有的办法。", "corrected_sentence": "他实验完了所有的办法。", "error_description": "结果补语位置错误：结果补语“完”应紧接动词“实验”，“了”放在“完”之后，应说“实验完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
