INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "教和学，就是老师讲课，学生学习。", "primary_collocate": null, "pronunciation": "jiào xué", "ipa": "tɕjɑʊ˥˩ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "教学就是老师讲课，学生听课。", "target_word": "教学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教学需要老师和学生一起努力。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师每天八点开始教学。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这节课的教学很清楚，我都听懂了。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教学时，老师常常问学生问题。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每个星期都检查教学。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小学做教学工作已经二十年了。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情期间，很多学校改成了网上教学。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会把教学变得很有意思。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教学不只是讲课，也要看学生学得怎么样。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教學", "label": "繁体"}, {"form": "教学法", "label": "复合"}, {"form": "教学楼", "label": "复合"}], "register": "中性", "sense_fingerprint": "教学|老师讲课与学生学习", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a63aca67-39cc-41c0-8a09-ede636634a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是装书本的袋子，不是教与学的活动，不能用来定义“教学”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是收入，不能与“老师讲课，学生听课”这样的活动构成定义。"}, {"text": "教学", "is_correct": true, "explanation": "“教学”指老师讲课、学生听课的过程，与句中定义完全一致。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是检查学习成果的活动，与“讲课、听课”不同，不能这样定义。"}], "explanations": {"书包": "语义：书包是装书本的袋子，不是教与学的活动，不能用来定义“教学”。", "工资": "搭配：“工资”是收入，不能与“老师讲课，学生听课”这样的活动构成定义。", "教学": "“教学”指老师讲课、学生听课的过程，与句中定义完全一致。", "考试": "语义：考试是检查学习成果的活动，与“讲课、听课”不同，不能这样定义。"}, "sentence_index": 0, "correct_answer": "教学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的教学很重，抬不动。", "explanation": "这里应该用〈行李〉。“很重，抬不动”形容有形的物品；教学是教与学的活动，不能抬。"}, {"text": "他每天教学晚饭，味道很好。", "explanation": "这里应该用〈烹饪〉。烹饪指做饭菜，教学指传授与学习，不能用来表示做饭。"}, {"text": "他的教学比我高很多。", "explanation": "这里应该用〈身高〉。身高指人的高矮，教学指教与学的活动，不能用来比较高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矿业", "is_correct": false, "explanation": "语义：矿业与小学无关，不可能在小学从事，与“在小学做”的句意冲突。"}, {"text": "航运", "is_correct": false, "explanation": "语义：航运是水上运输，与小学的工作环境不相容。"}, {"text": "教学", "is_correct": true, "explanation": "“做教学工作”指在小学教书，与“在小学”的语境相符。"}, {"text": "外贸", "is_correct": false, "explanation": "搭配：“小学”与“外贸”不搭，不说在小学做外贸。"}], "explanations": {"矿业": "语义：矿业与小学无关，不可能在小学从事，与“在小学做”的句意冲突。", "航运": "语义：航运是水上运输，与小学的工作环境不相容。", "教学": "“做教学工作”指在小学教书，与“在小学”的语境相符。", "外贸": "搭配：“小学”与“外贸”不搭，不说在小学做外贸。"}, "sentence_index": 6, "correct_answer": "教学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教学很大，能坐下八十个学生。", "explanation": "这里应该用〈教室〉。教室指上课的房间，教学指老师教、学生学的活动，不能指地点，“教学很大”不通。"}, {"text": "教学带队训练，很有经验。", "explanation": "这里应该用〈教练〉。教练指带领队员训练的人，教学是活动，不能做主语指人。"}, {"text": "这次失败给了我很大的教学。", "explanation": "这里应该用〈教训〉。教训指从失败中得到的经验，教学指课堂上的教与学，不能用来指失败带来的收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师跟教学很认真。", "corrected_sentence": "这位老师对教学很认真。", "error_description": "介词错误：表示对某事的态度要用“对”，应说“对教学很认真”，不说“跟教学很认真”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师地教学很认真。", "corrected_sentence": "这位老师的教学很认真。", "error_description": "结构助词错误：名词修饰语应用“的”连接，“地”用于修饰动词或形容词，应说“这位老师的教学很认真”，不说“这位老师地教学很认真”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
