INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22234, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22234, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或东西轮流着做事情，一方动了另一方再动。", "primary_collocate": null, "pronunciation": "jiāo hù", "ipa": "tɕjɑʊ˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "两个孩子交互传球，玩得很开心。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两只机械手交互动作，配合得很好。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左右两只脚交互向前迈步。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个舞者交互转圈，动作很整齐。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和小红交互递着积木。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队员交互掩护，慢慢向前走。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两台机器交互运转，一台停，另一台开。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人交互敲鼓，声音此起彼伏。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两只小狗交互追逐，在草地上跑。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双手交互拍球，球一直不停。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交互式", "label": "复合"}], "register": "书面", "sense_fingerprint": "双方轮流配合着动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a63aca67-39cc-41c0-8a09-ede636634a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝传球与“玩得很开心”的句意相矛盾，读起来不通。"}, {"text": "交互", "is_correct": true, "explanation": "“交互传球”指两个孩子轮流着传球，与“玩得很开心”相符。"}, {"text": "反对", "is_correct": false, "explanation": "语义：反对传球也与“玩得很开心”矛盾，不符合句中的快乐情景。"}, {"text": "遗忘", "is_correct": false, "explanation": "搭配：“遗忘”多用于事情或信息，“遗忘传球”这一动作搭配不当。"}], "explanations": {"拒绝": "语义：拒绝传球与“玩得很开心”的句意相矛盾，读起来不通。", "交互": "“交互传球”指两个孩子轮流着传球，与“玩得很开心”相符。", "反对": "语义：反对传球也与“玩得很开心”矛盾，不符合句中的快乐情景。", "遗忘": "搭配：“遗忘”多用于事情或信息，“遗忘传球”这一动作搭配不当。"}, "sentence_index": 0, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两人动作交互，一起举手。", "explanation": "这里应该用〈同步〉。同步指同时做同样的动作，交互指轮流着动，与“一起举手”相矛盾。"}, {"text": "他交互转圈，动作很整齐。", "explanation": "这里应该用〈独自〉。交互至少要两方轮流着动，一个人转圈只能说独自，不能说交互。"}, {"text": "两个队员交互冲过终点，很精彩。", "explanation": "这里应该用〈一起〉。一起指同时行动，交互指轮流着动，两人轮流冲过终点不合常理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同步", "is_correct": false, "explanation": "语义：同步是一起运转，与“一台停，另一台开”的句意相矛盾。"}, {"text": "交互", "is_correct": true, "explanation": "“交互运转”指两台机器轮流工作，与“一台停，另一台开”相符。"}, {"text": "持续", "is_correct": false, "explanation": "语义：持续运转与“一台停”矛盾，句子读起来不通。"}, {"text": "报废", "is_correct": false, "explanation": "搭配：“报废”指机器不能再用，不能修饰“运转”这一正在进行的动作。"}], "explanations": {"同步": "语义：同步是一起运转，与“一台停，另一台开”的句意相矛盾。", "交互": "“交互运转”指两台机器轮流工作，与“一台停，另一台开”相符。", "持续": "语义：持续运转与“一台停”矛盾，句子读起来不通。", "报废": "搭配：“报废”指机器不能再用，不能修饰“运转”这一正在进行的动作。"}, "sentence_index": 6, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两棵树交互站着，风一吹都摇晃。", "explanation": "这里应该用〈并排〉。并排指并列站立，交互指轮流着做动作，树不能轮流着动，不能说交互。"}, {"text": "他交互跳绳，跳得很高。", "explanation": "这里应该用〈独自〉。交互至少要两方轮流着动，一个人跳绳只能说独自，不能说交互。"}, {"text": "两个机器人交互摆手，同时举起手臂。", "explanation": "这里应该用〈同步〉。同步指同时做同样的动作，交互指轮流着动，与“同时举起手臂”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个同学很交互传递皮球，玩得很开心。", "corrected_sentence": "两个同学交互传递皮球，玩得很开心。", "error_description": "副词错误：“交互”是动词，前面不能加程度副词“很”，应删去“很”，说“交互传递皮球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个学生交互了朗读课文。", "corrected_sentence": "两个学生交互朗读课文。", "error_description": "体标错误：“了”不能插在“交互”和“朗读”之间，应删去，说“交互朗读课文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
