INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个人生活的地方，比如家、公园或者幼儿园。", "primary_collocate": null, "pronunciation": "huán jìng", "ipa": "xu̯an˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小明刚上幼儿园，对新环境很好奇。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在熟悉的环境里更放心。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新家以后，我还不熟悉周围的环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的环境很好，孩子们玩得很开心。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带宝宝看了看幼儿园的环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的环境干净，老人都爱在这儿散步。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看一下教室的环境，再决定要不要报名。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房以前，你最好去看看周围的环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗到了新环境，不吃也不喝。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢家附近的环境，每天都去走走。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活环境", "label": "复合"}], "register": "中性", "sense_fingerprint": "人日常所在的具体地方，如家、小区、公园、幼儿园", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63f12163-19cc-4b51-bb0d-63aa4777bd4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境", "is_correct": true, "explanation": "正确：环境指人日常所在的具体地方，幼儿园就是小明新的环境。"}, {"text": "公司", "is_correct": false, "explanation": "语义：小明刚上幼儿园，不是“新公司”的员工，与语境矛盾。"}, {"text": "薪资", "is_correct": false, "explanation": "语义：小明刚上幼儿园，对“新薪资”好奇说不通，与幼儿的语境不符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票不是小朋友接触的事物，与“刚上幼儿园”的语境不符。"}], "explanations": {"环境": "正确：环境指人日常所在的具体地方，幼儿园就是小明新的环境。", "公司": "语义：小明刚上幼儿园，不是“新公司”的员工，与语境矛盾。", "薪资": "语义：小明刚上幼儿园，对“新薪资”好奇说不通，与幼儿的语境不符。", "股票": "语义：股票不是小朋友接触的事物，与“刚上幼儿园”的语境不符。"}, "sentence_index": 0, "correct_answer": "环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个运动环境很努力，孩子们可以在这里跑步。", "explanation": "这里应该用〈教练〉。“努力”形容人的付出，环境不会努力；说教练很努力才自然。"}, {"text": "这家餐厅的环境很好吃，大家都爱来。", "explanation": "这里应该用〈菜〉。环境指周围的地方和条件，不指食物，不能说“好吃”；说菜好吃才自然。"}, {"text": "他的环境很开朗，大家都喜欢他。", "explanation": "这里应该用〈性格〉。环境指周围的地方和条件，不用来形容人的性格；说性格开朗才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境", "is_correct": true, "explanation": "正确：环境指人所处的具体地方，这里指教室，看一下教室环境再决定报名最自然。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是可以“看一下”的具体地方或设施，与“再决定要不要报名”的语境不搭。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人，不能说“教室的身高”。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：教室没有国籍，“看一下教室的国籍”说不通。"}], "explanations": {"环境": "正确：环境指人所处的具体地方，这里指教室，看一下教室环境再决定报名最自然。", "心情": "语义：心情不是可以“看一下”的具体地方或设施，与“再决定要不要报名”的语境不搭。", "身高": "搭配：“身高”只用于人，不能说“教室的身高”。", "国籍": "语义：教室没有国籍，“看一下教室的国籍”说不通。"}, "sentence_index": 6, "correct_answer": "环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个衣柜的环境很大，能放很多衣服。", "explanation": "这里应该用〈空间〉。环境指周围的地方和条件，不用来说容量或面积大小。"}, {"text": "这家超市的环境很聪明，学生们都爱来。", "explanation": "这里应该用〈店员〉。“聪明”形容人，环境不会聪明；说店员聪明才自然。"}, {"text": "这个孩子的环境长得很快，爸爸很高兴。", "explanation": "这里应该用〈身高〉。环境不会“长”，不能说长得快；说身高长得快才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子第一次来这里，对这条陌生环境有点害怕。", "corrected_sentence": "孩子第一次来这里，对这种陌生环境有点害怕。", "error_description": "错误：“条”用于细长的东西，不能修饰环境；正确的量词是“种”，应说“这种陌生环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近，家附近的环境好变了。", "corrected_sentence": "最近，家附近的环境变好了。", "error_description": "错误：结果补语“好”应放在动词“变”之后，说“变好了”，不能说“好变了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c75b3f-3630-4287-8fee-16b933667255') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22248, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22248, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22248, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走进别人事情里帮忙或改变。", "primary_collocate": null, "pronunciation": "jiè rù", "ipa": "tɕje˥˩ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "老师不想介入学生之间的小事。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察及时介入，两个人才不吵了。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是他们家里的事，别人不方便介入。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司出了问题，经理马上介入处理。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母不应该介入孩子的每个决定。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没有介入过这件事。", "target_word": "介入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国发生争吵时，第三方介入帮忙。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事太难，只好请专家介入。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵得很厉害，我不知道该不该介入。", "target_word": "介入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校介入以后，两个孩子很快和好了。", "target_word": "介入", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "介入了", "label": "体标"}, {"form": "介入过", "label": "体标"}], "register": "书面", "sense_fingerprint": "主动参与到别人的事情中去，帮忙处理或改变结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b874e5c-1605-4191-991e-5cc99b3cbbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说吃“小事”。"}, {"text": "介入", "is_correct": true, "explanation": "正确：“介入”指插手别人的事情，句意是老师不想参与学生之间的小事，符合语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是人或活动，不能说欢迎“小事”。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”的对象是衣物，不能说穿“小事”，句意不通。"}], "explanations": {"吃": "语义：“吃”的对象是食物，不能说吃“小事”。", "介入": "正确：“介入”指插手别人的事情，句意是老师不想参与学生之间的小事，符合语境。", "欢迎": "搭配：“欢迎”的对象是人或活动，不能说欢迎“小事”。", "穿": "语义：“穿”的对象是衣物，不能说穿“小事”，句意不通。"}, "sentence_index": 0, "correct_answer": "介入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天介入了一碗面。", "explanation": "这里应该用〈吃〉。“介入”指插手别人的事以改变局面，“一碗面”是要吃的食物，不能说介入。"}, {"text": "他们终于介入了那座大楼。", "explanation": "这里应该用〈进入〉。“介入”指插手别人的事以改变局面，走进大楼只是进入，不能用“介入”。"}, {"text": "他把全部精力介入到工作中。", "explanation": "这里应该用〈投入〉。“介入”强调插手别人的事以改变局面，把精力放进工作要用“投入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能指插手争端，“唱帮忙”的句意不成立。"}, {"text": "介入", "is_correct": true, "explanation": "正确：“介入”指第三方主动参与进来帮忙调解，符合句意。"}, {"text": "赞助", "is_correct": false, "explanation": "语义：“赞助”是提供钱或物资支持，不是在争吵中出面调解，与“帮忙”的语境不符。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：“旅行”指出行游玩，与“争吵时帮忙”的语境不符。"}], "explanations": {"唱": "语义：“唱”不能指插手争端，“唱帮忙”的句意不成立。", "介入": "正确：“介入”指第三方主动参与进来帮忙调解，符合句意。", "赞助": "语义：“赞助”是提供钱或物资支持，不是在争吵中出面调解，与“帮忙”的语境不符。", "旅行": "语义：“旅行”指出行游玩，与“争吵时帮忙”的语境不符。"}, "sentence_index": 6, "correct_answer": "介入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚介入了篮球队，每天都去训练。", "explanation": "这里应该用〈加入〉。“介入”指插手以改变局面，成为某个团队的成员要用“加入”。"}, {"text": "我在教室里介入老师讲课。", "explanation": "这里应该用〈听〉。“介入”是插手事情，听课不能说介入。"}, {"text": "他去超市介入了一些牛奶。", "explanation": "这里应该用〈买〉。“介入”指插手别人的事，买东西不能用“介入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们没有介入了那场争论。", "corrected_sentence": "我们没有介入那场争论。", "error_description": "错误形式：“没有介入了”；正确形式：“没有介入”。否定句中“了”不能与“没有”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师马上介入着他们的争吵。", "corrected_sentence": "老师马上介入了他们的争吵。", "error_description": "错误形式：“介入着”；正确形式：“介入了”。“马上介入”表示一下子完成的动作，不能用表示持续的“着”，应该用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
