INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22254, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "几个人在一起说一件事情，每个人都说自己的想法。", "primary_collocate": null, "pronunciation": "tǎo lùn", "ipa": "tʰaʊ˨˩˦ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "我们正在讨论明天的计划。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们围着桌子讨论问题。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家讨论了一个小时。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们分组讨论这篇文章。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我想和你讨论一下。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们讨论着去哪儿旅行。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家都在讨论价格。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们讨论过这个办法，但是没决定。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先别急，我们再讨论讨论。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末小组要讨论新的作业。", "target_word": "讨论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讨论了", "label": "体标"}, {"form": "讨论着", "label": "体标"}, {"form": "讨论过", "label": "体标"}, {"form": "讨论讨论", "label": "重叠"}, {"form": "讨论会", "label": "复合"}], "register": "中性", "sense_fingerprint": "几个人围绕一件事互相交流各自的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讨论", "is_correct": true, "explanation": "正确：“讨论”指大家交流各自的想法，与“明天的计划”相合。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想过去的事，与句中的“明天”冲突。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“计划”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“计划”搭配。"}], "explanations": {"讨论": "正确：“讨论”指大家交流各自的想法，与“明天的计划”相合。", "回忆": "语义：“回忆”指想过去的事，与句中的“明天”冲突。", "吃": "搭配：“吃”不能与“计划”搭配。", "洗": "搭配：“洗”不能与“计划”搭配。"}, "sentence_index": 0, "correct_answer": "讨论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人在屋里讨论了很久。", "explanation": "这里应该用〈思考〉。讨论需要几个人交流各自的想法，一个人独自想问题要用思考。"}, {"text": "我们在桌子上讨论了一杯茶。", "explanation": "这里应该用〈喝〉。讨论的对象是问题和想法，茶是要喝的，不能讨论茶。"}, {"text": "他用布讨论了桌子。", "explanation": "这里应该用〈擦〉。讨论的对象是问题和想法，用布清理桌面要用擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讨论", "is_correct": true, "explanation": "正确：“讨论”指大家交流各自的意见，开会时讨论价格符合语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多用于艺术作品或景色，不能说欣赏价格。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不能带“价格”作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能直接带“价格”作宾语。"}], "explanations": {"讨论": "正确：“讨论”指大家交流各自的意见，开会时讨论价格符合语境。", "欣赏": "搭配：“欣赏”多用于艺术作品或景色，不能说欣赏价格。", "扔": "搭配：“扔”不能带“价格”作宾语。", "睡": "配价：“睡”是不及物动词，后面不能直接带“价格”作宾语。"}, "sentence_index": 6, "correct_answer": "讨论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房讨论了碗。", "explanation": "这里应该用〈洗〉。讨论的是问题和想法，洗的是碗，不能讨论碗。"}, {"text": "他把画讨论在墙上。", "explanation": "这里应该用〈挂〉。讨论不表示把东西固定在某处，挂画要用挂。"}, {"text": "我们给花讨论水。", "explanation": "这里应该用〈浇〉。讨论的对象是问题和想法，给花加水要用浇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们讨论了着这次比赛的规则。", "corrected_sentence": "他们讨论着这次比赛的规则。", "error_description": "错误形式：“讨论了着”；正确形式：“讨论着”。“着”表示动作正在进行，与“了”重叠使用不通，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们热烈得讨论了这个问题。", "corrected_sentence": "我们热烈地讨论了这个问题。", "error_description": "错误形式：“热烈得讨论”；正确形式：“热烈地讨论”。修饰动词的状语要用“地”连接，“得”只用于动作或形容词之后的补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
