INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种用符号来表示想法、进行推理的学问，比如用字母代表句子。", "primary_collocate": null, "pronunciation": "fú hào luó jí", "ipa": "fu˧˥ xɑʊ˥˩ lwo˧˥ tɕi˧˥", "syllable_count": 4, "sentences": [{"text": "符号逻辑用符号表示人的想法。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在符号逻辑里，我们常用字母代表句子。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑课上，老师教我们用符号写想法。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得符号逻辑像一种特别的语言。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑里的符号，有的像数学符号。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对符号逻辑很感兴趣，每天都学一点。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门符号逻辑课，同学们都觉得很难。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐给我讲了什么是符号逻辑。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑中，用符号来写推理，可以看得更清楚。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了符号逻辑，我用符号来记想法。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "符號邏輯", "label": "繁体"}, {"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "用符号表示想法的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a63aca67-39cc-41c0-8a09-ede636634a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号逻辑", "is_correct": true, "explanation": "符号逻辑是用符号表示想法的学问，作主语指这门学问本身，搭配正确。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是固态的水，不能用符号表示人的想法。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能用符号表示人的想法。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜是食物，不能用符号表示人的想法。"}], "explanations": {"符号逻辑": "符号逻辑是用符号表示想法的学问，作主语指这门学问本身，搭配正确。", "冰块": "语义：冰块是固态的水，不能用符号表示人的想法。", "老虎": "语义：老虎是动物，不能用符号表示人的想法。", "蜂蜜": "语义：蜂蜜是食物，不能用符号表示人的想法。"}, "sentence_index": 0, "correct_answer": "符号逻辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很有符号逻辑。", "explanation": "这里应该用〈道理〉：“很有道理”指说话有根据；符号逻辑是用符号表示想法的学问，不能用来形容说话。"}, {"text": "符号逻辑很香，快尝尝。", "explanation": "这里应该用〈汤〉。“很香、快尝尝”形容食物；符号逻辑是学问，不能吃。"}, {"text": "符号逻辑是一种面粉做的点心。", "explanation": "这里应该用〈糕点〉：“面粉做的”指食品；符号逻辑是用符号表示想法的学问，不是食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号逻辑", "is_correct": true, "explanation": "符号逻辑是一门学问，“这门符号逻辑课”指这门课，与句子语境相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是学科，不能用作课程的名称。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是学科，不能作为课程的名称。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉是水果，不是学科，不能作为课程的名称。"}], "explanations": {"符号逻辑": "符号逻辑是一门学问，“这门符号逻辑课”指这门课，与句子语境相符。", "空气": "语义：空气不是学科，不能用作课程的名称。", "椅子": "语义：椅子是家具，不是学科，不能作为课程的名称。", "香蕉": "语义：香蕉是水果，不是学科，不能作为课程的名称。"}, "sentence_index": 6, "correct_answer": "符号逻辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的符号逻辑很快。", "explanation": "这里应该用〈节奏〉。“很快”描述音乐的节拍；符号逻辑是学问，不描述速度。"}, {"text": "这篇文章的符号逻辑很朴素。", "explanation": "这里“符号逻辑”是学问，不指文章的写法；“朴素”形容文风，应说〈语言〉。"}, {"text": "符号逻辑的颜色是红色的。", "explanation": "这里“符号逻辑”是学问，没有颜色；颜色用于〈图案〉这类有形的东西，不能用来描述学问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学了过符号逻辑，知道一些符号的用法。", "corrected_sentence": "我学过符号逻辑，知道一些符号的用法。", "error_description": "体标叠用错误：“了”和“过”不能同时用在同一动词后，经历体只用“过”，应说“学过符号逻辑”，删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年选了一把符号逻辑课。", "corrected_sentence": "我去年选了一门符号逻辑课。", "error_description": "量词错误：课程用“门”，“把”用于有柄的器具。应为“一门符号逻辑课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22258, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保持", "is_correct": false, "explanation": "与“融合”无反义关系，“保持”指维持原状，不是融合的反义词。"}, {"text": "分裂", "is_correct": true, "explanation": "与“融合”相反，指把整体分开，是本义项的反义词。"}, {"text": "挑选", "is_correct": false, "explanation": "与“融合”无反义关系，“挑选”指从中选取。"}, {"text": "扩展", "is_correct": false, "explanation": "与“融合”无反义关系，“扩展”指扩大范围。"}], "correct_answer": "分裂", "explanations": {"保持": "与“融合”无反义关系，“保持”指维持原状，不是融合的反义词。", "分裂": "与“融合”相反，指把整体分开，是本义项的反义词。", "挑选": "与“融合”无反义关系，“挑选”指从中选取。", "扩展": "与“融合”无反义关系，“扩展”指扩大范围。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22258, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "固定", "is_correct": false, "explanation": "与“融合”无反义关系，“固定”指使不再移动。"}, {"text": "分裂", "is_correct": true, "explanation": "与“融合”相反，指把整体分开，是本义项的反义词。"}, {"text": "摘取", "is_correct": false, "explanation": "与“融合”无反义关系，“摘取”指把东西取下来。"}, {"text": "收缩", "is_correct": false, "explanation": "与“融合”无反义关系，“收缩”指变小或变短。"}], "correct_answer": "分裂", "explanations": {"固定": "与“融合”无反义关系，“固定”指使不再移动。", "分裂": "与“融合”相反，指把整体分开，是本义项的反义词。", "摘取": "与“融合”无反义关系，“摘取”指把东西取下来。", "收缩": "与“融合”无反义关系，“收缩”指变小或变短。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的东西合在一起变成一样。", "primary_collocate": null, "pronunciation": "róng hé", "ipa": "/ɻʊŋ˧˥ xɤ˧˥/", "syllable_count": 2, "sentences": [{"text": "这道菜融合了中西方的味道。", "target_word": "融合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想把两种音乐融合在一起。", "target_word": "融合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和油很难融合。", "target_word": "融合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个城市融合了新和旧的文化。", "target_word": "融合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅把中国菜和法国菜融合得很好。", "target_word": "融合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种文化慢慢融合，变成了新的文化。", "target_word": "融合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的画融合着东方和西方的风格。", "target_word": "融合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的颜色放在一起，会融合成新的颜色。", "target_word": "融合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌融合了流行和古典。", "target_word": "融合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两种风格融合以后，形成了一种新的特色。", "target_word": "融合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "融合了", "label": "体标"}, {"form": "融合着", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：不同的事物合在一起，成为一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品尝", "is_correct": false, "explanation": "配价：“品尝”的主语须是人，“这道菜”不能作为品尝的人。"}, {"text": "融合", "is_correct": true, "explanation": "正确：“融合”指把中西方味道合为一体，符合句意。"}, {"text": "分辨", "is_correct": false, "explanation": "配价：“分辨”要求有人去辨认，“这道菜”自身不能分辨味道。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与菜式把两种味道合为一体的语境不符。"}], "explanations": {"品尝": "配价：“品尝”的主语须是人，“这道菜”不能作为品尝的人。", "融合": "正确：“融合”指把中西方味道合为一体，符合句意。", "分辨": "配价：“分辨”要求有人去辨认，“这道菜”自身不能分辨味道。", "讨厌": "语义：“讨厌”表示反感，与菜式把两种味道合为一体的语境不符。"}, "sentence_index": 0, "correct_answer": "融合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快融合了那张旧桌子。", "explanation": "这里应该用〈修理〉。融合指不同事物合为一体，旧桌子坏了要修理，不会与别的东西融合。"}, {"text": "他融合了两只小猫。", "explanation": "这里应该用〈抱〉。融合指不同事物合为一体，两只小猫不会融合，应说抱。"}, {"text": "他融合了很多邮票。", "explanation": "这里应该用〈收集〉。收集指把东西聚拢保存；融合指不同事物混为一体，邮票不会融合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与画作把东西方风格结合的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“风格”搭配，画不能吃风格。"}, {"text": "融合", "is_correct": true, "explanation": "正确：“融合”指把东西方风格合为一体，符合句意。"}, {"text": "背诵", "is_correct": false, "explanation": "配价：“背诵”要求有人或文本作对象，画作不能背诵风格。"}], "explanations": {"拒绝": "语义：“拒绝”表示不接受，与画作把东西方风格结合的语境相反。", "吃": "搭配：“吃”不能与“风格”搭配，画不能吃风格。", "融合": "正确：“融合”指把东西方风格合为一体，符合句意。", "背诵": "配价：“背诵”要求有人或文本作对象，画作不能背诵风格。"}, "sentence_index": 6, "correct_answer": "融合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套家具可以融合成一张大桌子。", "explanation": "这里应该用〈组合〉。组合指零件拼装后各自保留形态；融合要求事物混为一体，拼装的部件不会融合。"}, {"text": "冰块遇热后就融合了。", "explanation": "这里应该用〈融化〉。融化指固体受热变成液体；融合指不同事物合为一体，冰块受热不是与别的东西合在一起。"}, {"text": "这把伞融合了雨水。", "explanation": "这里应该用〈挡〉。融合指不同事物合为一体，伞是用来挡雨的，不与雨水融合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种颜色融合到了一种新的颜色。", "corrected_sentence": "这两种颜色融合成了一种新的颜色。", "error_description": "补语错误：表示变成新事物应用“成”，“融合到了一种新的颜色”不自然，应为“融合成了一种新的颜色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位画家的风格融合着以后，形成了一种新的流派。", "corrected_sentence": "两位画家的风格融合以后，形成了一种新的流派。", "error_description": "体标错误：“以后”指已经完成的事件，“融合”后不能加“着”，应去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
