INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物经过较长时间慢慢发生的变化。", "primary_collocate": null, "pronunciation": "biàn qiān", "ipa": "pjɛn˥˩ tɕʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "这座老城几十年来的变迁很大。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷见证了小镇几十年的变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一个家庭的变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从老照片里能看出街道的变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河在百年里经历了很多变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会发生了很大的变迁，人们的生活也不同了。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里的老照片记录了城市的变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶最清楚这个村子几十年来的变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言也会随着时代发生变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢讲起家乡的变迁。", "target_word": "变迁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變遷", "label": "繁体"}], "register": "书面", "sense_fingerprint": "变迁：事物经过较长时间慢慢发生的变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47c36c6a-10d1-484f-a144-0a730fa56e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变迁", "is_correct": true, "explanation": "正确答案：变迁（biàn qiān），指较长时间里慢慢发生的变化。"}, {"text": "变天", "is_correct": false, "explanation": "t 与 q 声母不同，声调相同（第一声），意思是天气转变。"}, {"text": "变浅", "is_correct": false, "explanation": "qiǎn（第三声）与 qiān（第一声）声调不同，意思是变得浅。"}, {"text": "变尖", "is_correct": false, "explanation": "jiān 与 qiān 声母不同（j / q），意思是变得尖锐。"}], "explanations": {"变迁": "正确答案：变迁（biàn qiān），指较长时间里慢慢发生的变化。", "变天": "t 与 q 声母不同，声调相同（第一声），意思是天气转变。", "变浅": "qiǎn（第三声）与 qiān（第一声）声调不同，意思是变得浅。", "变尖": "jiān 与 qiān 声母不同（j / q），意思是变得尖锐。"}, "sentence_index": null, "correct_answer": "变迁"}, "level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：名字不能说“很大”，也不是几十年里慢慢发生的变化。"}, {"text": "变迁", "is_correct": true, "explanation": "变迁：几十年来慢慢发生的变化，正好填入句中的空格。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：形容历史常说「长」或「悠久」，不说「很大」。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：形容速度常说「快」或「慢」，不说「很大」。"}], "explanations": {"名字": "语义：名字不能说“很大”，也不是几十年里慢慢发生的变化。", "变迁": "变迁：几十年来慢慢发生的变化，正好填入句中的空格。", "历史": "搭配：形容历史常说「长」或「悠久」，不说「很大」。", "速度": "搭配：形容速度常说「快」或「慢」，不说「很大」。"}, "sentence_index": 0, "correct_answer": "变迁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子今天早上到晚上的变迁很大。", "explanation": "这里应该用〈变化〉。变迁指长时间里慢慢发生的变化，一天之内的起伏要用变化。"}, {"text": "这个城市的人口在一夜之间有了很大的变迁。", "explanation": "这里应该用〈巨变〉。变迁指长时间慢慢形成的变化，“一夜之间”的剧变应用巨变。"}, {"text": "股市这一周有了较大的变迁。", "explanation": "这里应该用〈变动〉。变迁用于长期慢慢发生的变化，一周之内的涨跌起伏要用变动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22264, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "变迁", "is_correct": true, "explanation": "正确答案：变迁（biàn qiān），指较长时间里慢慢发生的变化。"}, {"text": "电签", "is_correct": false, "explanation": "diàn 与 biàn 声母不同（d / b），意思是电子签名或电子签证。"}, {"text": "面签", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m / b），声调相同，意思是当面签署。"}, {"text": "便笺", "is_correct": false, "explanation": "jiān 与 qiān 声母不同（j / q），声调相同（第一声），意思是便条纸。"}], "explanations": {"变迁": "正确答案：变迁（biàn qiān），指较长时间里慢慢发生的变化。", "电签": "diàn 与 biàn 声母不同（d / b），意思是电子签名或电子签证。", "面签": "miàn 与 biàn 声母不同（m / b），声调相同，意思是当面签署。", "便笺": "jiān 与 qiān 声母不同（j / q），声调相同（第一声），意思是便条纸。"}, "sentence_index": null, "correct_answer": "变迁"}, "level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：老照片只能记录影像，不能记录声音。"}, {"text": "变迁", "is_correct": true, "explanation": "变迁：长时间里城市慢慢发生的变化，正好填入句中的空格。"}, {"text": "身材", "is_correct": false, "explanation": "语义：「身材」指人的体形，不能用来说城市。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程是教授的内容，不是可以被照片记录下来的东西。"}], "explanations": {"声音": "语义：老照片只能记录影像，不能记录声音。", "变迁": "变迁：长时间里城市慢慢发生的变化，正好填入句中的空格。", "身材": "语义：「身材」指人的体形，不能用来说城市。", "课程": "语义：课程是教授的内容，不是可以被照片记录下来的东西。"}, "sentence_index": 6, "correct_answer": "变迁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家在一夜之间遭遇了一场变迁。", "explanation": "这里应该用〈变故〉。变故指突然发生的重大事件，变迁是长时间慢慢发生的变化，不能用于突发事件。"}, {"text": "这次旅行是我最难忘的变迁。", "explanation": "这里应该用〈经历〉。变迁指事物长期慢慢发生的变化，不指个人亲身遇到的一次事情。"}, {"text": "这块石头在一分钟之内就有了很大的变迁。", "explanation": "这里应该用〈变化〉。变迁指长时间慢慢形成的变化，一分钟之内的变化应用变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子在最近几十年里进行了很大的变迁。", "corrected_sentence": "这个村子在最近几十年里发生了很大的变迁。", "error_description": "错误形式是「进行了」，正确形式是「发生了」。「进行」用于有目的的活动，如改革、调查；变迁是自然发生的变化，应说「发生了很大的变迁」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河经历了一只漫长的变迁。", "corrected_sentence": "这条河经历了一段漫长的变迁。", "error_description": "量词错误：“只”用于动物等，不能修饰“变迁”，应改为“段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
