INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "事物本身，尤其是主体部分，不包括附件，也不是它的照片。", "primary_collocate": null, "pronunciation": "běn tǐ", "ipa": "pən˨˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "这只是照片，不是它的本体。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个报价只包括相机本体，不包括镜头。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的壳很漂亮，本体却很旧。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具的本体是木头做的，外面涂着红色。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台吸尘器本体很小，配件却很多。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盒子是新的，里面的本体却坏了。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片上的月亮和月亮本体不一样。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只买了游戏机本体，没有买手柄。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先检查一下机器本体有没有问题。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台相机本体很轻，镜头却很重。", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "本體", "label": "繁体"}], "register": "通用", "sense_fingerprint": "事物本身或其主体，区别于附件与照片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db84973e-d904-419a-b58d-917694db0a8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本体", "is_correct": true, "explanation": "正确。“照片”不是事物本身，所以“不是它的本体”成立。"}, {"text": "体温", "is_correct": false, "explanation": "语义：照片没有体温，“不是它的体温”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：照片没有寿命可谈，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”与“照片”不搭配，照片没有可以品尝的味道。"}], "explanations": {"本体": "正确。“照片”不是事物本身，所以“不是它的本体”成立。", "体温": "语义：照片没有体温，“不是它的体温”说不通。", "寿命": "语义：照片没有寿命可谈，句意不通。", "味道": "搭配：“味道”与“照片”不搭配，照片没有可以品尝的味道。"}, "sentence_index": 0, "correct_answer": "本体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的本体很大，很多人都做不出来。", "explanation": "这里应该用〈难度〉。本体指事物本身，不指题目的难易程度；说题目难不难要用难度。"}, {"text": "这次旅行的本体很贵，我付不起。", "explanation": "这里应该用〈费用〉。本体指事物本身，不能用来说花钱多少；说花费要用「费用」。"}, {"text": "今天的本体很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。本体指事物本身，不能用来说天气的好坏；说天气要用「天气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本体", "is_correct": true, "explanation": "正确。“月亮本体”指月亮本身，与照片上的月亮相对，所以句意成立。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：月亮没有节奏可以比较，“月亮节奏不一样”说不通。"}, {"text": "芳香", "is_correct": false, "explanation": "搭配：“芳香”多用于花、香料，不与“月亮”搭配。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：月亮不是乐器，句中谈的是月亮本身，“乐器”不成立。"}], "explanations": {"本体": "正确。“月亮本体”指月亮本身，与照片上的月亮相对，所以句意成立。", "节奏": "语义：月亮没有节奏可以比较，“月亮节奏不一样”说不通。", "芳香": "搭配：“芳香”多用于花、香料，不与“月亮”搭配。", "乐器": "语义：月亮不是乐器，句中谈的是月亮本身，“乐器”不成立。"}, "sentence_index": 6, "correct_answer": "本体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃本体，所以身体很健康。", "explanation": "这里应该用〈食物〉。本体指事物本身，不能拿来吃；吃的东西要说食物。"}, {"text": "妈妈今天给我穿本体，很合身。", "explanation": "这里应该用〈衣服〉。本体指事物本身，不能拿来穿；穿的东西要说衣服。"}, {"text": "他每天唱本体，大家都很喜欢听。", "explanation": "这里应该用〈歌〉。本体指事物本身，不能拿来唱；唱的要说歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一张相机本体，镜头另外买。", "corrected_sentence": "我买了一个相机本体，镜头另外买。", "error_description": "量词“张”用错了。“张”用于纸、桌子等平面的东西，相机本体是立体的器物，应该说“一个相机本体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她只买了一张空气炸锅本体，配件另外买。", "corrected_sentence": "她只买了一台空气炸锅本体，配件另外买。", "error_description": "量词“张”用错了。“张”用于纸、桌子等平面的东西，空气炸锅本体是机器，应该说“一台空气炸锅本体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
