INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来做事情的东西，比如锤子、笔。", "primary_collocate": null, "pronunciation": "gōng jù", "ipa": "kʊŋ˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸用这件工具修好了自行车。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车需要很多工具。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工具放在桌子上了。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑是我工作时最常用的工具。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有合适的工具，这个螺丝拧不开。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木匠的工具都整整齐齐地放在箱子里。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借了邻居的工具来修门。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些工具都是用铁做的。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完工具，请放回原来的地方。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们拿着小工具在花园里挖土。", "target_word": "工具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件工具", "label": "量词"}, {"form": "一套工具", "label": "量词"}, {"form": "工具书", "label": "复合"}, {"form": "工具箱", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来做事的东西，如锤子、笔", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工具", "is_correct": true, "explanation": "正确。工具（gōngjù）指用来做事的东西，与句子语境相符。"}, {"text": "功绩", "is_correct": false, "explanation": "jì（第四声）与 jù（第四声）韵母不同（i 与 ü），意思是功绩，指功劳和业绩。"}, {"text": "工序", "is_correct": false, "explanation": "xù（第四声）与 jù（第四声）声母不同（x 与 j），意思是工序，指生产中的步骤。"}, {"text": "公路", "is_correct": false, "explanation": "lù（第四声）与 jù（第四声）声母不同（l 与 j），意思是公路。"}], "explanations": {"工具": "正确。工具（gōngjù）指用来做事的东西，与句子语境相符。", "功绩": "jì（第四声）与 jù（第四声）韵母不同（i 与 ü），意思是功绩，指功劳和业绩。", "工序": "xù（第四声）与 jù（第四声）声母不同（x 与 j），意思是工序，指生产中的步骤。", "公路": "lù（第四声）与 jù（第四声）声母不同（l 与 j），意思是公路。"}, "sentence_index": null, "correct_answer": "工具"}, "level_3": {"options": [{"text": "工具", "is_correct": true, "explanation": "正确。“用这件工具修好了自行车”中，工具是修理用的器具，与修车的语境相符。"}, {"text": "作品", "is_correct": false, "explanation": "语义：“作品”指文艺或创作的成果，不能用来修自行车。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“用……修好”的手段应是器具，“礼物”不能作为修理自行车的手段。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“衣服”是穿的东西，不能用来修自行车，这句话的意思不通。"}], "explanations": {"工具": "正确。“用这件工具修好了自行车”中，工具是修理用的器具，与修车的语境相符。", "作品": "语义：“作品”指文艺或创作的成果，不能用来修自行车。", "礼物": "搭配：“用……修好”的手段应是器具，“礼物”不能作为修理自行车的手段。", "衣服": "语义：“衣服”是穿的东西，不能用来修自行车，这句话的意思不通。"}, "sentence_index": 0, "correct_answer": "工具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用工具和敌人作战，所以这次很成功。", "explanation": "这里应该用〈武器〉。“工具”指做事用的器具，不能用来和敌人作战，这里应换成“武器”。"}, {"text": "我渴了，想喝一杯工具。", "explanation": "这里应该用〈水〉。“工具”是用来做事的东西，不能喝。"}, {"text": "这幅画是他最珍贵的工具。", "explanation": "这里应该用〈作品〉。“工具”指用来做事的器物，画作是创作成果，不能称为工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "工具", "is_correct": true, "explanation": "正确。工具（gōngjù）指用来做事的东西，与句子语境相符。"}, {"text": "公墓", "is_correct": false, "explanation": "mù（第四声）与 jù（第四声）声母不同（m 与 j），意思是公墓。"}, {"text": "耕具", "is_correct": false, "explanation": "gēng 与 gōng 韵母不同（e 与 o），意思是耕具，指耕种用的农具。"}, {"text": "公寓", "is_correct": false, "explanation": "yù（第四声）与 jù（第四声）声母不同（有无 j），意思是公寓。"}], "explanations": {"工具": "正确。工具（gōngjù）指用来做事的东西，与句子语境相符。", "公墓": "mù（第四声）与 jù（第四声）声母不同（m 与 j），意思是公墓。", "耕具": "gēng 与 gōng 韵母不同（e 与 o），意思是耕具，指耕种用的农具。", "公寓": "yù（第四声）与 jù（第四声）声母不同（有无 j），意思是公寓。"}, "sentence_index": null, "correct_answer": "工具"}, "level_3": {"options": [{"text": "工具", "is_correct": true, "explanation": "正确。“我借了邻居的工具来修门”中，工具是修门用的器具，与语境相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是修门的器具，借房子来修门的说法不通。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”是吃的东西，不能用来修门，与句意矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“借……来修门”的手段应是器具，“玩具”与“修门”不搭配。"}], "explanations": {"工具": "正确。“我借了邻居的工具来修门”中，工具是修门用的器具，与语境相符。", "房子": "语义：“房子”不是修门的器具，借房子来修门的说法不通。", "食物": "语义：“食物”是吃的东西，不能用来修门，与句意矛盾。", "玩具": "搭配：“借……来修门”的手段应是器具，“玩具”与“修门”不搭配。"}, "sentence_index": 6, "correct_answer": "工具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做的工具很好吃，我们都爱吃。", "explanation": "这里应该用〈食物〉。“工具”指做事用的器具，不能用来形容味道好不好，应说“妈妈做的菜很好吃”。"}, {"text": "天冷了，我穿上了一件工具。", "explanation": "这里应该用〈外套〉。“工具”是用来做事的东西，不是穿的衣服。"}, {"text": "我家的工具每天早上都会叫我起床。", "explanation": "这里应该用〈小狗〉或〈闹钟〉的说法不合适时可用〈妈妈〉。“工具”是没有生命的东西，不会叫人起床。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一粒工具。", "corrected_sentence": "他买了一套工具。", "error_description": "错误形式是“一粒工具”，正确形式是“一套工具”。“粒”用于米、沙等细小颗粒，“工具”一般用“套”或“件”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷修车时拿出了一条工具。", "corrected_sentence": "爷爷修车时拿出了一件工具。", "error_description": "错误形式是“一条工具”，正确形式是“一件工具”。“条”多用于长而细的东西，“工具”一般用“件”或“套”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22272, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "现实：与“想象”构成反义，指客观存在的真实情况，与在脑中构想的事物相对。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是具体的家具，与“想象”这个意思没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然景物，与“想象”这个意思没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园是具体的场所，与“想象”这个意思没有反义关系。"}], "correct_answer": "现实", "explanations": {"现实": "现实：与“想象”构成反义，指客观存在的真实情况，与在脑中构想的事物相对。", "桌子": "桌子是具体的家具，与“想象”这个意思没有反义关系。", "河流": "河流是自然景物，与“想象”这个意思没有反义关系。", "花园": "花园是具体的场所，与“想象”这个意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22272, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "现实：与“想象”构成反义，指客观存在的真实情况，与在脑中构想的事物相对。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是具体的建筑部件，与“想象”这个意思没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头是具体的物体，与“想象”这个意思没有反义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "钥匙是具体的工具，与“想象”这个意思没有反义关系。"}], "correct_answer": "现实", "explanations": {"现实": "现实：与“想象”构成反义，指客观存在的真实情况，与在脑中构想的事物相对。", "窗户": "窗户是具体的建筑部件，与“想象”这个意思没有反义关系。", "石头": "石头是具体的物体，与“想象”这个意思没有反义关系。", "钥匙": "钥匙是具体的工具，与“想象”这个意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在心里画出一幅画面。", "primary_collocate": null, "pronunciation": "xiǎng xiàng", "ipa": "ɕjɑŋ˨˩ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你能想象一下十年后的生活吗？", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无法想象没有手机的日子。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭上眼睛，想象自己在海边。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们常常想象自己是小鸟。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家比我想象的大得多。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能想象到他会一个人去旅行？", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着这张照片，我想象着当时的热闹场面。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你想象一下，你是老板会怎么做。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么冷的冬天，我真想象不出夏天的样子。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读小说时，我常常想象人物的样子。", "target_word": "想象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想象了", "label": "体标"}, {"form": "想象过", "label": "体标"}, {"form": "想象着", "label": "体标"}, {"form": "想象想象", "label": "重叠"}, {"form": "想象力", "label": "复合"}], "register": "中性", "sense_fingerprint": "在脑海中构想没有见到的人、事或景象；动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想象", "is_correct": true, "explanation": "想象：xiǎng xiàng，在脑海中构想没有见过的人、事或景象。"}, {"text": "想想", "is_correct": false, "explanation": "想想：xiǎng xiang，后一音节为轻声，与 xiàng（第四声）声调不同，意思是思考。"}, {"text": "相像", "is_correct": false, "explanation": "相像：xiāng xiàng，第一音节 xiāng（第一声）与 xiǎng（第三声）声调不同，意思是相似。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮：xiǎng liàng，第二音节声母不同，liàng 与 xiàng 的声母分别是 l 和 x，意思是声音大而清楚。"}, {"text": "相向", "is_correct": false, "explanation": "相向：xiāng xiàng，第一音节 xiāng（第一声）与 xiǎng（第三声）声调不同，意思是面对面。"}], "explanations": {"想象": "想象：xiǎng xiàng，在脑海中构想没有见过的人、事或景象。", "想想": "想想：xiǎng xiang，后一音节为轻声，与 xiàng（第四声）声调不同，意思是思考。", "相像": "相像：xiāng xiàng，第一音节 xiāng（第一声）与 xiǎng（第三声）声调不同，意思是相似。", "响亮": "响亮：xiǎng liàng，第二音节声母不同，liàng 与 xiàng 的声母分别是 l 和 x，意思是声音大而清楚。", "相向": "相向：xiāng xiàng，第一音节 xiāng（第一声）与 xiǎng（第三声）声调不同，意思是面对面。"}, "sentence_index": null, "correct_answer": "想象"}, "level_3": {"options": [{"text": "想象", "is_correct": true, "explanation": "想象：在脑中构想没见过的景象。“十年后的生活”尚未发生，只能靠想象。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指对已经发生的事的追想，“十年后”尚未发生，无从回忆。"}, {"text": "观察", "is_correct": false, "explanation": "搭配：“观察”接的是眼前可以看到的对象，不能接“十年后的生活”这种尚未发生的事。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指对过去的人或事的思念，与“十年后”的未来相矛盾。"}], "explanations": {"想象": "想象：在脑中构想没见过的景象。“十年后的生活”尚未发生，只能靠想象。", "回忆": "语义：“回忆”指对已经发生的事的追想，“十年后”尚未发生，无从回忆。", "观察": "搭配：“观察”接的是眼前可以看到的对象，不能接“十年后的生活”这种尚未发生的事。", "怀念": "语义：“怀念”指对过去的人或事的思念，与“十年后”的未来相矛盾。"}, "sentence_index": 0, "correct_answer": "想象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我亲眼想象了那场事故。", "explanation": "这里应该用〈目睹〉。“想象”是在脑中构想没有见到的景象，与“亲眼”自相矛盾。"}, {"text": "这道题的答案，他很快想象出来了。", "explanation": "这里应该用〈算〉。答案要通过计算得到，不能靠想象得出，“想象”只用于构想画面。"}, {"text": "我在抽屉里想象出了一张旧照片。", "explanation": "这里应该用〈找〉。照片是真实存在的，要靠寻找得到，“想象”只能用于构想不存在或没见过的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22272, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "想象", "is_correct": true, "explanation": "想象：xiǎng xiàng，在脑海中构想没有见过的人、事或景象。"}, {"text": "现象", "is_correct": false, "explanation": "现象：xiàn xiàng，第一音节 xiàn（第四声）与 xiǎng（第三声）的韵母和声调都不同，意思是可以观察到的事物表现。"}, {"text": "显像", "is_correct": false, "explanation": "显像：xiǎn xiàng，第一音节 xiǎn 与 xiǎng 韵母不同（an 与 ang），意思是图像的显示。"}, {"text": "小象", "is_correct": false, "explanation": "小象：xiǎo xiàng，第一音节 xiǎo 与 xiǎng 韵母不同（ao 与 ang），意思是幼小的大象。"}], "explanations": {"想象": "想象：xiǎng xiàng，在脑海中构想没有见过的人、事或景象。", "现象": "现象：xiàn xiàng，第一音节 xiàn（第四声）与 xiǎng（第三声）的韵母和声调都不同，意思是可以观察到的事物表现。", "显像": "显像：xiǎn xiàng，第一音节 xiǎn 与 xiǎng 韵母不同（an 与 ang），意思是图像的显示。", "小象": "小象：xiǎo xiàng，第一音节 xiǎo 与 xiǎng 韵母不同（ao 与 ang），意思是幼小的大象。"}, "sentence_index": null, "correct_answer": "想象"}, "level_3": {"options": [{"text": "想象", "is_correct": true, "explanation": "想象：在脑中构想。照片只能看到，当时的热闹场面要靠想象。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”接的是正在取景的对象，而“这张照片”已经拍好，不能说拍摄。"}, {"text": "预见", "is_correct": false, "explanation": "语义：“预见”指对将来的事提前看到，而“当时”的场面已经过去。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”接的是建筑或设施，不能接“热闹场面”，句意不通。"}], "explanations": {"想象": "想象：在脑中构想。照片只能看到，当时的热闹场面要靠想象。", "拍摄": "搭配：“拍摄”接的是正在取景的对象，而“这张照片”已经拍好，不能说拍摄。", "预见": "语义：“预见”指对将来的事提前看到，而“当时”的场面已经过去。", "拆除": "搭配：“拆除”接的是建筑或设施，不能接“热闹场面”，句意不通。"}, "sentence_index": 6, "correct_answer": "想象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在词典里想象出了这个词的意思。", "explanation": "这里应该用〈查〉。词典里的意思是现成的，要靠查找得到，不能靠想象。"}, {"text": "工人用尺子想象出了桌子的长度。", "explanation": "这里应该用〈量〉。长度要靠测量得到，“想象”不能用于得出可以测量的数据。"}, {"text": "他想象出了整篇课文，一字不差。", "explanation": "这里应该用〈背〉。课文要靠记忆背下来，“想象”不能表示记住已有的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你想象得这个房间的样子吗？", "corrected_sentence": "你想象得出这个房间的样子吗？", "error_description": "补语错误：表示能不能想到要用可能补语「想象得出」，漏掉「出」后「想象得这个房间的样子」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没想象了自己成为作家。", "corrected_sentence": "我从没想象过自己成为作家。", "error_description": "“从没”表示从未有过的经历，应与“过”搭配，写作“想象过”。错句用“了”，与“从没”的语境不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22274, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无限", "is_correct": true, "explanation": "无限与有限意义相反，指没有限度。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚与“有限”没有反义关系，指明白、不模糊。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明与“有限”意义无关，指智力好。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜与“有限”意义无关，指价格低。"}], "correct_answer": "无限", "explanations": {"无限": "无限与有限意义相反，指没有限度。", "清楚": "清楚与“有限”没有反义关系，指明白、不模糊。", "聪明": "聪明与“有限”意义无关，指智力好。", "便宜": "便宜与“有限”意义无关，指价格低。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22274, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22274, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指东西不多，或者不能一直做下去。", "primary_collocate": null, "pronunciation": "yǒu xiàn", "ipa": "i̯ou˨˩˦ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我的时间有限，不能陪你去了。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱很有限。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里的座位有限，要早点去。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的汉语水平有限，请你慢慢说。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的选择很有限。", "target_word": "有限", "complexity_tier": "T3", "furigana": "zhè jiā xiǎo diàn de xuǎn zé hěn yǒu xiàn。", "sentence_source": "generated"}, {"text": "我们的力量有限，不能帮所有人。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的名额有限。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的经验有限，做不好这件事。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的时间有限，一次只能回答三个问题。", "target_word": "有限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的电量有限，你别玩游戏了。", "target_word": "有限", "complexity_tier": "T3", "furigana": "shǒu jī de diàn liàng yǒu xiàn, nǐ bié wán yóu xì le。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有限公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量、范围、时间等有限度，不多；形容词义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有限", "is_correct": true, "explanation": "正确答案：有限（yǒu xiàn），指数量、范围、时间不多。"}, {"text": "有效", "is_correct": false, "explanation": "xiào（第四声）与 xiàn（第四声）韵母不同（-iao 与 -ian），意思是有效果、起作用。"}, {"text": "涌现", "is_correct": false, "explanation": "yǒng（第三声）与 yǒu（第三声）韵母不同（-ong 与 -ou），意思是大量地出现。"}, {"text": "有闲", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是有空闲。"}], "explanations": {"有限": "正确答案：有限（yǒu xiàn），指数量、范围、时间不多。", "有效": "xiào（第四声）与 xiàn（第四声）韵母不同（-iao 与 -ian），意思是有效果、起作用。", "涌现": "yǒng（第三声）与 yǒu（第三声）韵母不同（-ong 与 -ou），意思是大量地出现。", "有闲": "xián（第二声）与 xiàn（第四声）声调不同，意思是有空闲。"}, "sentence_index": null, "correct_answer": "有限"}, "level_3": {"options": [{"text": "充足", "is_correct": false, "explanation": "语义：“充足”说时间够用，与后面“不能陪你去”的原因矛盾。"}, {"text": "充裕", "is_correct": false, "explanation": "语义：“充裕”说时间宽余，与“不能陪你去了”矛盾。"}, {"text": "丰富", "is_correct": false, "explanation": "搭配：“丰富”多用于知识、经验，一般不说“时间丰富”。"}, {"text": "有限", "is_correct": true, "explanation": "正确：“有限”说时间不多，所以不能陪你去。"}], "explanations": {"充足": "语义：“充足”说时间够用，与后面“不能陪你去”的原因矛盾。", "充裕": "语义：“充裕”说时间宽余，与“不能陪你去了”矛盾。", "丰富": "搭配：“丰富”多用于知识、经验，一般不说“时间丰富”。", "有限": "正确：“有限”说时间不多，所以不能陪你去。"}, "sentence_index": 0, "correct_answer": "有限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很有限，篮球打得很好。", "explanation": "这里应该用〈高〉。“有限”说数量、范围、时间或能力的限度，不用来形容身高。"}, {"text": "听到这个好消息，他的心情很有限。", "explanation": "这里应该用〈激动〉。“有限”指数量、范围或限度不多，不用来形容心情。"}, {"text": "今天的天气很有限，我们去公园吧。", "explanation": "这里应该用〈好〉或〈暖和〉。“有限”不用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宽泛", "is_correct": false, "explanation": "搭配：“宽泛”说范围广，不用来修饰“名额”这种数量。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌好看，“名额”不能是漂亮的。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说岁数小，与“名额”的数量概念无关。"}, {"text": "有限", "is_correct": true, "explanation": "正确：“有限”说名额不多，符合“这次比赛”的语境。"}], "explanations": {"宽泛": "搭配：“宽泛”说范围广，不用来修饰“名额”这种数量。", "漂亮": "语义：“漂亮”形容外貌好看，“名额”不能是漂亮的。", "年轻": "语义：“年轻”说岁数小，与“名额”的数量概念无关。", "有限": "正确：“有限”说名额不多，符合“这次比赛”的语境。"}, "sentence_index": 6, "correct_answer": "有限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的温度很有限，我们可以喝了。", "explanation": "这里应该用〈合适〉。“有限”说数量、范围或限度不多，不用来形容温度。"}, {"text": "这个政策有限了我的发展。", "explanation": "这里应该用动词〈限制〉：这个政策限制了我的发展。“有限”是形容词，不能带宾语。"}, {"text": "这位老师很有限，很多学生都认识她。", "explanation": "这里应该用〈有名〉。“有限”说数量、范围或限度不多，不用来形容人出名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅的座位不有限，周末最好提前订位。", "corrected_sentence": "这家餐厅的座位很有限，周末最好提前订位。", "error_description": "“有限”本身表示不多，不能再用“不”否定；应说“很有限”，用“很”修饰程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台旧手机的电量很太有限，出门前记得充电。", "corrected_sentence": "这台旧手机的电量很有限，出门前记得充电。", "error_description": "程度副词重复使用：“很”和“太”都修饰“有限”，只能用一个。应说“很有限”，不能说“很太有限”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "现象：事物表现在外的样子，与「本质」构成反义关系。"}, {"text": "方法", "is_correct": false, "explanation": "方法指做事的途径，与「本质」没有对立关系。"}, {"text": "速度", "is_correct": false, "explanation": "速度指运动的快慢，与「本质」没有对立关系。"}, {"text": "季节", "is_correct": false, "explanation": "季节指一年中的时段，与「本质」没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "现象：事物表现在外的样子，与「本质」构成反义关系。", "方法": "方法指做事的途径，与「本质」没有对立关系。", "速度": "速度指运动的快慢，与「本质」没有对立关系。", "季节": "季节指一年中的时段，与「本质」没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "现象：事物表现在外的样子，与「本质」构成反义关系。"}, {"text": "体积", "is_correct": false, "explanation": "体积指物体所占空间的大小，与「本质」没有对立关系。"}, {"text": "工具", "is_correct": false, "explanation": "工具指用来做事的器具，与「本质」没有对立关系。"}, {"text": "声音", "is_correct": false, "explanation": "声音指听觉所感受到的振动，与「本质」没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "现象：事物表现在外的样子，与「本质」构成反义关系。", "体积": "体积指物体所占空间的大小，与「本质」没有对立关系。", "工具": "工具指用来做事的器具，与「本质」没有对立关系。", "声音": "声音指听觉所感受到的振动，与「本质」没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本质就是一样东西最最重要的特点。", "primary_collocate": null, "pronunciation": "běn zhì", "ipa": "pən˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这两件事的本质是一样的。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想看清问题的本质。", "target_word": "本质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们看到事情的本质，不要只看表面。", "target_word": "本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不是幸福的本质。", "target_word": "本质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书说的是爱情的本质。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看起来很凶，可他的本质很善良。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习的本质是自己多想多练。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "变了名字，东西的本质没有变。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种动物和那种动物，本质不同。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的广告不会骗人，要说出产品的本质。", "target_word": "本质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "本质上", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物最根本、最重要的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9733c-8de7-4445-b4c8-56f8fe774a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本质", "is_correct": true, "explanation": "běn zhì（第四声）：事物最根本、最重要的特点，即听到的目标词。"}, {"text": "本市", "is_correct": false, "explanation": "běn shì（第四声）与 běn zhì 的声母不同（sh 与 zh），意思是本市（这座城市）。"}, {"text": "本职", "is_correct": false, "explanation": "běn zhí（第二声）与 běn zhì（第四声）声调不同，意思是本职（本职工作）。"}, {"text": "本事", "is_correct": false, "explanation": "běn shi（轻声）与 běn zhì 声母不同（sh 与 zh），声调也不同，意思是本事（能力）。"}], "explanations": {"本质": "běn zhì（第四声）：事物最根本、最重要的特点，即听到的目标词。", "本市": "běn shì（第四声）与 běn zhì 的声母不同（sh 与 zh），意思是本市（这座城市）。", "本职": "běn zhí（第二声）与 běn zhì（第四声）声调不同，意思是本职（本职工作）。", "本事": "běn shi（轻声）与 běn zhì 声母不同（sh 与 zh），声调也不同，意思是本事（能力）。"}, "sentence_index": null, "correct_answer": "本质"}, "level_3": {"options": [{"text": "容貌", "is_correct": false, "explanation": "体貌：容貌只指人的外貌，不能用来说两件事之间的关系。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：事件没有颜色，「颜色」只能用来说事物的色彩，这里说不通。"}, {"text": "本质", "is_correct": true, "explanation": "本质：事物最根本的特点，与「这两件事……是一样的」搭配自然。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重只指人或动物的重量，「这两件事的体重」说不通。"}], "explanations": {"容貌": "体貌：容貌只指人的外貌，不能用来说两件事之间的关系。", "颜色": "语义：事件没有颜色，「颜色」只能用来说事物的色彩，这里说不通。", "本质": "本质：事物最根本的特点，与「这两件事……是一样的」搭配自然。", "体重": "语义：体重只指人或动物的重量，「这两件事的体重」说不通。"}, "sentence_index": 0, "correct_answer": "本质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠这笔本质开了一家店。", "explanation": "这里应该用〈本钱〉。本质指事物根本的特点，不指做生意用的资金；做生意的资金要用〈本钱〉。"}, {"text": "这件衣服的本质很便宜。", "explanation": "这里应该用〈价格〉。本质不指价钱；说衣服价钱便宜要用〈价格〉。"}, {"text": "这面墙的本质很白。", "explanation": "这里应该用〈颜色〉。本质是抽象的根本特点，不指物体的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "语义：学习没有重量，「重量」只用来说物体，这里说不通。"}, {"text": "本质", "is_correct": true, "explanation": "本质：学习最根本的特点，与「自己多想多练」的内容相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：学习不是有岁数的事物，「学习的年龄」说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只指人的体形，不能用来说学习。"}], "explanations": {"重量": "语义：学习没有重量，「重量」只用来说物体，这里说不通。", "本质": "本质：学习最根本的特点，与「自己多想多练」的内容相合。", "年龄": "语义：学习不是有岁数的事物，「学习的年龄」说不通。", "身材": "体貌：身材只指人的体形，不能用来说学习。"}, "sentence_index": 6, "correct_answer": "本质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的本质很烫。", "explanation": "这里应该用〈温度〉。本质不指冷热这类可感受的程度；说水的冷热要用〈温度〉。"}, {"text": "这块蛋糕的本质很甜。", "explanation": "这里应该用〈味道〉。本质指根本特点，不指口感；说蛋糕甜要用〈味道〉。"}, {"text": "他的本质很大，什么都会修。", "explanation": "这里应该用〈本领〉。本质指事物根本的特点，不指人的能力；说人会做事的能力要用〈本领〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件事在本质是一样的。", "corrected_sentence": "这两件事在本质上是一样的。", "error_description": "「在……本质上」是固定格式，应为「在本质上」。学习者常漏掉「上」，写成「在本质」，这是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要看到问题的本质上，不要只看表面。", "corrected_sentence": "我们要看到问题的本质，不要只看表面。", "error_description": "「本质上」是副词性用法，不能作「看到」的宾语。作宾语时要用名词「本质」，应为「看到问题的本质」，去掉「上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "耳朵听声音的能力。", "primary_collocate": null, "pronunciation": "tīng jué", "ipa": "tʰiŋ˥ tɕyɛ˧˥", "syllable_count": 2, "sentences": [{"text": "猫的听觉很好，远处的声音也听得到。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的听觉不太好，说话要大声一点。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听觉有问题的人可以戴助听器。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗的听觉比人灵。", "target_word": "听觉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生用仪器测试孩子的听觉。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "耳朵受伤以后，他的听觉变差了。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的听觉会慢慢变弱。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太吵的地方对听觉不好。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的听觉很灵，隔着墙也听得到我说话。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护听觉，请不要把音量开得太大。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聽覺", "label": "繁体"}], "register": "通用", "sense_fingerprint": "耳朵听声音的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db84973e-d904-419a-b58d-917694db0a8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“很好”评价能力，句中讲的是猫的听力，与“颜色”不合。"}, {"text": "听觉", "is_correct": true, "explanation": "正确：“听觉”指耳朵听声音的能力，与后面“远处的声音也听得到”一致。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”是写下的笔画痕迹，猫不具备字迹，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”一般说“正常”或“超标”，不说“很好”。"}], "explanations": {"颜色": "语义：“颜色”不能用“很好”评价能力，句中讲的是猫的听力，与“颜色”不合。", "听觉": "正确：“听觉”指耳朵听声音的能力，与后面“远处的声音也听得到”一致。", "字迹": "语义：“字迹”是写下的笔画痕迹，猫不具备字迹，与句意不符。", "体重": "搭配：“体重”一般说“正常”或“超标”，不说“很好”。"}, "sentence_index": 0, "correct_answer": "听觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次露营的听觉让我很满足。", "explanation": "这里应该用〈体验〉。“体验”指亲身经历后获得的感受，可以说“体验让我很满足”；“听觉”是听声音的能力，不能指露营的经历。"}, {"text": "我对这家餐厅的听觉很满意。", "explanation": "这里应该用〈感觉〉。对餐厅的印象要说“感觉”，“听觉”只指听声音的能力。"}, {"text": "这部电影给我留下了深刻的听觉。", "explanation": "这里应该用〈感受〉。对作品的体会要说“感受”，“听觉”不能指这种体会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高会增长或降低，不会“变弱”，与句中的变化趋势不符。"}, {"text": "听觉", "is_correct": true, "explanation": "正确：“听觉”会随年龄减弱，与“慢慢变弱”的语义相合。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是固定的生理分类，不会“变弱”，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般说“增长”，不说“变弱”，与这一搭配不符。"}], "explanations": {"身高": "语义：身高会增长或降低，不会“变弱”，与句中的变化趋势不符。", "听觉": "正确：“听觉”会随年龄减弱，与“慢慢变弱”的语义相合。", "血型": "语义：血型是固定的生理分类，不会“变弱”，句意不通。", "年龄": "搭配：“年龄”一般说“增长”，不说“变弱”，与这一搭配不符。"}, "sentence_index": 6, "correct_answer": "听觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的听觉很漂亮，我很喜欢。", "explanation": "这里应该用〈款式〉。听觉指听声音的能力，不能用来形容衣服的样式；说衣服的样式要用「款式」。"}, {"text": "这碗汤的听觉很咸，我喝不下去。", "explanation": "这里应该用〈味道〉。听觉指听声音的能力，不能用来说汤的咸淡；说咸淡要用「味道」。"}, {"text": "这座山的听觉很高，我们爬了一整天。", "explanation": "这里应该用〈高度〉。听觉指听声音的能力，不能用来说山的高矮；说高矮要用「高度」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一张很灵敏的听觉。", "corrected_sentence": "他有很灵敏的听觉。", "error_description": "错误：“听觉”前用了量词“张”。“张”用于纸、桌子等平面的东西，“听觉”是能力，不用“张”计量，应去掉“一张”，说“他有很灵敏的听觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外婆的听觉最近变大了。", "corrected_sentence": "外婆的听觉最近变弱了。", "error_description": "错误：“变大”不能用来描述听觉的强弱；听觉减弱应说“变弱”。正确形式是“外婆的听觉最近变弱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
