INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西走过或动过后留下的印子。", "primary_collocate": null, "pronunciation": "guǐ jì", "ipa": "/kweɪ˨˩ tɕi˥˩/", "syllable_count": 2, "sentences": [{"text": "飞机在天空留下了一条白色的轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图画出了月亮的运动轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球飞出去的轨迹是一条弧线。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了星星的轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地上留下了一道长长的轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机地图记下了他今天走过的轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏能看到你的移动轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流星划过夜空，留下了一道明亮的轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看地图上的轨迹，我知道他去过哪里。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在沙滩上跑了一圈，留下了弯弯曲曲的轨迹。", "target_word": "轨迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "軌跡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，物体运动经过后留下的路线或痕迹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：“声音”看不见，不能在天空留下一条白色的痕迹。"}, {"text": "烟囱", "is_correct": false, "explanation": "搭配：“烟囱”是固定的建筑，“留下一条烟囱”搭配不当。"}, {"text": "轨迹", "is_correct": true, "explanation": "正确：“轨迹”指飞机飞过后留下的路线痕迹，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是嗅觉的对象，不能在天空留下白色的痕迹。"}], "explanations": {"声音": "语义：“声音”看不见，不能在天空留下一条白色的痕迹。", "烟囱": "搭配：“烟囱”是固定的建筑，“留下一条烟囱”搭配不当。", "轨迹": "正确：“轨迹”指飞机飞过后留下的路线痕迹，符合句意。", "味道": "语义：“味道”是嗅觉的对象，不能在天空留下白色的痕迹。"}, "sentence_index": 0, "correct_answer": "轨迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老房子在墙上留下了一道轨迹。", "explanation": "这里应该用〈裂缝〉。轨迹指运动物体经过的路线，墙上的开裂要用裂缝；房子不会运动，不会留下轨迹。"}, {"text": "妈妈给我买了一条轨迹。", "explanation": "这里应该用〈围巾〉。轨迹指运动后留下的痕迹，不能购买；买的应是围巾。"}, {"text": "这块玻璃是用一条轨迹做成的。", "explanation": "这里应该用〈材料〉。轨迹指运动后留下的痕迹，不是制作玻璃的东西，应说材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“移动颜色”说不通，颜色不是移动留下的路线。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“移动”后接“香味”搭配不当，香味不能被移动。"}, {"text": "轨迹", "is_correct": true, "explanation": "正确：“轨迹”指移动留下的路线，游戏能看见，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听觉的对象，“看到”的对象不能是声音。"}], "explanations": {"颜色": "搭配：“移动颜色”说不通，颜色不是移动留下的路线。", "香味": "搭配：“移动”后接“香味”搭配不当，香味不能被移动。", "轨迹": "正确：“轨迹”指移动留下的路线，游戏能看见，符合句意。", "声音": "语义：“声音”是听觉的对象，“看到”的对象不能是声音。"}, "sentence_index": 6, "correct_answer": "轨迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在书页上做了一个轨迹。", "explanation": "这里应该用〈标记〉。轨迹指运动经过的路线，书页上的记号要用标记。"}, {"text": "我吃了一条轨迹。", "explanation": "这里应该用〈面条〉。轨迹指运动后留下的痕迹，不能吃；能吃的一条应是面条。"}, {"text": "我们在厨房炒了一盘轨迹。", "explanation": "这里应该用〈菜〉。轨迹指运动后留下的痕迹，不能炒；能炒的是菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火箭飞上天空，留下了一只长长的轨迹。", "corrected_sentence": "火箭飞上天空，留下了一道长长的轨迹。", "error_description": "量词错误：“只”多用于动物等，不能修饰“轨迹”，应改为“道”或“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卫星在天空留下了三条轨迹们。", "corrected_sentence": "卫星在天空留下了三条轨迹。", "error_description": "词缀错误：“们”只用于指人的名词，“轨迹”是无生命的事物，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
