INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22294, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人一起做事情，你帮我，我帮你。", "primary_collocate": null, "pronunciation": "hù dòng", "ipa": "xu˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师和学生在课上互动。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在一起互动，玩得很开心。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同桌互动得很好。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和邻居常常互动，互相帮忙。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥一起修自行车，互相帮忙，互动很多。", "target_word": "互动", "complexity_tier": "T3", "furigana": "hùdòng", "sentence_source": "generated"}, {"text": "课堂上要多互动，不要只听老师说。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同事互动很多，工作很顺利。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家人常常互动，一起做饭。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喜欢和孩子互动。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在小组里互动，一起做作业。", "target_word": "互动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "互动了", "label": "体标"}, {"form": "互动过", "label": "体标"}, {"form": "互动着", "label": "体标"}], "register": "中性", "sense_fingerprint": "双方互相配合、互相影响地做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互动", "is_correct": true, "explanation": "正确。互动指双方互相配合、互相影响地做事，这里指课上师生互相配合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是在水中运动，与课堂上双方互相配合无关。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：旅行要到外地去，不能在课堂上进行。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」是随意走动，与课上师生互相配合的意思不符。"}], "explanations": {"互动": "正确。互动指双方互相配合、互相影响地做事，这里指课上师生互相配合。", "游泳": "语义：游泳是在水中运动，与课堂上双方互相配合无关。", "旅行": "语义：旅行要到外地去，不能在课堂上进行。", "散步": "语义：「散步」是随意走动，与课上师生互相配合的意思不符。"}, "sentence_index": 0, "correct_answer": "互动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈一个人在厨房里互动了一下午，做了很多菜。", "explanation": "这里应该用〈忙〉。互动要双方一起做事，一个人在厨房做菜要说忙了一下午。"}, {"text": "小猫总是独自互动，没有人陪它玩。", "explanation": "这里应该用〈玩耍〉。互动要双方或多方一起做事，只有一个主体时不能说互动。"}, {"text": "老师在台上一个人认真互动，台下没有学生。", "explanation": "这里应该用〈讲课〉。互动需要双方共同参与，老师一个人讲课时不能说互动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互动", "is_correct": true, "explanation": "正确。这里说我和同事之间互相配合、互相影响很多。"}, {"text": "生气", "is_correct": false, "explanation": "语义：「生气」表示不满，与「工作很顺利」的语气相矛盾。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：「哭泣」与「工作很顺利」相矛盾。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：「丢失」表示失去，与「工作很顺利」的语境相矛盾。"}], "explanations": {"互动": "正确。这里说我和同事之间互相配合、互相影响很多。", "生气": "语义：「生气」表示不满，与「工作很顺利」的语气相矛盾。", "哭泣": "语义：「哭泣」与「工作很顺利」相矛盾。", "丢失": "语义：「丢失」表示失去，与「工作很顺利」的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "互动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一个人互动完成了作业。", "explanation": "这里应该用〈独立〉。互动需要双方互相影响地做事，一个人完成作业要说独立完成。"}, {"text": "他一个人互动得很好，每天独自吃饭。", "explanation": "这里应该用〈生活〉。互动需要双方一起做事，一个人过日子要说生活得很好。"}, {"text": "他一个人在地铁上认真互动，什么也不说。", "explanation": "这里应该用〈思考〉。互动要双方参与，一个人安静地思考时不能说互动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位医生在手术中互动的很好。", "corrected_sentence": "两位医生在手术中互动得很好。", "error_description": "错误在补语：动词「互动」后带程度补语，要用「得」连接，不能用「的」。正确说法是「互动得很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位记者在现场互互动了很久。", "corrected_sentence": "两位记者在现场互动了很久。", "error_description": "错误在词形：「互动」是一个词，不能重叠成「互互动」。正确说法是「互动了很久」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
