INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "镜子里的样子，或者和镜子里的样子一样。", "primary_collocate": null, "pronunciation": "jìng xiàng", "ipa": "tɕiŋ˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我走近镜子，镜像也朝我走来。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜像里的我，和本人一模一样。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左手在镜像里变成了右手。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子擦得很干净，镜像非常清楚。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我笑了，镜像里的我也在笑。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个图形互为镜像。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机自拍时，看到的镜像是反的。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你画出这个字的镜像。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面大镜子能清楚地照出人的镜像。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着镜像，慢慢举起了右手。", "target_word": "镜像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鏡像", "label": "繁体"}], "register": "中性", "sense_fingerprint": "镜子或水面里映出的左右相反的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己移动，不能朝我走来，与镜子的语境不符。"}, {"text": "镜像", "is_correct": true, "explanation": "正确答案。镜子中映出的像随人移动，符合“朝我走来”的语境。"}, {"text": "枕头", "is_correct": false, "explanation": "语义：枕头不会自己移动，不能朝我走来。"}, {"text": "大厅", "is_correct": false, "explanation": "搭配：“走来”的主语应是能移动的人或物，“大厅”是场所，不与此动作搭配。"}], "explanations": {"石头": "语义：石头不会自己移动，不能朝我走来，与镜子的语境不符。", "镜像": "正确答案。镜子中映出的像随人移动，符合“朝我走来”的语境。", "枕头": "语义：枕头不会自己移动，不能朝我走来。", "大厅": "搭配：“走来”的主语应是能移动的人或物，“大厅”是场所，不与此动作搭配。"}, "sentence_index": 0, "correct_answer": "镜像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在商店买了一个镜像。", "explanation": "这里应该用〈镜子〉。镜像是映出的样子，不能买；买的是镜子。"}, {"text": "我把镜像挂在墙上。", "explanation": "这里应该用〈照片〉。镜像是镜子或水面映出的样子，不是可以挂起来的实物；挂在墙上的是照片。"}, {"text": "他把镜像拿去废品站卖了。", "explanation": "这里应该用〈镜子〉。镜像是映出的样子，不是可以拿去卖的实物；卖的是镜子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道看不到，不能用“看到的……是反的”来描述。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“看到”的对象应是可见之物，“温度”不可见，不与“看到”搭配。"}, {"text": "镜像", "is_correct": true, "explanation": "正确答案。自拍时看到的镜中像左右相反，是反的，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间看不到，不能用“看到的……是反的”来描述。"}], "explanations": {"味道": "语义：味道看不到，不能用“看到的……是反的”来描述。", "温度": "搭配：“看到”的对象应是可见之物，“温度”不可见，不与“看到”搭配。", "镜像": "正确答案。自拍时看到的镜中像左右相反，是反的，符合句意。", "时间": "语义：时间看不到，不能用“看到的……是反的”来描述。"}, "sentence_index": 6, "correct_answer": "镜像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打碎了镜像，碎片落了一地。", "explanation": "这里应该用〈镜子〉。能被打碎、产生碎片的是镜子本身，镜像只是映出的像。"}, {"text": "他把镜像放进了口袋里。", "explanation": "这里应该用〈镜子〉。镜像是映出的像，不能放进口袋。"}, {"text": "他伸手摸了摸镜像。", "explanation": "这里应该用〈镜面〉。镜像本身摸不到，伸手碰到的是镜面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在商店玻璃里看见了一面镜像。", "corrected_sentence": "我在商店玻璃里看见了一个镜像。", "error_description": "量词用错：“镜像”应用“个”计量，“面”用于镜子。“一面镜像”把镜像说成了镜子，不符合词义。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个图形的镜像们都很清楚。", "corrected_sentence": "这两个图形的镜像都很清楚。", "error_description": "词尾用错：“们”只加在指人的名词后面，“镜像”是事物，不能说“镜像们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
