INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22298, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "按说好的时间到，不晚也不早。", "primary_collocate": null, "pronunciation": "zhǔn shí", "ipa": "ʈʂuən˨˩ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "火车会准时到站。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请明天早上八点准时来学校。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天准时上班，从不迟到。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，考试九点准时开始。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一定要准时，我们不等人。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机没有准时起飞，因为下雨。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个很准时的人。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们准时到了饭店，朋友还没来。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车今天不太准时。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛准时开始，大家都坐好了。", "target_word": "准时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：按约定的时间，不早不晚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "准时", "is_correct": true, "explanation": "按约定的时间到站，符合句意。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列有序，不能用来说火车到站的时间。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指清晰、明白，不表示按时到达。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，不能用来形容火车到站。"}], "explanations": {"准时": "按约定的时间到站，符合句意。", "整齐": "搭配：“整齐”形容排列有序，不能用来说火车到站的时间。", "清楚": "语义：“清楚”指清晰、明白，不表示按时到达。", "热情": "语义：“热情”形容人的态度，不能用来形容火车到站。"}, "sentence_index": 0, "correct_answer": "准时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告的数据很准时。", "explanation": "这里应该用〈准确〉。准确指数据、答案正确无误；准时只用于按约定时间到达或开始，不能形容数据。"}, {"text": "我们的球队准时赢得了冠军。", "explanation": "这里应该用〈最终〉。准时要求事情按约定时间发生；比赛的结果不是按时间安排出现的，表示结局要说“最终赢得”。"}, {"text": "这家餐厅的菜准时好吃。", "explanation": "这里误把“准时”的“准”当成“准确、精准”的意思。准时只说时间上不早不晚，不能评价菜的味道；形容菜的味道要说〈地道〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准时", "is_correct": true, "explanation": "按约定的时间到，符合“她”守时的特点。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指清晰、明白，不用来形容人的性格。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容皮肤或物体的颜色，不用来说人的性格或习惯。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”指程度厉害，不用来形容人。"}], "explanations": {"准时": "按约定的时间到，符合“她”守时的特点。", "清楚": "语义：“清楚”指清晰、明白，不用来形容人的性格。", "雪白": "体貌：“雪白”形容皮肤或物体的颜色，不用来说人的性格或习惯。", "严重": "语义：“严重”指程度厉害，不用来形容人。"}, "sentence_index": 6, "correct_answer": "准时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师准时发现了这个问题。", "explanation": "这里应该用〈及时〉。及时指在需要的时候赶快做到；准时只说按约定时间，不能说“准时发现问题”。"}, {"text": "这件衣服的颜色很准时。", "explanation": "这里误把“准时”的“准”当成“准确、一致”的意思。准时只说按约定时间到达或开始，不能形容颜色；形容颜色鲜艳要说〈鲜艳〉。"}, {"text": "这个孩子准时学会了游泳。", "explanation": "这里应该用〈终于〉。准时要求动作按约定时间发生；学会游泳是能力达到，不是按约定完成的事件，表示最后达到要说“终于学会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天起很准时。", "corrected_sentence": "他每天起得很准时。", "error_description": "错误：补语标记“得”漏掉了。正确：“很准时”作补语，补充说明动词“起”的情况，应在“起”后加“得”，说“起得很准时”；不能说“起很准时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议准时结束着。", "corrected_sentence": "会议准时结束了。", "error_description": "错误：动态助词“着”用错了，“着”表示动作持续。正确：“准时结束”是一次性完成的动作，应用“了”表示完成，说“会议准时结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
