INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲眼看到或亲身经历某件事，并能证明它是真的。", "primary_collocate": null, "pronunciation": "jiàn zhèng", "ipa": "t͡ɕjɛn˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们见证了这座城市的变化。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他亲眼见证了那次比赛。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷见证了国家的发展。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵老树见证了学校的历史。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人来到现场，见证这个重要时刻。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我见证过他们从认识到结婚。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的婚礼上，我们一起见证了他们的幸福。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想亲眼见证孩子长大。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河见证着小镇的变化。", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能见证我说的是真的？", "target_word": "见证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "見證", "label": "繁体"}, {"form": "见证了", "label": "体标"}, {"form": "见证过", "label": "体标"}, {"form": "见证着", "label": "体标"}, {"form": "见证人", "label": "复合"}], "register": "中性", "sense_fingerprint": "亲眼看到或亲身经历某件事并能证明它是真的；动词义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：“参观”说去看地方或展览，不能说“参观变化”。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”用于文章、计划等，不能说“修改了城市的变化”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理环境，与“城市的变化”无关。"}, {"text": "见证", "is_correct": true, "explanation": "正确：“见证”指亲眼看到城市的变化，并能证明它。"}], "explanations": {"参观": "搭配：“参观”说去看地方或展览，不能说“参观变化”。", "修改": "搭配：“修改”用于文章、计划等，不能说“修改了城市的变化”。", "打扫": "语义：“打扫”指清理环境，与“城市的变化”无关。", "见证": "正确：“见证”指亲眼看到城市的变化，并能证明它。"}, "sentence_index": 0, "correct_answer": "见证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生见证了我的身体。", "explanation": "这里应该用〈检查〉。“见证”指亲眼看到或经历某事并能证明它，不用于医生对身体的检查。"}, {"text": "我见证了这道菜的味道。", "explanation": "这里应该用〈尝〉。“见证”说亲眼看见或亲身经历重要的事，味道不是可以“见证”的事件。"}, {"text": "他见证了这块石头的重量。", "explanation": "这里应该用〈称〉。“见证”指亲眼看到或亲身经历重要的事件并能证明，不用于测量重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、东西，不能说“修理了他们的幸福”。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：“打扰”是干扰别人，与婚礼上祝福他们的场合不符。"}, {"text": "签署", "is_correct": false, "explanation": "搭配：“签署”用于文件、协议，不能说“签署幸福”。"}, {"text": "见证", "is_correct": true, "explanation": "正确：“见证”指亲眼看到他们的幸福，并能证明它。"}], "explanations": {"修理": "搭配：“修理”用于机器、东西，不能说“修理了他们的幸福”。", "打扰": "语义：“打扰”是干扰别人，与婚礼上祝福他们的场合不符。", "签署": "搭配：“签署”用于文件、协议，不能说“签署幸福”。", "见证": "正确：“见证”指亲眼看到他们的幸福，并能证明它。"}, "sentence_index": 6, "correct_answer": "见证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长见证了我的作业。", "explanation": "这里应该用〈检查〉。“见证”指亲眼看到或亲身经历重要的事件并能证明，不用于作业。"}, {"text": "老板见证了我的午饭。", "explanation": "这里应该用〈吃〉。“见证”指亲眼看到或亲身经历重要的事件并能证明，不用于日常的吃饭。"}, {"text": "我见证了这张桌子的颜色。", "explanation": "这里应该用〈看〉或〈观察〉。“见证”用于重要的事件，不用于物体的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老房子见证了着我的成长。", "corrected_sentence": "这座老房子见证着我的成长。", "error_description": "“了”和“着”不能同时用在“见证”上。表示持续状态时只用“着”，应说“见证着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起很见证了他们的婚礼。", "corrected_sentence": "我们一起见证了他们的婚礼。", "error_description": "程度副词“很”不能直接修饰动词“见证”，应删去“很”，说“我们一起见证了他们的婚礼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
