INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两种生物生活在一起，互相帮助。", "primary_collocate": null, "pronunciation": "gòng shēng", "ipa": "kʊŋ˥˩ ʂəŋ˥", "syllable_count": 2, "sentences": [{"text": "小丑鱼和海葵共生，互相帮助。", "target_word": "共生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种小动物在树上共生。", "target_word": "共生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水牛和小鸟在草地上共生。", "target_word": "共生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "它们已经共生了很多年。", "target_word": "共生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鱼住在大鱼身上，两种动物共生。", "target_word": "共生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁和蚜虫共生，一个保护，一个给吃的。", "target_word": "共生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里的小虾和小鱼常常共生。", "target_word": "共生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为什么这两种动物能共生？", "target_word": "共生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "它们共生着，谁也离不开谁。", "target_word": "共生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看过，鳄鱼和小鸟可以共生。", "target_word": "共生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共生着", "label": "体标"}, {"form": "共生过", "label": "体标"}, {"form": "共生关系", "label": "复合"}], "register": "中性", "sense_fingerprint": "不同种类的生物生活在一起并互相有益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共生", "is_correct": true, "explanation": "“共生”指两种生物生活在一起、互相有利，符合“互相帮助”。"}, {"text": "竞争", "is_correct": false, "explanation": "语义：“竞争”指争夺利益，与“互相帮助”相矛盾。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”是离开，与“互相帮助”相矛盾。"}, {"text": "抢", "is_correct": false, "explanation": "配价：“抢”后面要带抢夺的对象，句中没有；而且意思与“互相帮助”相反。"}], "explanations": {"共生": "“共生”指两种生物生活在一起、互相有利，符合“互相帮助”。", "竞争": "语义：“竞争”指争夺利益，与“互相帮助”相矛盾。", "分开": "语义：“分开”是离开，与“互相帮助”相矛盾。", "抢": "配价：“抢”后面要带抢夺的对象，句中没有；而且意思与“互相帮助”相反。"}, "sentence_index": 0, "correct_answer": "共生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跳蚤共生在狗身上，靠吸狗血活着。", "explanation": "这里应该用〈寄生〉。共生指两种生物互利，跳蚤只吸血、对狗有害，是寄生。"}, {"text": "我每天早上六点共生。", "explanation": "这里应该用〈起床〉。共生指两种生物互利地生活在一起，不指早上起床，应说“六点起床”。"}, {"text": "孩子还小，需要父母共生。", "explanation": "这里应该用〈照顾〉。共生指两种生物互利地生存，不表示父母照料孩子，应说“父母照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共生", "is_correct": true, "explanation": "“共生”指互利地生活在一起，符合“常常”描述的动物关系。"}, {"text": "住院", "is_correct": false, "explanation": "语义：小虾和小鱼不会住院，这个词不符合动物的生活。"}, {"text": "上班", "is_correct": false, "explanation": "语义：小虾和小鱼不会上班，这个词与动物的生活不符。"}, {"text": "娶", "is_correct": false, "explanation": "配价：“娶”要带娶的对象，句中没有，搭配不成立。"}], "explanations": {"共生": "“共生”指互利地生活在一起，符合“常常”描述的动物关系。", "住院": "语义：小虾和小鱼不会住院，这个词不符合动物的生活。", "上班": "语义：小虾和小鱼不会上班，这个词与动物的生活不符。", "娶": "配价：“娶”要带娶的对象，句中没有，搭配不成立。"}, "sentence_index": 6, "correct_answer": "共生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩一起共生了一个下午，聊了很多。", "explanation": "这里应该用〈聊天〉。共生指两种动物住在一起、互相帮助，不用来说人一起聊天，应说“聊天”。"}, {"text": "同学们在学习上互相共生，成绩都很好。", "explanation": "这里应该用〈互助〉。共生指生物之间的互利生存，不用来说人与人之间的互相帮助。"}, {"text": "同学们在操场上共生，跑得很快。", "explanation": "这里应该用〈跑步〉。共生指生物互利地生活在一起，不指人在操场上运动，应说“跑步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种小鸟和犀牛很共生，帮犀牛清理身上的虫子。", "corrected_sentence": "这种小鸟和犀牛共生，帮犀牛清理身上的虫子。", "error_description": "错误形式：“很共生”；正确形式：“共生”。“很”只修饰形容词，共生是动词，不能用“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小丑鱼和海葵共生得好很。", "corrected_sentence": "小丑鱼和海葵共生得很好。", "error_description": "错误形式：“好很”；正确形式：“很好”。补语中的“很”要放在形容词前面，应说“共生得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
