INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22306, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "不用抱歉，小事而已。", "primary_collocate": null, "pronunciation": "méi guān xi", "ipa": "mei̯˧˥ kwan˥ ɕi", "syllable_count": 3, "sentences": [{"text": "“对不起，我来晚了。”“没关系。”", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不小心踩到我了？没关系，不疼。", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没关系，水杯坏了，我再买一个。", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说没关系，让我别难过。", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我把你的书弄脏了。”“没关系，我有两本。”", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没关系，下次你早一点来就好。", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你忘了带笔？没关系，我借你一支。", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“没关系，大家都会错。”", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没关系，我也刚到一会儿。", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“不好意思，让你等了很久。”“没关系。”", "target_word": "没关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有关系", "label": "完整形式"}], "register": "口语", "sense_fingerprint": "叹词：回应道歉，表示不要紧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没关系", "is_correct": true, "explanation": "没关系：用来回应道歉，表示不要紧，与前面的道歉相合。"}, {"text": "哈哈", "is_correct": false, "explanation": "语义：“哈哈”表示笑声，不能用来回应道歉。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是招呼或叫人的声音，不能作为对道歉的回应。"}, {"text": "谢谢", "is_correct": false, "explanation": "搭配：“谢谢”通常用于表示感谢，不用来回应道歉。"}], "explanations": {"没关系": "没关系：用来回应道歉，表示不要紧，与前面的道歉相合。", "哈哈": "语义：“哈哈”表示笑声，不能用来回应道歉。", "喂": "语义：“喂”是招呼或叫人的声音，不能作为对道歉的回应。", "谢谢": "搭配：“谢谢”通常用于表示感谢，不用来回应道歉。"}, "sentence_index": 0, "correct_answer": "没关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你身体没关系吧？", "explanation": "这里应该用〈没事〉。没关系用来回应别人的道歉，不用来询问身体状况。"}, {"text": "早上好，没关系。", "explanation": "这里应该用〈你好〉。没关系用来回应道歉，不用来打招呼。"}, {"text": "我考上大学了！没关系。", "explanation": "这里应该用〈恭喜〉。没关系用于宽慰或不计较，不用来回应好消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没关系", "is_correct": true, "explanation": "没关系：表示不必担心，与“我借你一支”的语境相符。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，与忘带笔的情境不相符。"}, {"text": "天哪", "is_correct": false, "explanation": "语义：“天哪”表示惊讶或焦急，不表示“不要紧”，不能用来宽慰对方。"}, {"text": "善哉", "is_correct": false, "explanation": "语域：“善哉”是文言感叹，与口语对话的语域不符。"}], "explanations": {"没关系": "没关系：表示不必担心，与“我借你一支”的语境相符。", "哇": "语义：“哇”表示惊叹，与忘带笔的情境不相符。", "天哪": "语义：“天哪”表示惊讶或焦急，不表示“不要紧”，不能用来宽慰对方。", "善哉": "语域：“善哉”是文言感叹，与口语对话的语域不符。"}, "sentence_index": 6, "correct_answer": "没关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在几点了？没关系。", "explanation": "这里应该直接回答时间，如〈十点〉。没关系是宽慰语，不能用来回答问题。"}, {"text": "天气真好，没关系。", "explanation": "这里应该说〈我们出去走走吧〉之类的话。没关系只用来回应道歉，表示不要紧，不能接在描述天气的话后面。"}, {"text": "这次考试我考得很好，没关系。", "explanation": "这里应该用〈不错〉。没关系是宽慰语，不能用来自夸成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很没关系，别担心。", "corrected_sentence": "没关系，别担心。", "error_description": "错误：「没关系」是固定的套语，不能用程度副词「很」修饰。正确是「没关系，别担心。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没关系着，我们慢慢来。", "corrected_sentence": "没关系，我们慢慢来。", "error_description": "错误：「没关系」是叹词，不能加动态助词「着」表示持续。正确是「没关系，我们慢慢来。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
