INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22310, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "到了说好的时间就做该做的事。", "primary_collocate": null, "pronunciation": "shǒu shí", "ipa": "ʂoʊ˨˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "小王很守时，每次开会都不迟到。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要守时，说好八点就八点到。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个守时的人，从来没让朋友等过。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说，学生一定要守时。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太守时，约会总是迟到。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守时是对别人的尊重。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本人很守时，火车几乎不晚点。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友特别守时，总是提前五分钟到。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是不守时，大家就不想等你。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想找好工作，就要学会守时。", "target_word": "守时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不守时", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "遵守约定的时间，不迟到不拖延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22310, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手势", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是用手做的动作。"}, {"text": "守时", "is_correct": true, "explanation": "正确答案：shǒu shí，意思是到了说好的时间就做该做的事。"}, {"text": "手持", "is_correct": false, "explanation": "chí 与 shí 声母不同（ch 与 sh），意思是用手拿着。"}, {"text": "收拾", "is_correct": false, "explanation": "第一音节 shōu（第一声）与 shǒu（第三声）声调不同，第二音节变轻声，意思是整理。"}], "explanations": {"手势": "shì（第四声）与 shí（第二声）声调不同，意思是用手做的动作。", "守时": "正确答案：shǒu shí，意思是到了说好的时间就做该做的事。", "手持": "chí 与 shí 声母不同（ch 与 sh），意思是用手拿着。", "收拾": "第一音节 shōu（第一声）与 shǒu（第三声）声调不同，第二音节变轻声，意思是整理。"}, "sentence_index": null, "correct_answer": "守时"}, "level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“每次开会都不迟到”的语境矛盾。"}, {"text": "守时", "is_correct": true, "explanation": "正确：“守时”指按约定时间行事，与“每次开会都不迟到”相符。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”描写声音或环境，与开会是否迟到无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材，与开会是否迟到无关。"}], "explanations": {"懒惰": "语义：“懒惰”与“每次开会都不迟到”的语境矛盾。", "守时": "正确：“守时”指按约定时间行事，与“每次开会都不迟到”相符。", "吵闹": "语义：“吵闹”描写声音或环境，与开会是否迟到无关。", "高大": "体貌：“高大”描写身材，与开会是否迟到无关。"}, "sentence_index": 0, "correct_answer": "守时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯很守时。", "explanation": "这里应该用〈明亮〉。“守时”形容人遵守时间，形容灯光要用“明亮”。"}, {"text": "医生守时抢救了病人。", "explanation": "这里应该用〈及时〉。“守时”指按约定的时间赴约或做事，抢救病人这样的紧急情况要用“及时”。"}, {"text": "这个钱包很守时。", "explanation": "这里应该用〈结实〉。“守时”形容人遵守时间，形容钱包坚固耐用要用“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散漫", "is_correct": false, "explanation": "语义：“散漫”与“火车几乎不晚点”的语境矛盾。"}, {"text": "守时", "is_correct": true, "explanation": "正确：“守时”指按时，与“火车几乎不晚点”的语境相符。"}, {"text": "健壮", "is_correct": false, "explanation": "体貌：“健壮”描写体格，与火车是否晚点无关。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：“粗鲁”描写言行，与火车准点无关，语境不通。"}], "explanations": {"散漫": "语义：“散漫”与“火车几乎不晚点”的语境矛盾。", "守时": "正确：“守时”指按时，与“火车几乎不晚点”的语境相符。", "健壮": "体貌：“健壮”描写体格，与火车是否晚点无关。", "粗鲁": "语义：“粗鲁”描写言行，与火车准点无关，语境不通。"}, "sentence_index": 6, "correct_answer": "守时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很守时。", "explanation": "这里应该用〈合身〉。“守时”形容人遵守时间，形容衣服大小合适要用“合身”。"}, {"text": "这块蛋糕很守时。", "explanation": "这里应该用〈松软〉。“守时”形容人遵守时间，形容蛋糕口感要用“松软”。"}, {"text": "她的眼睛很守时。", "explanation": "这里应该用〈明亮〉。“守时”形容人遵守时间，形容眼睛要用“明亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老张是个守时人，每次开会都很早到。", "corrected_sentence": "老张是个守时的人，每次开会都很早到。", "error_description": "错误：“守时人”。正确：“守时的人”。作定语的形容词短语后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位同学很守时很，总是提前到校。", "corrected_sentence": "这位同学很守时，总是提前到校。", "error_description": "错误：形容词「守时」后多出一个「很」。「很」须放在形容词前，句中已有「很守时」，后面多余的「很」应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22312, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喝", "is_correct": false, "explanation": "喝：与“连在一起”没有反义关系，“喝”指把液体咽下去。"}, {"text": "分开", "is_correct": true, "explanation": "分开：与“连在一起”意思相反，指不再接在一起。"}, {"text": "读", "is_correct": false, "explanation": "读：与“连在一起”没有反义关系，“读”指看着文字发出声音或理解文字。"}, {"text": "跳", "is_correct": false, "explanation": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。"}], "correct_answer": "分开", "explanations": {"喝": "喝：与“连在一起”没有反义关系，“喝”指把液体咽下去。", "分开": "分开：与“连在一起”意思相反，指不再接在一起。", "读": "读：与“连在一起”没有反义关系，“读”指看着文字发出声音或理解文字。", "跳": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22312, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "画", "is_correct": false, "explanation": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。"}, {"text": "跑", "is_correct": false, "explanation": "跑：与“连在一起”没有反义关系，“跑”指快速移动双腿前进。"}, {"text": "分开", "is_correct": true, "explanation": "分开：与“连在一起”意思相反，指不再接在一起。"}, {"text": "睡", "is_correct": false, "explanation": "睡：与“连在一起”没有反义关系，“睡”指闭眼休息。"}], "correct_answer": "分开", "explanations": {"画": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。", "跑": "跑：与“连在一起”没有反义关系，“跑”指快速移动双腿前进。", "分开": "分开：与“连在一起”意思相反，指不再接在一起。", "睡": "睡：与“连在一起”没有反义关系，“睡”指闭眼休息。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22312, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把两个东西接在一起，使它们不分开。", "primary_collocate": null, "pronunciation": "lián zài yì qǐ", "ipa": "ljɛn tsaɪ i tɕʰi", "syllable_count": 4, "sentences": [{"text": "请把这两张桌子连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两根绳子连在一起，系得很紧。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把两块布连在一起，做成一条裙子。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字写得太近，连在一起了。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把椅子连在一起。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把积木连在一起，搭成一座桥。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把两个小盒子连在一起，就是一个大盒子。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几根竹子连在一起，做成一根长竹竿。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两条项链连在一起了，分不开。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这两节火车连在一起，再开走。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连在一起了", "label": "完成体"}, {"form": "連在一起", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把两个东西接到一起，不分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲，不能说“唱桌子”。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：把两样东西接到一起，不分开，与“请把这两张桌子”的语境相符。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行书刊，桌子不能出版，句子说不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”用于文字，不能说“写桌子”。"}], "explanations": {"唱": "搭配：“唱”用于歌曲，不能说“唱桌子”。", "连在一起": "连在一起：把两样东西接到一起，不分开，与“请把这两张桌子”的语境相符。", "出版": "语义：“出版”指印刷发行书刊，桌子不能出版，句子说不通。", "写": "搭配：“写”用于文字，不能说“写桌子”。"}, "sentence_index": 0, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把两杯水连在一起喝了。", "explanation": "这里应该用〈混在一起〉。“连在一起”只用于能接合的有形实物，水不能被接在一起，应说“混在一起”。"}, {"text": "连在一起两张桌子，就能坐下十个人。", "explanation": "语序错误：“连在一起”后不能直接带宾语，应说“把两张桌子连在一起”。"}, {"text": "小明连在一起跑了两个小时。", "explanation": "这里应该用〈连续〉。“连在一起”指把东西接到一起，不表示时间上接连不断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：“烧”指点火燃烧，与“合成一个大盒子”的意思不符，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能说“吃盒子”。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：把两个东西接到一起，不分开，正好与“就是一个大盒子”相呼应。"}, {"text": "晒", "is_correct": false, "explanation": "搭配：“晒”指把东西放在阳光下干燥，不能说“晒两个小盒子”。"}], "explanations": {"烧": "语义：“烧”指点火燃烧，与“合成一个大盒子”的意思不符，句子说不通。", "吃": "搭配：“吃”用于食物，不能说“吃盒子”。", "连在一起": "连在一起：把两个东西接到一起，不分开，正好与“就是一个大盒子”相呼应。", "晒": "搭配：“晒”指把东西放在阳光下干燥，不能说“晒两个小盒子”。"}, "sentence_index": 6, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把汤和米饭连在一起吃了。", "explanation": "这里应该用〈拌在一起〉。“连在一起”指把有形的东西接合起来，汤和饭只能拌在一起。"}, {"text": "他把空气连在一起，装进了袋子里。", "explanation": "“连在一起”只用于有形的实物，空气无形，不能被接合在一起，这句话说不通。"}, {"text": "广场上很多游客连在一起。", "explanation": "这里应该用〈聚集〉。“连在一起”指物体接合，形容人群聚在一处要说“聚集”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把两根木条连在一起着，做成了一个架子。", "corrected_sentence": "他把两根木条连在一起，做成了一个架子。", "error_description": "“着”多用了。“把两根木条连在一起”是把两根木条接合的动作，后面接着说做成架子，不需要持续体“着”，应说“连在一起，做成了一个架子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个零件很连在一起，不会松开。", "corrected_sentence": "这两个零件紧紧连在一起，不会松开。", "error_description": "“很”是程度副词，不能修饰“连在一起”这类动词结构；这里应用“紧紧”修饰，表示连接牢固，正确为“紧紧连在一起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
