INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22314, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指很多人或所有人。", "primary_collocate": null, "pronunciation": "dà jiā", "ipa": "ta˥˩ tɕia˥", "syllable_count": 2, "sentences": [{"text": "大家好，欢迎来到我们的班。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天大家都很高兴。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家安静，现在开始上课。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事大家都知道。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起把桌子搬到外面去。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请大家吃饭。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在等你，快一点。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问大家有没有问题。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话让大家笑了。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这家饭馆的菜好吃。", "target_word": "大家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "代词：指在场或相关的所有人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22314, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大家", "is_correct": true, "explanation": "dàjiā 指很多人或所有人，是正确答案。"}, {"text": "打架", "is_correct": false, "explanation": "dǎjià（第三声、第四声）与 dàjiā（第四声、第一声）声调不同，意思是互相殴打。"}, {"text": "大江", "is_correct": false, "explanation": "jiāng 与 jiā 韵母不同（多一个 ng），意思是大河。"}, {"text": "大虾", "is_correct": false, "explanation": "xiā 与 jiā 声母不同，意思是大虾（一种海鲜）。"}], "explanations": {"大家": "dàjiā 指很多人或所有人，是正确答案。", "打架": "dǎjià（第三声、第四声）与 dàjiā（第四声、第一声）声调不同，意思是互相殴打。", "大江": "jiāng 与 jiā 韵母不同（多一个 ng），意思是大河。", "大虾": "xiā 与 jiā 声母不同，意思是大虾（一种海鲜）。"}, "sentence_index": null, "correct_answer": "大家"}, "level_3": {"options": [{"text": "大家", "is_correct": true, "explanation": "指在场的所有人，符合欢迎全班的句意。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人本人，不能用来向全班打招呼。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指第三人称，即不在场的人，不能用来招呼在场的人。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”是口语中指他人的说法，不用于正式的欢迎语。"}], "explanations": {"大家": "指在场的所有人，符合欢迎全班的句意。", "自己": "语义：“自己”指说话人本人，不能用来向全班打招呼。", "他": "语义：“他”指第三人称，即不在场的人，不能用来招呼在场的人。", "人家": "语域：“人家”是口语中指他人的说法，不用于正式的欢迎语。"}, "sentence_index": 0, "correct_answer": "大家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的妹妹大家很可爱。", "explanation": "这里误把“大家”当成指单个人的〈她〉。“大家”指许多人，不能指一个妹妹；形容妹妹可爱要说“她很可爱”。"}, {"text": "我买了大家的这本书。", "explanation": "这里误把“大家”当成单个所有者。“大家”指许多人，不能作一本具体书的主人；这本书是我的，应说〈我的〉。"}, {"text": "大家一个人去了上海。", "explanation": "这里误把“大家”当成〈一起〉的意思。“大家”指许多人，不能与“一个人”同时作主语；集体去要说“大家一起去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22314, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大家", "is_correct": true, "explanation": "dàjiā 指很多人或所有人，是正确答案。"}, {"text": "打假", "is_correct": false, "explanation": "dǎjiǎ 两个音节的声调都与 dàjiā 不同，意思是打击假冒伪劣商品。"}, {"text": "大街", "is_correct": false, "explanation": "jiē 与 jiā 韵母不同（a 与 e），意思是街道。"}, {"text": "那家", "is_correct": false, "explanation": "nà 与 dà 声母不同，意思是那一家（店）。"}], "explanations": {"大家": "dàjiā 指很多人或所有人，是正确答案。", "打假": "dǎjiǎ 两个音节的声调都与 dàjiā 不同，意思是打击假冒伪劣商品。", "大街": "jiē 与 jiā 韵母不同（a 与 e），意思是街道。", "那家": "nà 与 dà 声母不同，意思是那一家（店）。"}, "sentence_index": null, "correct_answer": "大家"}, "level_3": {"options": [{"text": "大家", "is_correct": true, "explanation": "指很多人，可以作“在等你”的主语。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指听话的人，而“等你”的对象也是听话的人，句意矛盾。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人本人，与“等你”的对象不合，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是无生命的书籍，不能作“在等你”的主语。"}], "explanations": {"大家": "指很多人，可以作“在等你”的主语。", "你们": "语义：“你们”指听话的人，而“等你”的对象也是听话的人，句意矛盾。", "自己": "语义：“自己”指说话人本人，与“等你”的对象不合，句意不通。", "课本": "语义：“课本”是无生命的书籍，不能作“在等你”的主语。"}, "sentence_index": 6, "correct_answer": "大家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果大家很甜。", "explanation": "这里误把“大家”当成指东西的〈都〉。“大家”只指人；形容苹果甜要说“这个苹果很甜”。"}, {"text": "这座大楼大家很高。", "explanation": "这里误把“大家”当成指建筑的〈全部〉。“大家”只指人，不能作大楼的主语；形容大楼高要说“很高”。"}, {"text": "我的小狗大家都很可爱。", "explanation": "这里误把“大家”当成指一只小狗的〈每只〉。“大家”指很多人，不能用来指一只小狗；形容小狗可爱要说〈它〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家很都喜欢这部电影。", "corrected_sentence": "大家都很喜欢这部电影。", "error_description": "错误：副词“很”放在了“都”前面，两个副词连用。正确：“都”紧跟“大家”，表示全体；“很”修饰后面的“喜欢”，应说“大家都很喜欢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚饭后一个大家都很开心。", "corrected_sentence": "晚饭后大家都很开心。", "error_description": "错误：“一个”这个数量词不能与代词“大家”组合。正确：“大家”指许多人，应直接说“大家都很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
