INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22316, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "你懂我的意思，我也懂你的意思。", "primary_collocate": null, "pronunciation": "hù xiāng lǐ jiě", "ipa": "xu⁵¹ ɕjɑŋ⁵⁵ li²¹⁴ tɕjɛ²¹⁴", "syllable_count": 4, "sentences": [{"text": "朋友之间要互相理解。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们互相理解，所以很少吵架。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻应该互相理解。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说同一种语言，大家更容易互相理解。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不常见面，但是互相理解。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们互相理解，一起完成了工作。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有互相理解，才会有好朋友。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望孩子们互相理解。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同屋互相理解了对方的习惯。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的人民需要互相理解。", "target_word": "互相理解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "互相理解了", "label": "体标"}, {"form": "互相理解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "双方都明白并体谅对方的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与“朋友之间”应有的友好关系相反，不能作为朋友之间要做的事。"}, {"text": "互相理解", "is_correct": true, "explanation": "正确答案。双方彼此明白、体谅，符合“朋友之间要……”的语境。"}, {"text": "打架", "is_correct": false, "explanation": "语义：朋友之间应当友好相处，“打架”与此相反，不能作为朋友之间要做的事。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”是不诚实的行为，与朋友之间应有的信任相悖。"}], "explanations": {"讨厌": "语义：“讨厌”表示不喜欢，与“朋友之间”应有的友好关系相反，不能作为朋友之间要做的事。", "互相理解": "正确答案。双方彼此明白、体谅，符合“朋友之间要……”的语境。", "打架": "语义：朋友之间应当友好相处，“打架”与此相反，不能作为朋友之间要做的事。", "欺骗": "语义：“欺骗”是不诚实的行为，与朋友之间应有的信任相悖。"}, "sentence_index": 0, "correct_answer": "互相理解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们互相理解了那张桌子。", "explanation": "这里应该用〈擦〉。“互相理解”只用于人与人之间彼此懂得对方的想法、心情，桌子这样的物品不能作对象；擦桌子才是这样说。"}, {"text": "我们三个人互相理解了这辆公交车。", "explanation": "这里应该用〈开〉。“互相理解”的对象是人的想法或心情，公交车是物体；开公交车才这样说。"}, {"text": "他们互相理解了这场比赛的时间。", "explanation": "这里应该用〈安排〉。“互相理解”的对象是人的想法、心情或处境，时间、安排这样的客观事物不能作对象；比赛的时间要说“安排”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”是看不起、不喜欢，与“才会有好朋友”的结果矛盾。"}, {"text": "增进", "is_correct": false, "explanation": "配价：“增进”后必须跟宾语（增进友谊、增进了解），这里空缺宾语，句子不完整。"}, {"text": "互相理解", "is_correct": true, "explanation": "正确答案。“只有双方彼此理解，才会有好朋友”，语义通顺。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：“疏远”指关系变得冷淡，与“好朋友”的结果相反。"}], "explanations": {"嫌弃": "语义：“嫌弃”是看不起、不喜欢，与“才会有好朋友”的结果矛盾。", "增进": "配价：“增进”后必须跟宾语（增进友谊、增进了解），这里空缺宾语，句子不完整。", "互相理解": "正确答案。“只有双方彼此理解，才会有好朋友”，语义通顺。", "疏远": "语义：“疏远”指关系变得冷淡，与“好朋友”的结果相反。"}, "sentence_index": 6, "correct_answer": "互相理解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个国家的人民互相理解了一座大山。", "explanation": "这里应该用〈翻越〉。“互相理解”的对象应是人的想法或心情，大山是物体，不能被“互相理解”；翻越大山才是这样说。"}, {"text": "这两个国家的人民互相理解了一把椅子。", "explanation": "这里应该用〈搬〉。椅子是物品，不能成为“互相理解”的对象；搬一把椅子才是这样说。"}, {"text": "这两个国家的人民互相理解了我的电脑。", "explanation": "这里应该用〈修理〉。电脑是物品，“互相理解”的对象只能是对方的想法、心情或处境；修理电脑才是这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们互相理解的很好。", "corrected_sentence": "我们互相理解得很好。", "error_description": "补语标记用错：应说“理解得很好”，用“得”引出程度补语；“的”用于定语，不能引出“很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们互相理解的很快。", "corrected_sentence": "他们互相理解得很快。", "error_description": "补语标记用错：表示程度的补语要用“得”引出，“的”会把“很快”变成定语，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "正好就是这个", "primary_collocate": null, "pronunciation": "zhèng shì", "ipa": "ʈʂɤŋ˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "现在正是春天，花都开了。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来得正是时候，饭刚做好。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这正是我想要的礼物。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正是我们找了很久的老师。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九月正是秋天，天气很舒服。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这正是问题的关键。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天正是她的生日，我送了她花。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人正是我们的新经理。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子十岁正是学游泳的好年纪。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事正是他最担心的。", "target_word": "正是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "强调恰好就是所说的人、事物或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是证明属实。"}, {"text": "正是", "is_correct": true, "explanation": "正确答案：zhèng shì，意思是恰好就是所说的人、事物或时间。"}, {"text": "正史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的历史记载。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}, {"text": "阵势", "is_correct": false, "explanation": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是阵势、气势。"}], "explanations": {"证实": "shí（第二声）与 shì（第四声）声调不同，意思是证明属实。", "正是": "正确答案：zhèng shì，意思是恰好就是所说的人、事物或时间。", "正史": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的历史记载。", "政治": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。", "阵势": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是阵势、气势。"}, "sentence_index": null, "correct_answer": "正是"}, "level_3": {"options": [{"text": "并不是", "is_correct": false, "explanation": "语义：“并不是”否定“春天”，与“花都开了”的描述相矛盾。"}, {"text": "正是", "is_correct": true, "explanation": "正确：“正是”强调恰好是春天，与“花都开了”相符。"}, {"text": "可不是", "is_correct": false, "explanation": "语义：“现在可不是春天”是强调否定，与“花都开了”的描述相矛盾。"}, {"text": "不一定是", "is_correct": false, "explanation": "语义：“不一定是”表示不确定，与“花都开了”的肯定描述不符。"}], "explanations": {"并不是": "语义：“并不是”否定“春天”，与“花都开了”的描述相矛盾。", "正是": "正确：“正是”强调恰好是春天，与“花都开了”相符。", "可不是": "语义：“现在可不是春天”是强调否定，与“花都开了”的描述相矛盾。", "不一定是": "语义：“不一定是”表示不确定，与“花都开了”的肯定描述不符。"}, "sentence_index": 0, "correct_answer": "正是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正是吃饭呢，你先别进来。", "explanation": "这里应该用〈正在〉。“正是”用于确认人或事的所指，不表示动作正在进行，要用“正在”。"}, {"text": "这件衣服正是很漂亮。", "explanation": "这里应该用〈非常〉。“正是”用于确认所指，不表示程度，形容程度要用“非常”。"}, {"text": "我正是吃饱了，你们吃吧。", "explanation": "这里应该用〈刚刚〉。“正是”用于确认所指，不表示刚发生的动作，要用“刚刚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一直是", "is_correct": false, "explanation": "语义：“一直是”表示持续，与“昨天”这一具体日子矛盾。"}, {"text": "正是", "is_correct": true, "explanation": "正确：“正是”强调恰好是某天是她的生日，与“我送了她花”相符。"}, {"text": "不会是", "is_correct": false, "explanation": "语义：“不会是”否定“她的生日”，与“我送了她花”的情境矛盾。"}, {"text": "绝不是", "is_correct": false, "explanation": "语义：“绝不是”完全否定，与“我送了她花”的语境矛盾。"}], "explanations": {"一直是": "语义：“一直是”表示持续，与“昨天”这一具体日子矛盾。", "正是": "正确：“正是”强调恰好是某天是她的生日，与“我送了她花”相符。", "不会是": "语义：“不会是”否定“她的生日”，与“我送了她花”的情境矛盾。", "绝不是": "语义：“绝不是”完全否定，与“我送了她花”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "正是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正是回家了，你别等他了。", "explanation": "这里应该用〈刚刚〉。“正是”用于确认所指，不表示刚发生的动作，要用“刚刚”。"}, {"text": "这本书正是很厚。", "explanation": "这里应该用〈非常〉。“正是”用于确认所指，不表示程度，形容程度要用“非常”。"}, {"text": "这个房间正是很大。", "explanation": "这里应该用〈十分〉。“正是”用于确认所指，不表示程度，形容程度要用“十分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是正是我们最需要的东西。", "corrected_sentence": "这正是我们最需要的东西。", "error_description": "错误：「正是」前多加了「是」。「正是」本身已表示恰好是，与「这」连用直接说「这正是」，不能再加「是」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个答案很正是我想要的。", "corrected_sentence": "这个答案正是我想要的。", "error_description": "错误：“很正是”。正确：“正是”。“正是”本身已表示强调，不能再加程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情就是人们做的一件事。", "primary_collocate": null, "pronunciation": "shì qing", "ipa": "ʂɻ̩⁵¹ tɕʰiŋ", "syllable_count": 2, "sentences": [{"text": "今天我有很多事情要做。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事情很重要。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情告诉了妈妈。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这件事情吗？", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情已经做完了。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在教室里说了一件事情。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你说一件有意思的事情。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天发生了一件奇怪的事情。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先做重要的事情，再玩手机。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是把事情做得很好。", "target_word": "事情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}], "register": "中性", "sense_fingerprint": "人们做的或发生的一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6750d34-8059-4248-b24c-0c46300c707b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事情", "is_correct": true, "explanation": "“很多事情要做”指很多需要做的事，与句意相符，通顺。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是需要去做的事，“很多河流要做”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“做”来处理，句意不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“做”与“房间”不搭，应说“打扫房间”。"}], "explanations": {"事情": "“很多事情要做”指很多需要做的事，与句意相符，通顺。", "河流": "语义：河流不是需要去做的事，“很多河流要做”说不通。", "天气": "语义：天气不能用“做”来处理，句意不通。", "房间": "搭配：“做”与“房间”不搭，应说“打扫房间”。"}, "sentence_index": 0, "correct_answer": "事情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个事情很好用，大家都想买。", "explanation": "这里应该用〈东西〉。事情指人做的事，不能说“好用”，说有用处的物件要用东西。"}, {"text": "我想和你说一本事情。", "explanation": "这里的量词用错了。“本”用于书、本子，事情要用“件”，应说“一件事情”。"}, {"text": "这个事情很好吃，我很喜欢。", "explanation": "这里应该用〈菜〉。“好吃”形容食物，事情不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事情", "is_correct": true, "explanation": "“说一件有意思的事情”指讲述一件有趣的事，与句意相符，通顺。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“说”的对象是话题或事情，不能说衣服，句意不通。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李不能作为“说”的内容，句意不通。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“说”一般接话题、事情，不接家具，搭配不当。"}], "explanations": {"事情": "“说一件有意思的事情”指讲述一件有趣的事，与句意相符，通顺。", "衣服": "语义：“说”的对象是话题或事情，不能说衣服，句意不通。", "行李": "语义：行李不能作为“说”的内容，句意不通。", "家具": "搭配：“说”一般接话题、事情，不接家具，搭配不当。"}, "sentence_index": 6, "correct_answer": "事情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事情的颜色很白，像雪一样。", "explanation": "这里应该用〈东西〉。“白”形容有颜色的东西，事情没有颜色，不能这样形容。"}, {"text": "我昨天做了一块事情。", "explanation": "这里的量词用错了。“块”用于成块的东西，事情应该用“件”。"}, {"text": "这道菜的事情很好，大家都爱吃。", "explanation": "这里应该用〈味道〉。菜的好坏要说味道，事情不能用来评价菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本事情我必须马上告诉你。", "corrected_sentence": "这件事情我必须马上告诉你。", "error_description": "错误形式：“这本事情”。正确形式：“这件事情”。“本”用于书、本子，“事情”应该用量词“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经事情做完了。", "corrected_sentence": "他已经把事情做完了。", "error_description": "错误形式：“他已经事情做完了”。“事情”是“做完”的宾语，不能直接放在动词前：可以用“把”提到动词前（“把事情做完”），也可以放在动词后（“做完事情了”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "就是让别人不要生气，意思是“请别不高兴”。", "primary_collocate": null, "pronunciation": "bié shēng qì", "ipa": "pjɛ ʂɤŋ tɕʰi", "syllable_count": 3, "sentences": [{"text": "老师笑着说：“别生气，慢慢来。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看我不高兴，就说：“别生气。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气，这只是个小问题。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐对生气的小明说：“别生气。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学说错了话，你别生气。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气，我们明天再谈。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对妈妈说：“别生气，我来做饭。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对朋友说：“别生气，是我的错。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人很不高兴，服务员说：“请别生气。”", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气啦，下次我一定准时。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "别生气了", "label": "加了"}, {"form": "別生氣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "请别人不要不高兴的安慰话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别生气", "is_correct": true, "explanation": "正确。「别生气，慢慢来」是劝慰语，与「老师笑着说」的语境相符，只有它能填入空格。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：「迟到」不能构成劝慰，「迟到，慢慢来」句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉，慢慢来」与老师笑着劝人的语境无关，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：「慢慢来」用于人的行为，天气不能被要求「慢慢来」，搭配不当。"}], "explanations": {"别生气": "正确。「别生气，慢慢来」是劝慰语，与「老师笑着说」的语境相符，只有它能填入空格。", "迟到": "语义：「迟到」不能构成劝慰，「迟到，慢慢来」句意不通。", "睡觉": "语义：「睡觉，慢慢来」与老师笑着劝人的语境无关，句意不通。", "下雨": "搭配：「慢慢来」用于人的行为，天气不能被要求「慢慢来」，搭配不当。"}, "sentence_index": 0, "correct_answer": "别生气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在图书馆里安静地看书，妈妈对我说：“别生气。”", "explanation": "「别生气」预设有人正在发怒，图书馆里大家都在安静看书，没有人生气，这里应该用「小声点」提醒别人。"}, {"text": "老人在公园里下棋，我走过去对他说：“别生气。”", "explanation": "「别生气」预设对方正在发怒，老人下棋时心情很好，这里不能这样劝，应该说「打扰了」。"}, {"text": "他没有生气，我却劝他：“别生气。”", "explanation": "「别生气」预设对方正在生气。对方没有生气时不能这样劝，应该用「没关系」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别生气", "is_correct": true, "explanation": "正确。「别生气，我来做饭」是家人之间的劝慰语，只有它能填入空格。"}, {"text": "出门", "is_correct": false, "explanation": "语义：「出门，我来做饭」前后不接，句意不通。"}, {"text": "赴约", "is_correct": false, "explanation": "语域：「赴约」是书面语，与家人间的口语对话不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「考试，我来做饭」与劝慰的语境无关，句意不通。"}], "explanations": {"别生气": "正确。「别生气，我来做饭」是家人之间的劝慰语，只有它能填入空格。", "出门": "语义：「出门，我来做饭」前后不接，句意不通。", "赴约": "语域：「赴约」是书面语，与家人间的口语对话不合。", "考试": "语义：「考试，我来做饭」与劝慰的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "别生气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在银行排队办事，一直很耐心，我对他说：“别生气。”", "explanation": "「别生气」预设对方正在发怒，他很有耐心，没有生气，这里不能这样劝，应该说「辛苦了」。"}, {"text": "他把饭做得很香，全家都夸他，我却说：“别生气。”", "explanation": "「别生气」预设对方正在生气；全家都在夸他，他正高兴，这里应该说「做得真好」。"}, {"text": "我请朋友看电影，他很开心，我说：“别生气。”", "explanation": "这里是开心的语境。「别生气」是劝人不要发怒，这里应该用「别客气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你别生气了了，我马上去买。", "corrected_sentence": "你别生气了，我马上去买。", "error_description": "错误形式「别生气了了」，「了」多写了一个。正确形式「别生气了」，「了」只用一次，紧跟在「生气」后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸，别生气过，我们明天再去。", "corrected_sentence": "爸爸，别生气了，我们明天再去。", "error_description": "错误形式「别生气过」，「过」表示经历过，劝阻的语境要用「了」表示事情的变化。正确形式「别生气了」，「了」应放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
