INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22326, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "常常可以见到，不稀奇。", "primary_collocate": null, "pronunciation": "cháng jiàn", "ipa": "ʈʂʰɑŋ˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种小鸟在我们这里很常见。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒是冬天最常见的病。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王是中国很常见的姓。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种错误在初学者中很常见。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在北方，雪是冬天常见的景色。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机是现在最常见的东西，人人都有。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很常见，不用担心。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们城市，马车已经不常见了。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很常见，路边到处都是。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的这个词不太常见，我没学过。", "target_word": "常见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不常见", "label": "否定"}, {"form": "常见病", "label": "复合"}], "register": "中性", "sense_fingerprint": "经常能见到的，不稀奇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55f2e96c-13a5-42cd-ab9f-f21f3b3466c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22326, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成见", "is_correct": false, "explanation": "成见 chéng jiàn 与 常见 cháng jiàn 第一个音节韵母不同（eng 与 ang），意思是固有的看法"}, {"text": "常见", "is_correct": true, "explanation": "正确。常见 cháng jiàn，意思是经常能见到，不稀奇"}, {"text": "长江", "is_correct": false, "explanation": "长江 cháng jiāng 与 常见 cháng jiàn 第二个音节韵母不同（ang 与 an）且声调不同（一声与四声），意思是中国最长的河"}, {"text": "长街", "is_correct": false, "explanation": "长街 cháng jiē 与 常见 cháng jiàn 第二个音节韵母和声调都不同（ie 与 ian，一声与四声），意思是长长的街道"}], "explanations": {"成见": "成见 chéng jiàn 与 常见 cháng jiàn 第一个音节韵母不同（eng 与 ang），意思是固有的看法", "常见": "正确。常见 cháng jiàn，意思是经常能见到，不稀奇", "长江": "长江 cháng jiāng 与 常见 cháng jiàn 第二个音节韵母不同（ang 与 an）且声调不同（一声与四声），意思是中国最长的河", "长街": "长街 cháng jiē 与 常见 cháng jiàn 第二个音节韵母和声调都不同（ie 与 ian，一声与四声），意思是长长的街道"}, "sentence_index": null, "correct_answer": "常见"}, "level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容人或物的个头，用来说小鸟在这里是否常见说不通"}, {"text": "常见", "is_correct": true, "explanation": "正确。常见指经常能见到、不稀奇，与“很”搭配，说明小鸟在这里很常见"}, {"text": "复杂", "is_correct": false, "explanation": "语义：「复杂」说事情或结构繁多，与小鸟在这里的情况无关"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：「宽敞」形容空间大，不能用来形容小鸟"}], "explanations": {"高大": "体貌：「高大」形容人或物的个头，用来说小鸟在这里是否常见说不通", "常见": "正确。常见指经常能见到、不稀奇，与“很”搭配，说明小鸟在这里很常见", "复杂": "语义：「复杂」说事情或结构繁多，与小鸟在这里的情况无关", "宽敞": "搭配：「宽敞」形容空间大，不能用来形容小鸟"}, "sentence_index": 0, "correct_answer": "常见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "检查结果显示他的体温很常见。", "explanation": "这里应该用〈正常〉。常见指经常能看到、不稀奇，不用来说体温是否合乎标准"}, {"text": "这次考试他的成绩很常见，全班第一。", "explanation": "这里应该用〈优秀〉。常见指不稀奇、到处都有，与“全班第一”的出色表现相矛盾，应说〈优秀〉"}, {"text": "这件礼物很常见，全世界只有一件。", "explanation": "这里应该用〈特别〉。常见指不稀奇、到处都有，与“全世界只有一件”的独一无二相矛盾，应说〈特别〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22326, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尝鲜", "is_correct": false, "explanation": "尝鲜 cháng xiān 与 常见 cháng jiàn 第二个音节声母（x 与 j）和声调不同，意思是吃新鲜的东西"}, {"text": "常见", "is_correct": true, "explanation": "正确。常见 cháng jiàn，意思是经常能见到，不稀奇"}, {"text": "厂家", "is_correct": false, "explanation": "厂家 chǎng jiā 与 常见 cháng jiàn 两个音节声调都不同，第二个音节韵母也不同，意思是工厂"}, {"text": "长线", "is_correct": false, "explanation": "长线 cháng xiàn 与 常见 cháng jiàn 第二个音节声母不同（x 与 j），意思是长期的，如长线投资"}], "explanations": {"尝鲜": "尝鲜 cháng xiān 与 常见 cháng jiàn 第二个音节声母（x 与 j）和声调不同，意思是吃新鲜的东西", "常见": "正确。常见 cháng jiàn，意思是经常能见到，不稀奇", "厂家": "厂家 chǎng jiā 与 常见 cháng jiàn 两个音节声调都不同，第二个音节韵母也不同，意思是工厂", "长线": "长线 cháng xiàn 与 常见 cháng jiàn 第二个音节声母不同（x 与 j），意思是长期的，如长线投资"}, "sentence_index": null, "correct_answer": "常见"}, "level_3": {"options": [{"text": "严重", "is_correct": false, "explanation": "语义：「严重」说问题很糟，与“不用担心”的语境相矛盾"}, {"text": "常见", "is_correct": true, "explanation": "正确。常见指经常能见到、不稀奇，说明这个问题很普遍，所以不用担心"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：「拥挤」多形容地方或人群，不用来形容问题"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：「辽阔」形容地域或空间广大，不用来形容问题"}], "explanations": {"严重": "语义：「严重」说问题很糟，与“不用担心”的语境相矛盾", "常见": "正确。常见指经常能见到、不稀奇，说明这个问题很普遍，所以不用担心", "拥挤": "搭配：「拥挤」多形容地方或人群，不用来形容问题", "辽阔": "搭配：「辽阔」形容地域或空间广大，不用来形容问题"}, "sentence_index": 6, "correct_answer": "常见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对这座城市很常见，连路都不认识。", "explanation": "这里应该用〈陌生〉。常见说事物不稀奇，不用来表示对某地熟悉与否；“连路都不认识”说明对这座城市应说〈陌生〉"}, {"text": "这种鸟在这里很常见，一年也碰不到一次。", "explanation": "这里应该用〈少见〉。常见指经常看到、不稀奇，与“一年也碰不到一次”的说法相矛盾，应说〈少见〉"}, {"text": "那个小镇很常见，坐车要三天才能到。", "explanation": "这里应该用〈遥远〉。常见指不稀奇，不用来说距离远近；“坐车要三天才能到”说明应说〈遥远〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在北京的冬天，这种鸟越来越常见着。", "corrected_sentence": "在北京的冬天，这种鸟越来越常见了。", "error_description": "“常见着”错误：形容词“常见”表示变化时要用“了”，不能用“着”。应为“越来越常见了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一种很常见鸟，大家都认识它。", "corrected_sentence": "这是一种很常见的鸟，大家都认识它。", "error_description": "“很常见鸟”错误：形容词“常见”修饰名词时要加定语标记“的”，应为“很常见的鸟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
