INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人对某件事怎么想，就是他的看法。", "primary_collocate": null, "pronunciation": "kàn fǎ", "ipa": "kʰan˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "你对这件事有什么看法？", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的看法和你不一样。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说说自己的看法吧。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很想听听学生的看法。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于搬家，爸爸的看法很简单。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他改变了看法，不再生气了。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对新同事，我还没有什么看法。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个看法很有道理，我同意。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的看法不同，所以吵了起来。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，每个人都要说出看法。", "target_word": "看法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个看法", "label": "量词"}, {"form": "一种看法", "label": "量词"}], "register": "中性", "sense_fingerprint": "看法：一个人对某事的想法和意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6750d34-8059-4248-b24c-0c46300c707b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22328, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "看法", "is_correct": true, "explanation": "正确。“看法”读作 kàn fǎ，指对某件事的想法和意见。"}, {"text": "砍伐", "is_correct": false, "explanation": "声调不同：“砍伐”读 kǎn fá，两个音节的声调都与 kàn fǎ 不同，“砍伐”的意思是砍树。"}, {"text": "砍法", "is_correct": false, "explanation": "声调不同：kǎn（第三声）与 kàn（第四声）声调不同，“砍法”的意思是砍的方法。"}, {"text": "刊发", "is_correct": false, "explanation": "声调不同：“刊发”读 kān fā，两个音节的声调都与 kàn fǎ 不同，“刊发”的意思是在报刊上发表。"}], "explanations": {"看法": "正确。“看法”读作 kàn fǎ，指对某件事的想法和意见。", "砍伐": "声调不同：“砍伐”读 kǎn fá，两个音节的声调都与 kàn fǎ 不同，“砍伐”的意思是砍树。", "砍法": "声调不同：kǎn（第三声）与 kàn（第四声）声调不同，“砍法”的意思是砍的方法。", "刊发": "声调不同：“刊发”读 kān fā，两个音节的声调都与 kàn fǎ 不同，“刊发”的意思是在报刊上发表。"}, "sentence_index": null, "correct_answer": "看法"}, "level_3": {"options": [{"text": "看法", "is_correct": true, "explanation": "正确。“对这件事有什么看法”是问对事情的观点，符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“这件事”没有价格，“有什么价格”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与对事情的态度无关，句子不通。"}, {"text": "风格", "is_correct": false, "explanation": "搭配：“风格”多用于艺术或做事方式，不能说“对这件事有什么风格”。"}], "explanations": {"看法": "正确。“对这件事有什么看法”是问对事情的观点，符合语境。", "价格": "语义：“这件事”没有价格，“有什么价格”不通。", "颜色": "语义：“颜色”与对事情的态度无关，句子不通。", "风格": "搭配：“风格”多用于艺术或做事方式，不能说“对这件事有什么风格”。"}, "sentence_index": 0, "correct_answer": "看法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事有一张看法。", "explanation": "这里应该用〈种〉或〈个〉。“张”用于纸、桌子等平面的东西，不用于计量“看法”。"}, {"text": "他把自己的看法放进了箱子里。", "explanation": "“看法”是人头脑中的想法，不是实物，不能放进箱子。"}, {"text": "他这次考试取得了很高的看法。", "explanation": "这里应该用〈成绩〉。“取得”搭配“成绩”，看法不能被取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看法", "is_correct": true, "explanation": "正确。“还没有什么看法”表示对新同事还没有形成观点，符合语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙与对人的态度无关，句子不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不能用来表示对人的态度。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“灯光”不能用来表示对人的态度，“没有什么灯光”不通。"}], "explanations": {"看法": "正确。“还没有什么看法”表示对新同事还没有形成观点，符合语境。", "钥匙": "语义：钥匙与对人的态度无关，句子不通。", "体温": "语义：体温不能用来表示对人的态度。", "灯光": "搭配：“灯光”不能用来表示对人的态度，“没有什么灯光”不通。"}, "sentence_index": 6, "correct_answer": "看法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们对这个方案有一座看法。", "explanation": "这里应该用〈个〉。“座”用于山、房屋等大型固定的东西，不用于计量“看法”。"}, {"text": "他把我们的看法擦干净了。", "explanation": "“擦”的对象应是有形的东西，看法是抽象的想法，不能擦。"}, {"text": "这件衣服的看法很漂亮。", "explanation": "这里应该用〈样子〉。“漂亮”形容东西的外观，看法是头脑中的想法，不能说漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这件事有一张独特的看法。", "corrected_sentence": "他对这件事有一种独特的看法。", "error_description": "“张”用于纸、桌子等平面的东西，不能用来计量“看法”。应该用“种”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家对这个方案的一块看法差别很大。", "corrected_sentence": "大家对这个方案的看法差别很大。", "error_description": "“块”用于块状的东西，不能用来计量“看法”。误句中的“一块”应去掉，说“的看法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻视", "is_correct": true, "explanation": "正确：“轻视”与“尊重”意思相反，指看不起别人、不重视对方。"}, {"text": "观察", "is_correct": false, "explanation": "无关：“观察”是仔细看，与“尊重”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "无关：“参加”指加入某项活动，与“尊重”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存物品，与“尊重”没有反义关系。"}], "correct_answer": "轻视", "explanations": {"轻视": "正确：“轻视”与“尊重”意思相反，指看不起别人、不重视对方。", "观察": "无关：“观察”是仔细看，与“尊重”没有反义关系。", "参加": "无关：“参加”指加入某项活动，与“尊重”没有反义关系。", "收藏": "无关：“收藏”指保存物品，与“尊重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻视", "is_correct": true, "explanation": "正确：“轻视”与“尊重”意思相反，指看不起别人、不重视对方。"}, {"text": "阅读", "is_correct": false, "explanation": "无关：“阅读”指看书、看文字，与“尊重”没有反义关系。"}, {"text": "思念", "is_correct": false, "explanation": "无关：“思念”是心理活动，与“尊重”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指修复物品，与“尊重”没有反义关系。"}], "correct_answer": "轻视", "explanations": {"轻视": "正确：“轻视”与“尊重”意思相反，指看不起别人、不重视对方。", "阅读": "无关：“阅读”指看书、看文字，与“尊重”没有反义关系。", "思念": "无关：“思念”是心理活动，与“尊重”没有反义关系。", "修理": "无关：“修理”指修复物品，与“尊重”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "尊敬别人，把别人看得重要。", "primary_collocate": null, "pronunciation": "zūn zhòng", "ipa": "tswən˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们要尊重老师。", "target_word": "尊重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请尊重别人的意见。", "target_word": "尊重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很尊重自己的父母。", "target_word": "尊重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师尊重每一个学生的想法。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她尊重孩子的选择，没有反对。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在别人家里，要尊重他们的习惯。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好朋友会互相尊重，不会说坏话。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都很尊重这位老医生。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不听我说话，就是不尊重我。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到别的国家旅行，要尊重那里的文化。", "target_word": "尊重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "尊重了", "label": "体标"}, {"form": "尊重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "尊敬他人，重视他人的想法和感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9733c-8de7-4445-b4c8-56f8fe774a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尊重", "is_correct": true, "explanation": "正确：“尊重”表示尊敬老师，与“我们要……老师”的语境相符。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”与尊敬老师的语境相反，“我们要欺负老师”不合常理。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”用于物品，不能用于老师，句子不通。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”搭配物品，不能说“搬运老师”。"}], "explanations": {"尊重": "正确：“尊重”表示尊敬老师，与“我们要……老师”的语境相符。", "欺负": "语义：“欺负”与尊敬老师的语境相反，“我们要欺负老师”不合常理。", "修理": "语义：“修理”用于物品，不能用于老师，句子不通。", "搬运": "搭配：“搬运”搭配物品，不能说“搬运老师”。"}, "sentence_index": 0, "correct_answer": "尊重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校一直尊重安全教育。", "explanation": "这里应该用〈重视〉。尊重用于人的想法、感受、选择，对事情的重要性要用〈重视〉。"}, {"text": "他尊重了那块面包。", "explanation": "这里应该用〈吃〉。尊重指看重人的想法、感受、文化等，不指吃东西；吃面包要用〈吃〉。"}, {"text": "他尊重了那个盒子。", "explanation": "这里应该用〈打开〉。尊重用于人的想法和感受，盒子要用〈打开〉，不能说“尊重盒子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊重", "is_correct": true, "explanation": "正确：“尊重”表示重视彼此，与“不会说坏话”的语境相符。"}, {"text": "偷窃", "is_correct": false, "explanation": "语义：“偷窃”与“好朋友”的意思相反，整句不通。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：摔倒是身体意外，与「互相尊重」的语境无关，「互相摔倒」说不通。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：迷路指找不着方向，与「互相尊重」的语境无关，「互相迷路」说不通。"}], "explanations": {"尊重": "正确：“尊重”表示重视彼此，与“不会说坏话”的语境相符。", "偷窃": "语义：“偷窃”与“好朋友”的意思相反，整句不通。", "摔倒": "语义：摔倒是身体意外，与「互相尊重」的语境无关，「互相摔倒」说不通。", "迷路": "语义：迷路指找不着方向，与「互相尊重」的语境无关，「互相迷路」说不通。"}, "sentence_index": 6, "correct_answer": "尊重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天都要尊重这台机器。", "explanation": "这里应该用〈维护〉。尊重用于对人的想法和感受，机器的保养要用〈维护〉。"}, {"text": "晚上他尊重窗外的雨声。", "explanation": "这里应该用〈欣赏〉。尊重不用于景色和声音，欣赏美好的事物才用〈欣赏〉。"}, {"text": "他每天都要尊重这扇窗户。", "explanation": "这里应该用〈擦〉。尊重用于人的想法和感受，窗户要用〈擦〉，不能说“尊重窗户”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该尊重了彼此的隐私。", "corrected_sentence": "我们应该尊重彼此的隐私。", "error_description": "体标错误：“应该”表示义务，尚未实现，不能与“了”同用，应说“应该尊重彼此的隐私”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该被尊重每个人的权利。", "corrected_sentence": "我们应该尊重每个人的权利。", "error_description": "被动误用：“尊重”后面已带宾语“每个人的权利”，不能再加“被”构成被动句，应去掉“被”，说“应该尊重每个人的权利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
